function etapasSemanas(N){
  const w = [0.1, 0.2, 0.3, 0.65, 0.9, 1];
  let prev = 0;
  return w.map(c => {
    const s = Math.min(N, Math.floor(prev * N) + 1);
    const e = Math.max(s, Math.ceil(c * N));
    prev = c;
    return [s, e];
  });
}
