const MESES = ["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];
const DIAS_SEM = ["domingo","lunes","martes","miércoles","jueves","viernes","sábado"];
const pad2 = n => String(n).padStart(2, "0");
const isoDe = d => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
const fechaDe = iso => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || ""); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; };
const dm = d => `${d.getDate()}/${d.getMonth() + 1}`;
const diaCorto = d => `${DIAS_SEM[d.getDay()]} ${dm(d)}`;
function estadoDiaBase(d){
  if (d.getDay() === 0 || d.getDay() === 6) return "fin de semana";
  const c = CAL[d.getFullYear()];
  if (!c) return null;
  const iso = isoDe(d);
  if (c.feriados[iso]) return c.feriados[iso];
  if (c.receso && iso >= c.receso[0] && iso <= c.receso[1]) return "receso invernal";
  if (c.inicio && iso < c.inicio) return "antes del inicio de clases";
  if (c.fin && iso > c.fin) return "después del cierre del ciclo lectivo";
  return null;
}
function diasDeClase(){ return val("dias").split(",").map(Number).filter(n => n >= 1 && n <= 5); }
