const KEEP_ON_NEW = ["institucion","docente","coformador","ciclo","lugar","semanas","clasesSemana","nclases","tiempo","dias","horas"];
const STORE_KEY = "planificador-clases-v2";

const EXAMPLE = {materia:"fisica", anio:"8", curso:"8.º A", tema:"Leyes de Newton", tiempo:"80 minutos", caracter:"Desarrollo"};

/* ============================================================
   Utilidades
   ============================================================ */
const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const norm = s => String(s).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const val = id => ($(id)?.value || "").trim();
const fill = (arr, t) => arr.map(s => gramFill(s, t));
const toList = arr => arr.map(s => "- " + s).join("\n");
const STOP = new Set(["para","sobre","entre","desde","como","clase","tema","unidad","introduccion","nocion","nociones","concepto","conceptos","primera","segunda","tercera","parte","cual","cuales"]);

function temaWords(tema){
  return norm(tema).split(/[^a-z0-9ñ]+/).filter(w => w.length > 3 && !STOP.has(w)).map(w => w.length > 5 ? w.slice(0, 5) : w);
}
function score(text, words){
  const n = norm(text);
  return words.reduce((acc, w) => acc + (n.includes(w) ? 1 : 0), 0);
}
function labelOf(id){
  const el = $(id);
  return el && el.value ? el.options[el.selectedIndex].text : "";
}
function fmtFecha(v){
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v || "");
  return m ? `${m[3]}/${m[2]}/${m[1]}` : "";
}
function minutos(txt){
  const s = norm(txt);
  if (!s) return null;
  let m = s.match(/(\d+)\s*(?:modulos?|horas? catedra|hs? catedra)\s*(?:de)?\s*(\d+)/);
  if (m) return (+m[1]) * (+m[2]);
  m = s.match(/(\d+(?:[.,]\d+)?)\s*(?:h|hs|hora|horas)\b/);
  if (m) return Math.round(parseFloat(m[1].replace(",", ".")) * 60);
  m = s.match(/(\d+)/);
  return m ? +m[1] : null;
}
function reparto(total){
  if (!total || total < 20) return null;
  const r5 = x => Math.max(5, Math.round(x / 5) * 5);
  const ini = r5(total * 0.2), cie = r5(total * 0.2);
  const des = total - ini - cie;
  return des > 0 ? {ini, des, cie} : null;
}

/* ============================================================
   Saberes y contenidos
   ============================================================ */
function autoSaberesBase(lista, tema){
  const words = temaWords(tema);
  if (!words.length) return [];
  const pun = lista.map((item, i) => { const c = item.indexOf(":"); return {i, s: score(item, words) + (c > 0 ? score(item.slice(0, c), words) : 0)}; });
  const mejor = Math.max(0, ...pun.map(x => x.s));
  return pun
    .filter(x => x.s > 0 && (x.s === mejor || (mejor < 3 && x.s >= mejor - 1 && words.length === 1)))
    .sort((a, b) => b.s - a.s)
    .slice(0, 2)
    .map(x => x.i)
    .sort((a, b) => a - b);
}
function contenidosDesdeBase(saberes, tema){
  const items = [];
  saberes.forEach(line => {
    line.replace(/\.\s*$/, "").split(/\.\s+/).forEach(sent => {
      const c = sent.indexOf(":");
      const body = c > -1 ? sent.slice(c + 1) : sent;
      const parts = body.split(",").map(s => s.trim()).filter(Boolean);
      const last = parts.pop();
      if (last){
        const yy = last.split(/\s+(?:y|e)\s+/);
        if (yy.length === 2 && yy[0].trim().split(/\s+/).length === 2 && /^[a-záéíóúñ]+(al|ico|ica|ivo|iva|ado|ada|ar|ino|ina|ano|ana|ente|ante)$/.test(yy[1].trim())) yy[1] = yy[0].trim().split(/\s+/)[0] + " " + yy[1].trim();
        parts.push(...yy);
      }
      items.push(...parts.map(p => p.trim()).filter(Boolean));
    });
  });
  const seen = new Set();
  const unicos = items.filter(x => { const k = norm(x); if (seen.has(k)) return false; seen.add(k); return true; });
  const words = temaWords(tema);
  const ordenados = unicos.map((x, i) => ({x, i, s: score(x, words)}))
    .sort((a, b) => (b.s > 0) - (a.s > 0) || a.i - b.i)
    .map(o => o.x);
  let lista = ordenados.slice(0, 7).map(cap);
  if (tema && words.length && !unicos.some(x => score(x, words) > 0)) lista = [cap(tema), ...lista.slice(0, 6)];
  return lista.length ? toList(lista) : "";
}

/* ============================================================
   Utilidades de proyecto (rúbrica, secuencia semanal, PLaNEA)
   ============================================================ */
function parseRubrica(txt){
  let rows = (txt || "").split("\n").map(l => l.trim()).filter(l => l.includes("|")).map(l => l.split("|").map(c => c.trim()));
  let head = null;
  if (rows.length && norm(rows[0][0]) === "criterio"){ head = rows[0]; rows = rows.slice(1); }
  rows = rows.filter(r => norm(r[0]) !== "criterio");
  if (!head){
    const n = Math.max(0, ...rows.map(r => r.length));
    head = n >= 5 ? ["Criterio", "Experto", "Avanzado", "Logrado", "En camino"] : ["Criterio", "Logrado", "En proceso", "Inicial"];
  }
  return {head, rows};
}
function parseSemanal(txt){
  return (txt || "").split("\n").map(l => l.trim()).filter(Boolean).map(l => {
    const m = l.match(/^Semanas?\s*([0-9][0-9\sya,-]*?)\s*[:|.–-]\s*(.+)$/i);
    return m ? [m[1].trim(), m[2].trim()] : ["", l.replace(/^[-•*·]\s*/, "")];
  });
}
function semanalGenerica(N, t){
  const Q = ["¿De qué se va a tratar nuestro proyecto?",
    `¿Qué sabemos sobre ${t} y qué necesitamos averiguar?`,
    "¿Cómo nos organizamos para resolver el desafío?",
    `¿Qué información encontramos sobre ${t}?`,
    "¿Cómo construimos el producto final?",
    "¿Cómo comunicamos lo que aprendimos?"];
  const Qb = [Q[0], Q[1], Q[2],
    `¿Qué preguntas sobre ${t} nos faltan responder y cómo sintetizamos lo encontrado?`,
    "¿Qué ajustes necesita el producto antes de presentarlo?", Q[5]];
  const sem = etapasSemanas(N), out = [];
  for (let w = 1; w <= N; w++){
    const cub = sem.map((r, i) => i).filter(i => sem[i][0] <= w && w <= sem[i][1]);
    const ini = cub.filter(i => sem[i][0] === w);
    out.push(`Semana ${w}: ` + (ini.length ? ini.map(i => Q[i]).join(" ") : Qb[cub[cub.length - 1]]));
  }
  return out.join("\n");
}
const sinPunto = x => (x || "").trim().replace(/\.$/, "");
function contItems(c){
  const txt = (c || "").replace(/•/g, " ").replace(/\s+/g, " ").trim();
  const parts = txt.split(/\.\s+/).map(sinPunto).filter(Boolean);
  if (parts.length > 1 && !/\.$/.test(txt)) parts.pop();
  return parts;
}
const lcFirst = x => x ? x[0].toLowerCase() + x.slice(1) : x;
function planeaSel(){ return state.planea ? PLANEA.find(p => p.k === state.planea) || null : null; }
const planeaCita = p => `«${p.t}», PLaNEA ${PLANEA_AREAS[p.a]}, ${p.y}.º año`;

/* ============================================================
   Sugerencias
   ============================================================ */
function sugerencias(ctx){
  const o = mejorarClase(sugerenciasBase(ctx), ctx);
  if (o) o.rubrica_est = rubricaEstudiante(state.edited.rubrica ? val("rubrica") : o.rubrica);
  const integ = state.integra.filter(m => m !== ctx.materia);
  if (o && integ.length && (state.modo === "clase" || state.modo === "secuencia")){
    const t = ctx.tema || "el tema";
    o.int_aportes = toList([ctx.materia, ...integ].filter(m => APORTES[m]).map(m => `${nombreMateria(m)}: ${APORTES[m]}`));
    o.int_acuerdos = toList([`Definir con los docentes de ${listaNatural(integ.map(nombreMateria))} una pregunta o un problema común sobre ${t}.`,
      "Acordar los momentos de trabajo conjunto (clases compartidas o pareja pedagógica) y qué coordina cada docente.",
      "Diseñar una producción final común, evaluada con criterios de cada espacio.",
      "Registrar los acuerdos y revisarlos al terminar."]);
  }
  return o;
}
function sugerenciasBase(ctx){
  const g = GEN[ctx.materia];
  if (!g) return null;
  const t = state.modo === "anual" ? `los saberes de ${nombreMateria(ctx.materia)}${ctx.anio ? " de " + anioSec(ctx.anio) : ""}` : temaArt(ctx.tema || "el tema de la clase");
  const L = arr => toList(fill(arr, t));
  const contenidosSug = contenidosDesde(ctx.saberes, ctx.tema);
  const critArr = fill(["Usa correctamente los conceptos y el vocabulario específico vinculados con {t}.", g.cri,
                  "Fundamenta sus respuestas y procedimientos.",
                  "Participa en el trabajo grupal con respeto y compromiso.",
                  "Revisa y mejora sus producciones a partir de las devoluciones."], t);
  return {
    contenidos: contenidosSug,
    propositos: L(g.prop),
    objetivos: L(g.obj),
    capacidades: L(g.cap),
    competencias: g.comp,
    inicio: L(g.ini),
    desarrollo: L(g.des),
    cierre: L(g.cie),
    apoyo: L(DIF.apoyo),
    general: L(DIF.general),
    avanzada: L(DIF.avanzada),
    adecuaciones: L(DIF.adec),
    diagnostica: L(EV.diag),
    formativa: L(EV.form),
    sumativa: L([g.sum, "Se tiene en cuenta además el proceso registrado durante las clases."]),
    instrumentos: L([...g.ins, "Registro de observación de clase", "Lista de cotejo para el trabajo grupal"]),
    criterios: L(["Usa correctamente los conceptos y el vocabulario específico vinculados con {t}.", g.cri,
                  "Fundamenta sus respuestas y procedimientos.",
                  "Participa en el trabajo grupal con respeto y compromiso.",
                  "Revisa y mejora sus producciones a partir de las devoluciones."]),
    recursos: L(g.rec),
    nap: napAuto(ctx, contenidosSug),
    ...sugerenciasExtra(ctx, g, t, state.edited.contenidos ? val("contenidos") : contenidosSug, critArr),
    ...sugerenciasAnual(ctx, g),
    ...sugerenciasProyecto(ctx, g, t, L),
    ...sugerenciasSecuencia(ctx, g, ctx.tema || "el tema", state.edited.contenidos ? val("contenidos") : contenidosSug)
  };
}
function itemsLista(txt){
  return (txt || "").split("\n").map(l => l.replace(/^\s*(?:[-•*·]|\d+[.)])\s+/, "").replace(/\.$/, "").trim()).filter(l => l && !/^(procedimientos|actitudes|valores)\s*:/i.test(l));
}
function planSecuencia(N, t, items, g, p){
  const cont = items.length ? items : [t];
  const out = [];
  out.push({t:`Problematización e ideas previas sobre ${t}`,
    a:[`Situación disparadora vinculada con ${t} y preguntas para abrir el tema.`,
       "Registro de ideas previas con la rutina «Veo, pienso, me pregunto».",
       "Presentación del recorrido de la secuencia y de los criterios de evaluación."],
    e:"Registro de ideas previas y preguntas del grupo"});
  const D = N <= 3 ? 1 : N - 3;
  const evid = ["Ticket de salida con una pregunta clave", "Guía de actividades resuelta y corregida en clase",
                "Informe breve de la experiencia o actividad", "Resolución de situaciones problemáticas en parejas"];
  for (let k = 0; k < D; k++){
    const c = cont[k % cont.length], rep = k >= cont.length;
    const des = fill([g.des[k % g.des.length]], lcFirst(c))[0];
    out.push({t: rep ? `Profundización: ${lcFirst(c)}` : c,
      a:[rep ? `Nuevas situaciones para profundizar ${lcFirst(c)} a partir de ${p.inv}.` : `Exploración de ${lcFirst(c)} a partir de ${p.inv}.`,
         des,
         `Puesta en común: se sistematizan en el pizarrón las ideas centrales sobre ${lcFirst(c)}.`],
      e:evid[k % evid.length]});
  }
  if (N > 3) out.push({t:`Integración: ${t}`,
    a:["Actividad integradora que relaciona los contenidos trabajados en la secuencia.",
       "Elaboración grupal de un mapa conceptual o de una síntesis.",
       "Repaso orientado por los criterios de evaluación y consultas."],
    e:"Mapa conceptual o síntesis grupal (evaluación formativa)"});
  out.push({t:"Evaluación y cierre de la secuencia",
    a:["Instancia de evaluación sumativa, según lo previsto en «Evaluación».",
       "Devolución y corrección compartida de la evaluación.",
       `Reflexión sobre lo aprendido acerca de ${t} con la rutina «Puente 3-2-1».`],
    e:sinPunto(fill([g.sum], t)[0])});
  return out.slice(0, N);
}
function sugerenciasSecuencia(ctx, g, t, contTxt){
  const N = +val("nclases") || 5;
  const sq = secuenciaConCriterios(ctx, g, t, itemsLista(contTxt));
  const o = {fundsec:sq ? sq.fund : "", fundepi:sq ? sq.fundepi : "", objgen:sq ? sq.objgen : ""};
  for (let n = 1; n <= 10; n++){
    const c = sq && sq.clases[n - 1];
    o[`sc${n}_t`] = c ? c.t : "";
    o[`sc${n}_a`] = c ? c.a : "";
    o[`sc${n}_e`] = c ? c.e : "";
  }
  if (state.modo === "secuencia"){
    const caso = val("caso");
    if (sq && sq.objetivos && sq.objetivos.length) o.objetivos = toList(sq.objetivos);
    o.sumativa = toList([caso ? `Informe grupal del problema de cierre (clase ${N}): ${lcFirst(sinPunto(caso))}, evaluado con rúbrica.` : `Evaluación sumativa en la clase ${N}: ${lcFirst(sinPunto(fill([g.sum], t)[0]))}.`, "Se consideran además las evidencias de aprendizaje registradas en cada clase."]);
    o.formativa = toList(["Seguimiento de la evidencia prevista en cada clase (tickets de salida, guías, informes).", "Devoluciones orales y escritas durante las actividades.", "Autoevaluación al cierre de la secuencia."]);
  }
  return o;
}
const nombreMateria = id => (MATERIAS.find(m => m[0] === id) || ["", ""])[1];
function listaNatural(arr){
  if (arr.length < 2) return arr.join("");
  return arr.slice(0, -1).join(", ") + " y " + arr[arr.length - 1];
}
function sugerenciasProyecto(ctx, g, t, L){
  const p = PROY[ctx.materia];
  const pl = planeaSel();
  const N = +val("semanas") || 6;
  const sem = etapasSemanas(N);
  const integra = state.integra.filter(m => m !== ctx.materia);
  const espacios = [ctx.materia, ...integra];
  const integraTxt = integra.length ? `, en diálogo con ${listaNatural(integra.map(nombreMateria))},` : "";
  const proy = state.modo === "proyecto";
  const sl = r => semLabel(r).toLowerCase();
  const pregunta = val("nombre") || fill([p.preg], t)[0];
  const producto = pl ? pl.prod : fill([p.prod], t)[0];
  const out = {
    pregunta: `${/[?!.]$/.test(pregunta) ? pregunta : pregunta + "."} Para responderla, los equipos investigan y elaboran un producto que presentan ante una audiencia de fuera del aula: ${lcFirst(sinPunto(producto))}.`,
    fundamentacion: [
      pl ? `El proyecto toma como base ${planeaCita(pl)}, de los cuadernillos elaborados por UNICEF y el Ministerio de Educación de Tucumán, y lo adapta a las características del grupo. Se busca que los saberes de ${nombreMateria(ctx.materia)}${integraTxt} se pongan en juego para resolver un desafío vinculado con ${t} y que el trabajo termine en un producto que se comparte con una audiencia real.`
         : `El proyecto aborda ${t} a partir de una pregunta vinculada con la vida cotidiana de los estudiantes. Se busca que los saberes de ${nombreMateria(ctx.materia)}${integraTxt} se pongan en juego para resolver un desafío concreto, y que el trabajo termine en un producto que se comparte con una audiencia real.`,
      `La propuesta sigue las seis fases del aprendizaje basado en proyectos de PLaNEA, desde la presentación del desafío hasta la presentación del producto final, con evaluación formativa y momentos de metaaprendizaje a lo largo de todo el proceso. El trabajo en equipos con roles definidos favorece la autonomía, la responsabilidad compartida y la comunicación de lo aprendido.`
    ].join("\n"),
    producto,
    intermedios: L(["Registro de saberes previos y preguntas del equipo.",
                    "Plan de trabajo con tareas, roles y plazos.",
                    "Síntesis de la información sobre {t} (fichas, cuadros o esquemas), corregida con devolución del docente.",
                    "Borrador o prototipo del producto final, revisado con la rúbrica."]),
    difusion: L(["Presentación del producto ante una audiencia de fuera del aula: otros cursos, familias o la comunidad.",
                 "Publicación del producto en los canales de la escuela (cartelera, blog o redes institucionales)."]),
    aportes: toList(espacios.map(m => `${nombreMateria(m)}: ${APORTES[m]}`)),
    semanal: pl ? pl.sem.join("\n") : semanalGenerica(N, t),
    etapa1: L(["Situación disparadora vinculada con {t} y presentación del título y del desafío del proyecto.",
               "Presentación del producto final, de la audiencia y de la rúbrica con la que se va a evaluar.",
               "Conformación de equipos de 4 o 5 estudiantes."]),
    etapa2: L(["Rutina de pensamiento para recuperar ideas previas (por ejemplo, «Veo, pienso, me pregunto»).",
               "Cuadro de lo que sabemos y lo que necesitamos saber para resolver el desafío.",
               "Formulación de las preguntas que va a responder cada equipo."]),
    etapa3: L(["Reparto de roles en cada equipo: facilitador, secretario, portavoz e investigador.",
               "Plan de trabajo con tareas, plazos y materiales.",
               "Inicio del diario de equipo."]),
    etapa4: L([`Búsqueda y análisis de información sobre {t} a partir de ${p.inv}.`,
               ...(pl ? [`Actividades de las semanas correspondientes del cuadernillo «${pl.t}».`] : []),
               "Clases breves del docente para sistematizar los conceptos que el proyecto necesita.",
               "Estructuras cooperativas (lápiz al centro, 1-2-4, rompecabezas) para trabajar y sintetizar la información.",
               "Entrega de productos intermedios con devolución del docente."]),
    etapa5: L(["Boceto del producto y acuerdo sobre su formato.",
               integra.length ? "Producción en equipos, con consultas a los docentes de los espacios que integran el proyecto." : "Producción en equipos, con seguimiento y devoluciones del docente en cada clase.",
               "Revisión entre equipos con la rúbrica y ajustes a partir de las devoluciones."]),
    etapa6: L(["Presentación del producto final ante la audiencia prevista.",
               "Autoevaluación y coevaluación con la rúbrica; cierre del diario de equipo.",
               "Metaaprendizaje: qué aprendimos sobre {t}, cómo lo aprendimos y qué haríamos distinto (Puente 3-2-1)."]),
    organizacion: toList([
      "Equipos de 4 o 5 estudiantes con roles rotativos: facilitador, secretario, portavoz e investigador.",
      "Diario de equipo, completado al final de cada clase y revisado por el docente cada semana.",
      "Estructuras cooperativas según la actividad: hoja giratoria, 1-2-4, lápiz al centro, rompecabezas o carrusel.",
      `Hitos: plan de trabajo (${sl(sem[2])}), productos intermedios (${sl(sem[3])}), primera versión del producto (${sl([Math.max(sem[4][0], sem[4][1] - 1), Math.max(sem[4][0], sem[4][1] - 1)])}) y presentación final (${sl([N, N])}).`
    ]),
    rubrica: [
      "Criterio | Experto | Avanzado | Logrado | En camino",
      `Comprensión de ${t} | Explica los conceptos con precisión, los relaciona y los aplica a situaciones nuevas | Explica los conceptos con precisión y los aplica al desafío | Explica los conceptos con algunas imprecisiones | Menciona conceptos aislados sin relacionarlos con el desafío`,
      "Búsqueda y síntesis de información | Usa fuentes variadas, las contrasta y sintetiza con sus palabras | Usa fuentes variadas y sintetiza la información | Usa pocas fuentes y copia parte de la información | No registra fuentes o copia sin seleccionar",
      "Producto final | Resuelve el desafío con originalidad y es claro para la audiencia | Resuelve el desafío y es claro para la audiencia | Resuelve parcialmente el desafío | No resuelve el desafío",
      "Planificación | Cumple los plazos y ajusta el plan cuando hace falta | Cumple los plazos del plan de trabajo | Cumple algunos plazos con recordatorios | No cumple los plazos acordados",
      "Colaboración | Cumple su rol, ayuda a otros y propone mejoras | Cumple su rol y colabora con el equipo | Cumple su rol con ayuda | Participa poco en las tareas del equipo",
      "Comunicación | Presenta con claridad, adapta el lenguaje a la audiencia y fundamenta | Presenta con claridad y responde preguntas | Presenta con claridad, pero le cuesta fundamentar | Lee o repite sin explicar"
    ].join("\n")
  };
  if (!proy) delete out.rubrica;
  if (proy){
    out.propositos = L([...g.prop, `Organizar el trabajo en torno a un desafío real que dé sentido a los saberes de ${listaNatural(espacios.map(nombreMateria))}.`]);
    out.objetivos = pl ? toList(pl.metas)
      : L([...g.obj, "Elaborar en equipo un producto que responda al desafío y comunicarlo a una audiencia real."]);
    out.capacidades = L(["Planificación: organizar el trabajo, anticipar tareas y administrar el tiempo del equipo.",
                         "Resolución de problemas: analizar el desafío, buscar información y tomar decisiones fundamentadas sobre {t}.",
                         "Comunicación: expresar ideas y resultados con claridad ante distintas audiencias.",
                         "Colaboración: trabajar con otros, sostener un rol y valorar los aportes del equipo."]);
    if (pl && contItems(pl.cont).length) out.contenidos = toList(contItems(pl.cont));
    out.diagnostica = L(["Indagación de ideas previas sobre {t} en la fase de análisis de conocimientos previos.",
                         "Registro de intereses y necesidades del grupo para ajustar el alcance del proyecto."]);
    out.formativa = L(["Revisión semanal del diario de equipo, con devoluciones escritas.",
                       "Corrección de los productos intermedios con la rúbrica.",
                       "Rutinas de pensamiento al cierre de las clases (ticket de salida).",
                       "Coevaluación entre equipos antes de la presentación final."]);
    out.sumativa = L(["Evaluación del producto final y de su presentación con la rúbrica del proyecto.",
                      "Se consideran también los productos intermedios, el diario de equipo y la autoevaluación."]);
    out.instrumentos = L(["Rúbrica del proyecto", "Diario de equipo", "Lista de cotejo de productos intermedios",
                          "Escala de valoración del trabajo en equipo", "Diana de autoevaluación",
                          "Rutinas de pensamiento: ticket de salida y Puente 3-2-1"]);
    out.criterios = L(["Usa correctamente los conceptos y el vocabulario específico vinculados con {t}.", g.cri,
                       "Fundamenta las decisiones tomadas en el producto final.",
                       "Cumple los plazos acordados y sostiene su rol en el equipo.",
                       "Revisa y mejora sus producciones a partir de las devoluciones."]);
  }
  return out;
}

