const NOV_KEY = "planificador-novedades-visto";
function renderNovedades(){
  const u = NOVEDADES[0];
  if (!u) return;
  let visto = "";
  try { visto = localStorage.getItem(NOV_KEY) || ""; } catch (e) { logSilencioso(e); }
  if (visto === (u.id || u.fecha)) return;
  const [y, m, d] = u.fecha.split("-");
  $("nov-t").textContent = `Novedades del ${+d}/${+m}/${y}`;
  $("nov-list").innerHTML = u.items.map(i => `<li>${esc(i)}</li>`).join("");
  $("nov").hidden = false;
}


