  const run = (t, sz, o = {}) => `<a:r><a:rPr lang="es-AR" sz="${sz}"${o.b ? ' b="1"' : ""}${o.i ? ' i="1"' : ""} dirty="0"><a:solidFill><a:srgbClr val="${o.color || "1C1D1B"}"/></a:solidFill><a:latin typeface="Calibri"/></a:rPr><a:t>${x(t)}</a:t></a:r>`;
