/* ============================================================
   PDF (jsPDF, se carga solo cuando se pide)
   ============================================================ */
let jsPDFCarga = null;
function cargarJsPDF(){
  if (window.jspdf && window.jspdf.jsPDF) return Promise.resolve(window.jspdf.jsPDF);
  /* Si la librería viene incluida en la página (versión sin conexión), se activa acá, sin red */
  try {
    const inc = document.getElementById("jspdf-lib");
    if (inc && inc.textContent.length > 1000){
      const sc = document.createElement("script"); sc.textContent = inc.textContent;
      document.head.appendChild(sc); sc.remove();
      if (window.jspdf && window.jspdf.jsPDF) return Promise.resolve(window.jspdf.jsPDF);
    }
  } catch (e) { logSilencioso(e); }
  if (!jsPDFCarga) jsPDFCarga = new Promise((res, rej) => {
    const sc = document.createElement("script");
    sc.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    sc.onload = () => (window.jspdf && window.jspdf.jsPDF) ? res(window.jspdf.jsPDF) : rej(new Error("jspdf"));
    sc.onerror = () => { jsPDFCarga = null; rej(new Error("red")); };
    document.head.appendChild(sc);
  });
  return jsPDFCarga;
}
const PDF_MAP = {"…":"...", "–":"-", "—":"-", "“":'"', "”":'"', "‘":"'", "’":"'", "•":"-", "≥":">=", "≤":"<=", "−":"-", "→":"->", "↑":"", "↓":""};
const pdfTxt = s => pdfTxt2(s);
async function jpegDe(src){
  try {
    const im = await loadImg(src);
    const c = document.createElement("canvas");
    c.width = im.naturalWidth || 1200; c.height = im.naturalHeight || 900;
    const g = c.getContext("2d"); g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height); g.drawImage(im, 0, 0, c.width, c.height);
    return {data:c.toDataURL("image/jpeg", 0.88), w:c.width, h:c.height};
  } catch (e) { return null; }
}
async function pdfDe(M){
  const J = await cargarJsPDF();
  const doc = new J({unit:"pt", format:"a4"});
  const W = 595.28, H = 841.89, MX = 64, MY = 60, CW = W - 2 * MX;
  const F = state.docFont === "sans" ? "helvetica" : "times";
  let y = MY;
  const need = h => { if (y + h > H - MY){ doc.addPage(); y = MY; } };
  const txt = (s, o = {}) => {
    const size = o.size || 10.5, lh = size * (o.lh || 1.38), ind = o.ind || 0;
    doc.setFont(F, o.style || "normal"); doc.setFontSize(size);
    const col = o.color || [28, 29, 27]; doc.setTextColor(col[0], col[1], col[2]);
    const lines = doc.splitTextToSize(pdfTxt(s), CW - ind);
    lines.forEach((ln, i) => {
      need(lh);
      if (i === 0 && o.bullet){ doc.setFillColor(60, 60, 60); doc.circle(MX + ind - 8, y + size * 0.62, 1.4, "F"); }
      if (o.align === "center") doc.text(ln, MX + CW / 2, y + size * 0.85, {align:"center"});
      else if (o.align === "right") doc.text(ln, MX + CW, y + size * 0.85, {align:"right"});
      else doc.text(ln, MX + ind, y + size * 0.85);
      y += lh;
    });
    y += o.after == null ? 3 : o.after;
  };
  const bloque = (body, falta) => {
    if (!body){ txt(`[${falta || "Completar"}]`, {color:[150, 110, 0]}); return; }
    body.split("\n").map(l => l.trim()).filter(Boolean).forEach(l => {
      const m = l.match(/^(?:[-•*·]|\d+[.)])\s+(.*)$/);
      if (m) txt(m[1], {ind:14, bullet:true, after:2}); else txt(l);
    });
  };
  const tabla = (head, rows, wIn) => {
    const n = head.length;
    const base = wIn && wIn.length === n ? wIn : n === 2 ? [1500, 7570] : n === 3 ? [3500, 1500, 4070] : [n >= 5 ? 2470 : 1900, ...Array(n - 1).fill(1)];
    const sum = base.reduce((a, b) => a + b, 0);
    let ws = base.map(b => b / sum * CW);
    if (!(wIn && wIn.length === n) && n > 3){ const f = (n >= 5 ? 2470 : 1900) / 9070 * CW; ws = [f, ...Array(n - 1).fill((CW - f) / (n - 1))]; }
    const size = 8.8, lh = size * 1.3, pad = 4;
    const fila = (cells, hdr) => {
      doc.setFont(F, hdr ? "bold" : "normal"); doc.setFontSize(size);
      const ls = cells.map((c, i) => doc.splitTextToSize(pdfTxt(c || ""), ws[i] - 2 * pad));
      const h = Math.max(...ls.map(l => l.length), 1) * lh + 2 * pad;
      return {ls, h, hdr};
    };
    const dibujar = (f) => {
      let x0 = MX;
      if (f.hdr){ doc.setFillColor(238, 242, 240); doc.rect(MX, y, CW, f.h, "F"); }
      doc.setDrawColor(191, 199, 195); doc.setLineWidth(0.5);
      f.ls.forEach((l, i) => {
        doc.rect(x0, y, ws[i], f.h);
        doc.setTextColor(28, 29, 27); doc.setFont(F, f.hdr ? "bold" : "normal"); doc.setFontSize(size);
        l.forEach((ln, k) => doc.text(ln, x0 + pad, y + pad + size * 0.85 + k * lh));
        x0 += ws[i];
      });
      y += f.h;
    };
    const fh = fila(head, true);
    need(fh.h + 20); dibujar(fh);
    rows.forEach(r => { const f = fila(head.map((_, i) => r[i] || ""), false); if (y + f.h > H - MY){ doc.addPage(); y = MY; dibujar(fh); } dibujar(f); });
    y += 8;
  };
  const figura = async ({img, n}) => {
    const j = await jpegDe(img.png || img.src);
    const cap = `Figura ${n}. ${img.caption || ""}`.trim();
    if (!j){ txt(`[${cap}]`); return; }
    let w = Math.min(CW * 0.8, 380), h = w * j.h / j.w;
    if (h > 300){ h = 300; w = h * j.w / j.h; }
    need(h + 24);
    doc.addImage(j.data, "JPEG", MX + (CW - w) / 2, y, w, h);
    y += h + 4;
    txt(cap, {size:8.8, color:[90, 90, 90], align:"center", after:8});
  };
  const lineas = n => { doc.setDrawColor(160, 160, 160); doc.setLineWidth(0.5); for (let i = 0; i < n; i++){ need(22); y += 20; doc.line(MX, y, MX + CW, y); } y += 10; };
  // encabezado
  const E = state.enc || {};
  if (E.logo || E.texto){
    let tx = MX;
    if (E.logo){ const j = await jpegDe(E.logo); if (j){ const h = 40, w = h * j.w / j.h; doc.addImage(j.data, "JPEG", MX, y, w, h); tx = MX + w + 10; } }
    doc.setFont(F, "normal"); doc.setFontSize(8.8); doc.setTextColor(90, 90, 90);
    (E.texto || "").split("\n").filter(Boolean).forEach((l, i) => doc.text(pdfTxt(l), tx, y + 14 + i * 12));
    y += 48; doc.setDrawColor(210, 215, 212); doc.line(MX, y, MX + CW, y); y += 12;
  }
  txt((M.inst || "[Institución]").toUpperCase(), {size:8.5, color:[90, 90, 90], after:4});
  txt(M.titulo, {size:18, style:"bold", after:2});
  txt(M.subtitulo || `[${M.faltaSub}]`, {size:12.5, after:12});
  doc.setDrawColor(210, 215, 212); doc.setLineWidth(0.5);
  M.datos.forEach(([k, v]) => {
    doc.setFontSize(9.5);
    const ls = doc.splitTextToSize(pdfTxt(v || "[Completar]"), CW * 0.62);
    const h = ls.length * 13 + 8;
    need(h);
    doc.setFont(F, "bold"); doc.setTextColor(90, 90, 90); doc.text(pdfTxt(k), MX, y + 12);
    doc.setFont(F, "normal"); doc.setTextColor(28, 29, 27); ls.forEach((l, i) => doc.text(l, MX + CW * 0.36, y + 12 + i * 13));
    y += h; doc.line(MX, y, MX + CW, y);
  });
  y += 14;
  for (const sec of M.secs){
    if (sec.pageBreak){ doc.addPage(); y = MY; }
    need(sec.sinH ? 16 : 40);
    if (sec.h && !sec.sinH) txt(sec.h.toUpperCase(), {size:9.8, style:"bold", after:5});
    if (sec.lead) txt(sec.lead, {style:"italic"});
    if (sec.table) tabla(sec.table.head, sec.table.rows, sec.table.w);
    if (sec.onlyFigs){ for (const f of sec.figs || []) await figura(f); }
    else if (sec.tableOnly) {}
    else if (sec.quote) txt(sec.body || "[Completar]", {size:12, style:"italic", after:8});
    else if (sec.sub){
      for (const sb of sec.sub){
        need(30);
        txt(sb.h, {size:10.5, style:"bold", after:3});
        if ("rubrica" in sb){ const {head, rows} = parseRubrica(sb.rubrica); if (rows.length) tabla(head, rows); else txt("[Completar la rúbrica]"); }
        else {
          if (sb.body || !sb.lineas) bloque(sb.body, sb.falta);
          if (sb.lineas) lineas(sb.lineas);
          for (const f of sb.figs || []) await figura(f);
        }
      }
    } else if (sec.der || sec.ref){
      (sec.body || "").split("\n").filter(l => l.trim()).forEach(l => txt(l, sec.der ? {align:"right"} : {style:"bold"}));
    } else {
      if (sec.body || !(sec.links && sec.links.length)) bloque(sec.body, sec.falta);
      (sec.links || []).forEach(c => txt(`${c.f}. ${c.t}. ${c.u}`, {ind:14, bullet:true, after:2}));
    }
    y += sec.sinH ? 4 : 6;
  }
  if (M.firmas){
    const wf = CW / 2 - 20;
    M.firmas.forEach(([n, r], j) => {
      const i = j % 2;
      if (i === 0){ need(90); y += j ? 50 : 60; }
      const x0 = MX + i * (wf + 40);
      doc.setDrawColor(40, 40, 40); doc.line(x0, y, x0 + wf, y);
      doc.setFont(F, "normal"); doc.setFontSize(9.5); doc.setTextColor(28, 29, 27);
      doc.text(pdfTxt(n || ""), x0 + wf / 2, y + 13, {align:"center"});
      doc.setTextColor(90, 90, 90); doc.setFontSize(8.5); doc.text(pdfTxt(r), x0 + wf / 2, y + 25, {align:"center"});
    });
  }
  const np = doc.getNumberOfPages();
  for (let i = 1; i <= np; i++){ doc.setPage(i); doc.setFont(F, "normal"); doc.setFontSize(8.5); doc.setTextColor(120, 120, 120); doc.text(String(i), W - MX, H - 32, {align:"right"}); }
  return doc.output("blob");
}
async function descargarPDFV64(){
  const btn = $("btn-pdf");
  if (btn.disabled) return;
  btn.disabled = true; const t0 = btn.textContent; btn.textContent = "Preparando…";
  try {
    await Promise.all(state.images.map(rasterize));
    const M = modeloActual();
    const blob = await pdfDe(M);
    const pref = {ficha:"ficha", inst:"instrumentos", registro:"registro", libreto:"libreto"}[vistaEfectiva()] || state.modo;
    await guardarArchivo(`${pref}-${slug(M.subtitulo || "planificacion")}.pdf`, blob, "PDF descargado.");
  } catch (e) {
    toast(e && e.message === "red" ? "No se pudo cargar el generador de PDF (hace falta conexión). Probá con «Descargar Word»." : "No se pudo armar el PDF. Probá con «Descargar Word».");
  } finally { btn.disabled = false; btn.textContent = t0; }
}
async function descargarPPTX(){
  const btn = $("btn-docx");
  btn.disabled = true; const t0 = btn.textContent; btn.textContent = "Preparando…";
  try {
    await Promise.all(state.images.map(rasterize));
    const blob = zipStore(await pptxArchivos());
    const b2 = new Blob([blob], {type:"application/vnd.openxmlformats-officedocument.presentationml.presentation"});
    await guardarArchivo(`presentacion-${slug(temaVisible() || "clase")}.pptx`, b2, "Presentación descargada.");
  } catch (e) { toast("No se pudo armar la presentación."); }
  finally { btn.disabled = false; btn.textContent = t0; }
}

/* ============================================================
   Planilla de seguimiento del curso (local, por planificación)
   ============================================================ */
const SEG_KEY = "planificador-seguimiento-v1";
function segTodo(){ try { const s = JSON.parse(localStorage.getItem(SEG_KEY) || "{}"); return s && typeof s === "object" ? s : {}; } catch (e) { return {}; } }
const esNum = v => v !== "" && v != null && !isNaN(parseFloat(String(v).replace(",", ".")));
const aNum = v => parseFloat(String(v).replace(",", "."));
const state = {tabs:{}, condSel:0, infSel:0, ppiSel:"", rutFiltro:"todas", opcAbiertas:false, edited:{}, saberesSel:null, saberesKey:"", lastAuto:[], lista:[], accent:"verde", docFont:"serif", example:false, images:[], recursos:[], catAll:false, modo:"clase", integra:[], planea:"", plAll:false, plNombre:"", plTema:"", planId:"", libBorrados:{}, vista:"plan", zoom:1, contraste:false, enc:{logo:"", texto:"", w:0, h:0}};
const caps = {sample:null, downloads:null, inClaude: !!(window.claude && window.claude.use)};

/* ============================================================
   Construcción del formulario
   ============================================================ */
function fieldHTML(f){
  if (f.type === "saberes"){
    return `<div class="f full">
      <div class="f-head"><span class="lbl" id="saberes-lbl">Saberes del diseño curricular</span></div>
      <p class="hint" id="saberes-hint"></p>
      <div class="chips" id="saberes" role="group" aria-labelledby="saberes-lbl"></div>
    </div>`;
  }
  if (f.type === "timehint") return `<p class="timehint" id="timehint" hidden></p>`;
  if (f.type === "napsel") return `<div class="f full"><div class="f-head"><span class="lbl" id="nap-lbl">Núcleos de Aprendizajes Prioritarios (NAP)</span></div><div id="nap-box" role="group" aria-labelledby="nap-lbl"></div></div>`;
  if (f.type === "libreto") return `<div class="f full lb-entrada" data-solo="${f.solo}"><button type="button" class="btn btn-sm" data-abrirlb>¿Tenés un libreto o cuadernillo? Armá las clases desde el texto</button></div>`;
  if (f.type === "etapahint") return `<p class="timehint" id="etapahint"></p>`;
  if (f.type === "sechint") return `<p class="timehint" id="sechint"></p>`;
  const soloA = f.solo ? ` data-solo="${f.solo}"` : "";
  if (f.type === "nota"){
    return `<div class="nota full"${soloA}><p class="timehint" id="${f.id}"></p>${f.vista ? `<button type="button" class="btn btn-sm" data-vervista="${f.vista}">Ver en el documento</button>` : ""}</div>`;
  }
  if (f.type === "dias"){
    return `<div class="f full"${soloA}><div class="f-head"><span class="lbl" id="dias-lbl">${esc(f.label)}</span></div><input type="hidden" id="dias">
      <div class="chips chips-row" role="group" aria-labelledby="dias-lbl">${[[1,"Lunes"],[2,"Martes"],[3,"Miércoles"],[4,"Jueves"],[5,"Viernes"]].map(([n, l]) => `<button type="button" class="chip chip-sm" data-dia="${n}" aria-pressed="false">${l}</button>`).join("")}</div>
      <p class="hint">Con la fecha de inicio y los días de clase se calcula la fecha de cada clase, salteando feriados y el receso.</p></div>`;
  }
  if (f.type === "instsel" || f.type === "transv"){
    const ops = f.type === "instsel" ? [["rubrica","Rúbrica"],["rubricaest","Rúbrica para estudiantes"],["cotejo","Lista de cotejo"],["escala","Escala de valoración"],["ticket","Ticket de salida"]] : [["esi","Educación Sexual Integral"],["eai","Educación Ambiental Integral"],["edig","Educación digital e IA"]];
    const lbl = f.type === "instsel" ? "Instrumentos que vas a usar" : "Ejes que se trabajan en esta planificación";
    return `<div class="f full"><div class="f-head"><span class="lbl" id="${f.id}-lbl">${lbl}</span></div><input type="hidden" id="${f.id}">
      <div class="chips chips-row" role="group" aria-labelledby="${f.id}-lbl">${ops.map(([v, l]) => `<button type="button" class="chip chip-sm" data-${f.type}="${v}" aria-pressed="false">${l}</button>`).join("")}</div></div>`;
  }
  if (f.type === "claude"){
    return `<div class="f full claude-row" data-claude-box${soloA} hidden><div class="claude-in"><button type="button" class="btn btn-sm" data-claude="${f.acc}">${esc(f.label)}</button><span class="hint" id="cl-st-${f.acc}" role="status"></span></div></div>`;
  }
  if (f.type === "unidad"){
    return `<div class="scl" data-uni="${f.n}"><div class="scl-head"><b>Unidad ${f.n}</b><button type="button" class="linkbtn" data-uniabrir="${f.n}" id="uni-b-${f.n}">Planificar esta unidad</button></div><div class="sec-body sub-grid">${f.sub.map(fieldHTML).join("")}</div></div>`;
  }
  if (f.type === "formato"){
    return `<div class="f full"><p class="hint">Elegí qué secciones van en la planificación de <b id="fmt-modo"></b> y en qué orden. Queda guardado en este navegador como plantilla para tus próximas planificaciones de ese tipo.</p>
      <div class="fmt-list" id="fmt-list"></div><div><button type="button" class="linkbtn" id="fmt-reset">Volver al formato original</button></div></div>`;
  }
  if (f.type === "encabezado"){
    return `<div class="f full enc"><div class="f-head"><span class="lbl">Encabezado institucional (opcional)</span><span class="tag">Se guarda para todas tus planificaciones</span></div>
      <div class="enc-row"><div class="enc-logo" id="enc-logo-box"></div><div class="enc-btns"><button type="button" class="btn btn-sm" id="enc-subir">Subir logo</button><button type="button" class="linkbtn" id="enc-quitar" hidden>Quitar logo</button><input type="file" id="enc-file" accept="image/*" hidden></div></div>
      <label class="sr-only" for="enc-texto">Texto del encabezado</label><textarea id="enc-texto" class="ta-sm" rows="2" placeholder="Ej.: Ministerio de Educación · Provincia de Tucumán"></textarea></div>`;
  }
  if (f.type === "clasesec"){
    return `<div class="scl" data-scl="${f.n}"><div class="scl-head"><b id="scl-h-${f.n}">Clase ${f.n}</b><button type="button" class="linkbtn" data-sclabrir="${f.n}">Planificar esta clase en detalle</button></div>${f.sub.map(fieldHTML).join("")}</div>`;
  }
  if (f.type === "planea"){
    return `<div class="f full">
      <div class="f-head"><span class="lbl" id="pl-lbl">Proyectos PLaNEA para usar como base</span><span class="tag" id="pl-count"></span></div>
      <p class="hint" id="pl-hint"></p>
      <div class="pl-list" id="pl-list" role="group" aria-labelledby="pl-lbl"></div>
      <button type="button" class="linkbtn" id="pl-more" hidden></button>
    </div>`;
  }
  if (f.type === "integra2"){
    return `<div class="f full"><div class="f-head"><span class="lbl" id="integra-b-lbl">Espacios curriculares con los que trabajás</span></div>
      <p class="hint">Elegí los espacios: se sugieren los aportes de cada uno y los acuerdos, y se suma una sección al documento. Es la propuesta de aprendizaje integrado de Secundaria Federal 2030.</p>
      <div class="chips chips-row" id="integra-b" role="group" aria-labelledby="integra-b-lbl"></div></div>`;
  }
  if (f.type === "integra"){
    return `<div class="f full" data-solo="proyecto">
      <div class="f-head"><span class="lbl" id="integra-lbl">Espacios curriculares que se integran (opcional)</span></div>
      <div class="chips chips-row" id="integra" role="group" aria-labelledby="integra-lbl"></div>
    </div>`;
  }
  if (f.type === "catalogo"){
    return `<div class="f full">
      <div class="f-head"><span class="lbl" id="cat-lbl">Recursos oficiales y normativa (Educ.ar, INFoD, CONAE)</span><span class="tag" id="cat-count"></span></div>
      <p class="hint" id="cat-hint"></p>
      <label class="sr-only" for="cat-q">Buscar en el catálogo</label>
      <input id="cat-q" type="search" autocomplete="off" placeholder="Buscar en el catálogo: circuitos, Revolución de Mayo, poesía…">
      <div class="chips" id="cat-list" role="group" aria-labelledby="cat-lbl"></div>
      <div class="cat-links"><button type="button" class="linkbtn" id="cat-more" hidden></button><button type="button" class="linkbtn" id="cat-norma">Ver normativa vigente</button></div>
    </div>`;
  }
  if (f.type === "imagenes"){
    return `<div class="f full img-tools">
      <div class="img-row">
        <div class="f"><label for="img-tipo">Tipo de imagen</label>
          <select id="img-tipo">${TIPOS_IMG.map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join("")}</select></div>
        <div class="f"><label for="img-momento">Dónde va en la clase</label>
          <select id="img-momento">${MOMENTOS.map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join("")}</select></div>
      </div>
      <div class="f"><label for="img-detalle">Qué tiene que mostrar (opcional)</label>
        <input id="img-detalle" type="text" autocomplete="off" placeholder="Ej.: un bloque sobre una mesa con las fuerzas que actúan"></div>
      <div class="img-actions">
        <button type="button" class="btn btn-primary" id="img-gen" hidden>Generar con Claude</button>
        <button type="button" class="btn" id="img-mapa">Mapa conceptual automático</button>
        <button type="button" class="btn" id="img-subir">Subir imagen</button>
        <input type="file" id="img-file" accept="image/png,image/jpeg,image/webp,image/gif" hidden>
      </div>
      <div class="img-status" id="img-status" role="status" hidden><i class="spinner" aria-hidden="true"></i><span id="img-status-txt"></span><button type="button" class="linkbtn" id="img-stop">Detener</button></div>
      <p class="hint" id="img-hint"></p>
      <div class="gallery" id="gallery"></div>
    </div>`;
  }
  const tag = (f.auto ? `<span class="tag" id="tag-${f.id}"></span>` : "") + (f.banco ? `<button type="button" class="linkbtn banco-btn" data-banco="${f.id}">Guardar en el banco</button>` : "");
  let control;
  if (f.type === "select"){
    control = `<select id="${f.id}">${f.empty ? `<option value="">${esc(f.empty)}</option>` : ""}${f.opts.map(([v, l]) => `<option value="${v}"${f.def === v ? " selected" : ""}>${esc(l)}</option>`).join("")}</select>`;
  } else if (f.auto || f.rows){
    control = `<textarea id="${f.id}" rows="${f.rows || 4}"${f.small ? ' class="ta-sm"' : ""}${f.ph ? ` placeholder="${esc(f.ph)}"` : ""}></textarea>`;
  } else {
    const list = f.list ? ` list="dl-${f.id}"` : "";
    control = `<input id="${f.id}" type="${f.type || "text"}" autocomplete="off"${f.ph ? ` placeholder="${esc(f.ph)}"` : ""}${f.def ? ` value="${esc(f.def)}"` : ""}${list}>`;
    if (f.list) control += `<datalist id="dl-${f.id}">${f.list.map(o => `<option value="${esc(o)}">`).join("")}</datalist>`;
  }
  const attrs = f.attr ? Object.entries(f.attr).map(([k, v]) => ` data-${k}="${v}"`).join("") : "";
  return `<div class="f${f.full ? " full" : ""}"${f.solo ? ` data-solo="${f.solo}"` : ""}${attrs}><div class="f-head"><label for="${f.id}">${esc(f.label)}</label>${tag}</div>${control}</div>`;
}
function buildForm(){
  let opcPuesto = false;
  $("form-secs").innerHTML = FORM.map((s, i) => {
    let pre = "";
    if (s.opc && !opcPuesto){
      opcPuesto = true;
      pre = `<div class="opc-head" id="opc-head"><div><b>Más opciones</b><p class="hint">Capacidades, imágenes, diversidad, trabajo con otras materias, instrumentos, ficha, ejes transversales, registro, y el formato del documento con el logo de tu escuela. Lo que hace falta ya está sugerido en el documento: abrilas solo si querés cambiar algo.</p></div><button type="button" class="btn btn-sm" id="opc-toggle" aria-expanded="false" aria-controls="form-secs"><span>Mostrar las opciones</span></button></div>`;
    }
    return pre + `
    <details class="sec ${s.opc ? "opc" : "esen"}" id="sec-${i}"${s.open ? " open" : ""}${s.solo ? ` data-solo="${s.solo}"` : ""}>
      <summary><span class="sec-tt"><span class="sec-t">${esc(s.t)}</span>${s.d ? `<small class="sec-d">${esc(s.d)}</small>` : ""}</span><span class="sum-hint" id="sumh-${i}"></span><span class="chev" aria-hidden="true"></span></summary>
      <div class="sec-body">${s.fields.map(fieldHTML).join("")}</div>
    </details>`;
  }).join("");
}

