/* ============================================================
   Mi curso: cursos, lista, asistencia, notas por período, conducta,
   libro de temas, agenda, familias, cierre y entregas.
   Todo queda en este navegador (CURSOS_KEY) y en la copia de seguridad.
   ============================================================ */
const CURSOS_KEY = "planificador-cursos-v1";
const esNumC = v => v !== "" && v != null && !isNaN(parseFloat(String(v).replace(",", ".")));
const aNumC = v => parseFloat(String(v).replace(",", "."));
const nuevoIdC = p => (p || "x") + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const coma = n => String(Math.round(n * 100) / 100).replace(".", ",");
const signo = n => (n > 0 ? "+" : n < 0 ? "−" : "") + coma(Math.abs(n));
const hoyIso = () => isoDe(new Date());
const fechaLarga = iso => { const d = fechaDe(iso); return d ? `${DIAS_SEM[d.getDay()]} ${d.getDate()} de ${MESES[d.getMonth()]}` : ""; };
const fechaCortaIso = iso => { const d = fechaDe(iso); return d ? `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}/${d.getFullYear()}` : ""; };

let CD = null;
function cdatos(){
  if (CD) return CD;
  try { const c = JSON.parse(localStorage.getItem(CURSOS_KEY) || "null"); CD = c && Array.isArray(c.cursos) ? c : null; } catch (e) { CD = null; }
  if (!CD){ CD = {cursos:[], sel:""}; migrarSeguimiento(CD); }
  return CD;
}
function cguardar(){
  try { localStorage.setItem(CURSOS_KEY, JSON.stringify(CD)); try { gdProgramar(); } catch (e) { logSilencioso(e); } return true; }
  catch (e) { toast("No queda espacio en este navegador. Descargá una copia de seguridad y borrá cursos o fotos viejas."); return false; }
}
function cursoSel(){ const d = cdatos(); return d.cursos.find(c => c.id === d.sel) || d.cursos[0] || null; }
function alumnosActivos(c){ return (c.alumnos || []).filter(a => !a.baja); }
function nombreCurso(c){ return [c.curso || "Curso sin nombre", nombreMateria(c.materia)].filter(Boolean).join(" · "); }

/* Régimen y períodos */
const REGIMENES = {trim:{n:3, nombre:"trimestre", plural:"trimestres"}, cuatri:{n:2, nombre:"cuatrimestre", plural:"cuatrimestres"}};
const ORD = ["1.er", "2.º", "3.er", "4.º"];
function nombrePeriodo(c, p){ return `${ORD[p] || (p + 1) + ".º"} ${REGIMENES[c.regimen || "trim"].nombre}`; }
function periodosDefault(ciclo, regimen){
  const y = +ciclo || new Date().getFullYear(), c = CAL[y] || {};
  const ini = c.inicio || `${y}-03-02`, fin = c.fin || `${y}-12-15`;
  const sem = semanasLectivas(y);
  const finSemana = w => { const d = new Date(w); d.setDate(d.getDate() + 4); return isoDe(d); };
  if (regimen === "cuatri"){
    if (c.receso){
      const a = fechaDe(c.receso[0]); a.setDate(a.getDate() - 1);
      const b = fechaDe(c.receso[1]); b.setDate(b.getDate() + 1);
      while (b.getDay() === 0 || b.getDay() === 6) b.setDate(b.getDate() + 1);
      return [{ini, fin:isoDe(a)}, {ini:isoDe(b), fin}];
    }
    const k = Math.max(1, Math.round(sem.length / 2));
    return [{ini, fin:finSemana(sem[k - 1])}, {ini:isoDe(sem[k]), fin}];
  }
  const k1 = Math.max(1, Math.round(sem.length / 3)), k2 = Math.max(k1 + 1, Math.round(sem.length * 2 / 3));
  return [{ini, fin:finSemana(sem[k1 - 1])}, {ini:isoDe(sem[k1]), fin:finSemana(sem[k2 - 1])}, {ini:isoDe(sem[k2]), fin}];
}
function periodoDe(c, iso){
  const ps = c.periodos || [];
  if (!iso || !ps.length) return 0;
  for (let i = ps.length - 1; i >= 0; i--) if (iso >= ps[i].ini) return i;
  return 0;
}
function enPeriodo(c, iso, p){ return periodoDe(c, iso) === p; }

function cursoNuevo(o){
  const regimen = o.regimen === "cuatri" ? "cuatri" : "trim", ciclo = o.ciclo || String(new Date().getFullYear());
  return {id:nuevoIdC("c"), curso:o.curso || "", materia:o.materia || "", anio:o.anio || "", ciclo, escuela:o.escuela || "", docente:o.docente || "",
    regimen, periodos:periodosDefault(ciclo, regimen), escala:{max:10, aprob:6, redondeo:"entero"}, condApr:"promedio", limiteFaltas:20,
    horario:[], alumnos:(o.alumnos || []).map(n => ({id:nuevoIdC("a"), n})), asis:{}, evals:[], notas:{}, coment:{}, rub:{}, per:{}, fin:{},
    cond:[], condCfg:{usar:true, mas:0.25, menos:0.25, tope:1}, temas:[], agenda:[], inf:{per:"", txt:{}}, recup:{}, previas:[], planes:o.planes || [], creado:Date.now()};
}

/* Migración desde la planilla anterior (una por planificación) */
function migrarSeguimiento(D){
  let viejo = {};
  try { viejo = JSON.parse(localStorage.getItem("planificador-seguimiento-v1") || "{}") || {}; } catch (e) { viejo = {}; }
  const lib = (() => { try { return libLeer(); } catch (e) { return []; } })();
  Object.entries(viejo).forEach(([planId, s]) => {
    if (!s || !Array.isArray(s.alumnos) || !s.alumnos.length) return;
    const e = lib.find(x => x.id === planId), v = (e && e.data && e.data.v) || {};
    const clave = norm((v.curso || "") + "|" + (v.materia || ""));
    let c = D.cursos.find(x => norm((x.curso || "") + "|" + (x.materia || "")) === clave && clave !== "|");
    if (!c){
      c = cursoNuevo({curso:v.curso || "Curso migrado", materia:v.materia, anio:v.anio, ciclo:v.ciclo, escuela:v.institucion, docente:v.docente, regimen:"trim", planes:e ? [planId] : []});
      c.migrado = true; D.cursos.push(c);
    } else if (e && !c.planes.includes(planId)) c.planes.push(planId);
    const ids = s.alumnos.map(n => { let a = c.alumnos.find(x => norm(x.n) === norm(n)); if (!a){ a = {id:nuevoIdC("a"), n}; c.alumnos.push(a); } return a.id; });
    const hoy = hoyIso();
    (s.cols || []).forEach(col => {
      if (col.tipo === "nota"){
        const ev = {id:nuevoIdC("e"), t:col.t, f:hoy, p:periodoDe(c, hoy)};
        c.evals.push(ev);
        ids.forEach((aid, i) => { const val0 = (s.vals || {})[`${i}:${col.id}`]; if (val0 != null && val0 !== ""){ (c.notas[aid] = c.notas[aid] || {})[ev.id] = val0; } });
      } else if (col.tipo === "asis"){
        const m = /\((\d{1,2})\/(\d{1,2})\)/.exec(col.t || "");
        const f = m ? `${v.ciclo || new Date().getFullYear()}-${pad2(+m[2])}-${pad2(+m[1])}` : "";
        if (!f) return;
        ids.forEach((aid, i) => { const val0 = (s.vals || {})[`${i}:${col.id}`]; if (val0){ (c.asis[f] = c.asis[f] || {})[aid] = val0; } });
      }
    });
    (s.cond || []).forEach(k => { if (ids[k.i]) c.cond.push({id:k.id || nuevoIdC("k"), aid:ids[k.i], f:k.f, tipo:k.tipo, t:k.t, ts:k.ts || Date.now()}); });
    if (s.condCfg) c.condCfg = {...c.condCfg, ...s.condCfg};
    if (s.inf){ c.inf.per = s.inf.per || ""; Object.entries(s.inf.txt || {}).forEach(([n, t]) => { const a = c.alumnos.find(x => norm(x.n) === norm(n)); if (a) c.inf.txt[a.id] = t; }); }
  });
  if (D.cursos.length){
    D.sel = D.cursos[0].id;
    try { localStorage.setItem(CURSOS_KEY, JSON.stringify(D)); } catch (e) { logSilencioso(e); }
  }
}

/* Cálculos de notas */
function redondear(c, x){
  const r = (c.escala || {}).redondeo || "entero";
  return r === "medio" ? Math.round(x * 2) / 2 : r === "decimal" ? Math.round(x * 10) / 10 : Math.round(x);
}
const aprobC = c => +((c.escala || {}).aprob) || 6;
const maxC = c => +((c.escala || {}).max) || 10;
function limitar(c, x){ return Math.max(1, Math.min(maxC(c), x)); }
function notaEval(c, aid, eid){ const v = ((c.notas || {})[aid] || {})[eid]; return esNumC(v) ? aNumC(v) : null; }
function evalsDe(c, p){ return (c.evals || []).filter(e => e.p === p).sort((a, b) => (a.f || "").localeCompare(b.f || "")); }
function promPeriodo(c, aid, p){
  const ns = evalsDe(c, p).map(e => notaEval(c, aid, e.id)).filter(x => x != null);
  return ns.length ? ns.reduce((a, b) => a + b, 0) / ns.length : null;
}
function condDeC(c, aid, p){
  const l = (c.cond || []).filter(k => k.aid === aid && (p == null || periodoDe(c, k.f) === p));
  return {pos:l.filter(k => k.tipo === "+"), neg:l.filter(k => k.tipo === "-")};
}
function condCfgC(c){ return {usar:true, mas:0.25, menos:0.25, tope:1, ...(c.condCfg || {})}; }
function ajusteC(c, aid, p){
  const g = condCfgC(c);
  if (!g.usar) return 0;
  const d = condDeC(c, aid, p);
  return Math.max(-g.tope, Math.min(g.tope, d.pos.length * g.mas - d.neg.length * g.menos));
}
function notaPeriodoCalc(c, aid, p){ const pr = promPeriodo(c, aid, p); return pr == null ? null : limitar(c, redondear(c, pr + ajusteC(c, aid, p))); }
function notaPeriodo(c, aid, p){
  const man = (((c.per || {})[aid] || {})["p" + p] || {}).man;
  return esNumC(man) ? aNumC(man) : notaPeriodoCalc(c, aid, p);
}
function notaEfectiva(c, aid, p){
  const rec = (((c.per || {})[aid] || {})["p" + p] || {}).rec;
  const n = notaPeriodo(c, aid, p);
  return esNumC(rec) ? Math.max(aNumC(rec), n == null ? 0 : n) : n;
}
function notaAnual(c, aid){
  const ps = (c.periodos || []).map((_, p) => notaEfectiva(c, aid, p));
  if (ps.some(x => x == null)) return {ps, anual:null};
  return {ps, anual:redondear(c, ps.reduce((a, b) => a + b, 0) / ps.length)};
}
function condicion(c, aid){
  const {ps, anual} = notaAnual(c, aid), ap = aprobC(c), f = (c.fin || {})[aid] || {};
  if (anual == null) return {k:"curso", t:"En curso", def:null, anual, ps};
  const ok = c.condApr === "todos" ? ps.every(x => x >= ap) && anual >= ap : anual >= ap;
  if (ok) return {k:"ok", t:"Aprobado", def:anual, anual, ps};
  if (esNumC(f.dic) && aNumC(f.dic) >= ap) return {k:"dic-ok", t:"Aprobado en diciembre", def:aNumC(f.dic), anual, ps};
  if (esNumC(f.dic)){
    if (esNumC(f.feb) && aNumC(f.feb) >= ap) return {k:"feb-ok", t:"Aprobado en febrero/marzo", def:aNumC(f.feb), anual, ps};
    if (esNumC(f.feb)) return {k:"previa", t:"Queda como previa", def:aNumC(f.feb), anual, ps};
    return {k:"feb", t:"Va a febrero/marzo", def:null, anual, ps};
  }
  return {k:"dic", t:"Va a diciembre", def:null, anual, ps};
}
const fmtN = x => x == null ? "" : String(Math.round(x * 100) / 100).replace(".", ",");

/* Asistencia */
const ASIS = [["P", "Presente"], ["A", "Ausente"], ["T", "Tarde"], ["R", "Retiro"]];
function asisResumen(c, aid, p){
  const r = {P:0, A:0, T:0, R:0, clases:0};
  Object.entries(c.asis || {}).forEach(([f, m]) => {
    if (p != null && periodoDe(c, f) !== p) return;
    const v = m[aid]; if (!v) return;
    r[v] = (r[v] || 0) + 1; r.clases++;
  });
  r.faltas = r.A + (r.T + r.R) * 0.5;
  r.pct = r.clases ? Math.round(r.faltas / r.clases * 100) : 0;
  r.alerta = r.clases >= 4 && r.pct >= (+c.limiteFaltas || 20);
  return r;
}

/* Conducta */
const COND_POS = ["Participa activamente", "Ayuda a sus compañeros", "Cumple con las tareas", "Trae los materiales", "Trabaja bien en grupo", "Respeta los acuerdos de convivencia", "Muestra avances"];
const COND_NEG = ["No trae los materiales", "No entrega la tarea", "No trabaja en clase", "Interrumpe la clase", "Usa el celular sin permiso", "Falta el respeto a compañeros o docentes", "Llega tarde sin justificar"];
const COND_META = {
  "No trae los materiales":"traer los materiales necesarios", "No entrega la tarea":"entregar las tareas en tiempo y forma",
  "No trabaja en clase":"sostener el trabajo durante la clase", "Interrumpe la clase":"respetar los momentos de trabajo y de escucha",
  "Usa el celular sin permiso":"usar el celular solo cuando la actividad lo pide", "Falta el respeto a compañeros o docentes":"sostener un trato respetuoso con compañeros y docentes",
  "Llega tarde sin justificar":"llegar puntual a clase"
};
function contar(lista){ const m = new Map(); lista.forEach(k => m.set(k.t, (m.get(k.t) || 0) + 1)); return [...m.entries()].sort((a, b) => b[1] - a[1]); }
function registrarConducta(c, aid, tipo, texto, f){
  texto = (texto || "").trim();
  if (!texto) return null;
  const reg = {id:nuevoIdC("k"), aid, f:f || hoyIso(), tipo, t:texto, ts:Date.now()};
  c.cond.push(reg); cguardar();
  return reg;
}

/* Números en letras para actas */
const UNID = ["cero", "uno", "dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho", "nueve", "diez", "once", "doce", "trece", "catorce", "quince", "dieciséis", "diecisiete", "dieciocho", "diecinueve", "veinte"];
const DECE = {3:"treinta", 4:"cuarenta", 5:"cincuenta", 6:"sesenta", 7:"setenta", 8:"ochenta", 9:"noventa"};
function enLetras2(n){
  if (n <= 20) return UNID[n];
  if (n < 30) return "veinti" + ["", "uno", "dós", "trés", "cuatro", "cinco", "séis", "siete", "ocho", "nueve"][n - 20];
  const d = Math.floor(n / 10), u = n % 10;
  return DECE[d] + (u ? " y " + UNID[u] : "");
}
function numLetras(x){
  if (x == null || isNaN(x)) return "";
  const e = Math.floor(x), dec = Math.round((x - e) * 100);
  return enLetras2(e) + (dec ? " con " + enLetras2(dec) : "");
}

/* Excel genérico: hojas con celdas de texto, número o fórmula */
function xlsxLibro(hojas){
  const col = n => { let r = ""; n++; while (n > 0){ const m = (n - 1) % 26; r = String.fromCharCode(65 + m) + r; n = Math.floor((n - 1) / 26); } return r; };
  const x = t => xmlEsc(String(t));
  const R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
  const WS = "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml";
  const celda = (r, c, v) => {
    const ref = `${col(c)}${r}`;
    let est = 0;
    if (v && typeof v === "object" && !Array.isArray(v) && "s" in v){ est = v.s; v = "v" in v ? v.v : v.f != null ? {f:v.f} : ""; }
    const s = est ? ` s="${est}"` : "";
    if (v === "" || v == null) return est ? `<c r="${ref}"${s}/>` : "";
    if (typeof v === "number") return `<c r="${ref}"${s}><v>${v}</v></c>`;
    if (typeof v === "object") return `<c r="${ref}"${s}><f>${x(v.f)}</f></c>`;
    return `<c r="${ref}" t="inlineStr"${s}><is><t xml:space="preserve">${x(v)}</t></is></c>`;
  };
  const hojaXml = h => {
    const filas = h.filas.map((fila, i) => `<row r="${i + 1}">${fila.map((v, j) => celda(i + 1, j, v)).join("")}</row>`).join("");
    const anchos = (h.anchos || []).map((w, i) => `<col min="${i + 1}" max="${i + 1}" width="${w}" customWidth="1"/>`).join("");
    const pane = h.congelar ? `<sheetViews><sheetView workbookViewId="0"><pane${h.congelar.x ? ` xSplit="${h.congelar.x}"` : ""} ySplit="${h.congelar.y || 1}" topLeftCell="${col(h.congelar.x || 0)}${(h.congelar.y || 1) + 1}" activePane="${h.congelar.x ? "bottomRight" : "bottomLeft"}" state="frozen"/></sheetView></sheetViews>` : "";
    const merges = h.unir && h.unir.length ? `<mergeCells count="${h.unir.length}">${h.unir.map(m => `<mergeCell ref="${m}"/>`).join("")}</mergeCells>` : "";
    const val = h.validaciones && h.validaciones.length ? `<dataValidations count="${h.validaciones.length}">${h.validaciones.map(v => `<dataValidation type="list" allowBlank="1" showErrorMessage="1" sqref="${v.ref}"><formula1>"${x(v.lista.join(","))}"</formula1></dataValidation>`).join("")}</dataValidations>` : "";
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="${R}">${pane}${anchos ? `<cols>${anchos}</cols>` : ""}<sheetData>${filas}</sheetData>${merges}${val}<pageMargins left="0.5" right="0.5" top="0.6" bottom="0.6" header="0.3" footer="0.3"/><pageSetup paperSize="9" orientation="${h.horizontal ? "landscape" : "portrait"}" fitToWidth="1" fitToHeight="0"/></worksheet>`;
  };
  const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="3"><numFmt numFmtId="164" formatCode="0.0"/><numFmt numFmtId="165" formatCode="+0.00;-0.00;0"/><numFmt numFmtId="166" formatCode="0.00"/></numFmts><fonts count="3"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="13"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFEEF2F0"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFBFC7C3"/></left><right style="thin"><color rgb="FFBFC7C3"/></right><top style="thin"><color rgb="FFBFC7C3"/></top><bottom style="thin"><color rgb="FFBFC7C3"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="9"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment wrapText="1" vertical="center"/></xf><xf numFmtId="9" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/><xf numFmtId="165" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/><xf numFmtId="166" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment wrapText="1" vertical="top"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
  const nom = h => x((h.nombre || "Hoja").replace(/[\\/?*\[\]:']/g, " ").slice(0, 31));
  return zipStore([
    {name:"[Content_Types].xml", data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${hojas.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="${WS}"/>`).join("")}<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`},
    {name:"_rels/.rels", data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${R}/officeDocument" Target="xl/workbook.xml"/></Relationships>`},
    {name:"xl/workbook.xml", data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="${R}"><sheets>${hojas.map((h, i) => `<sheet name="${nom(h)}" sheetId="${i + 1}" r:id="rId${i + 10}"/>`).join("")}</sheets><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`},
    {name:"xl/_rels/workbook.xml.rels", data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId2" Type="${R}/styles" Target="styles.xml"/>${hojas.map((_, i) => `<Relationship Id="rId${i + 10}" Type="${R}/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join("")}</Relationships>`},
    ...hojas.map((h, i) => ({name:`xl/worksheets/sheet${i + 1}.xml`, data:hojaXml(h)})),
    {name:"xl/styles.xml", data:styles}
  ]);
}
const XLSX_MIME = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
async function bajarXlsx(nombre, hojas, msg){ await guardarArchivo(nombre, new Blob([xlsxLibro(hojas)], {type:XLSX_MIME}), msg || "Planilla descargada."); }
async function bajarDoc(M, nombre, formato, msg){
  try {
    if (formato === "pdf"){ PDF_REEMPLAZOS = 0; const b = await pdfDe(M); await guardarArchivo(nombre + ".pdf", b, PDF_REEMPLAZOS ? "PDF descargado. Algunos símbolos (letras griegas, subíndices) se escribieron con letras: para conservarlos tal cual, usá Word o «Imprimir»." : (msg || "PDF descargado.")); }
    else { const b = zipStore(await docxArchivos(M)); await guardarArchivo(nombre + ".docx", b, msg || "Documento de Word descargado."); }
  } catch (e) {
    registrarError("bajarDoc", e, e && e.message === "red" ? "aviso" : "error");
    toast(e && e.message === "red" ? "Para el PDF hace falta conexión. Descargalo en Word o usá «Imprimir»." : "No se pudo armar el documento. Quedó anotado en Ajustes › Diagnóstico.");
  }
}
