const FUENTE = (() => {
  try {
    const s = document.currentScript;
    return {js:s ? s.textContent : "", src:s && s.src ? s.src : "", app:document.getElementById("app") ? document.getElementById("app").outerHTML : "", css:[...document.querySelectorAll("style")].map(x => x.textContent).join("\n")};
  } catch (e) { return {js:"", app:"", css:""}; }
})();
const CLAVES_RESPALDO = ["planificador-hojas-v1", "planificador-clases-v2", "planificador-biblioteca-v1", "planificador-encabezado-v1", "planificador-preferencias-v1", "planificador-formato-v1", "planificador-banco-v1", "planificador-seguimiento-v1", "planificador-ppi-v1", "planificador-cursos-v1", "planificador-preguntas-v1", "planificador-salidas-v1", "planificador-actas-v1", "planificador-legajo-v1", "planificador-junta-v1", "planificador-novedades-visto"];
function prefSet(k, v){ try { const p = leerPref(); p[k] = v; localStorage.setItem(PREF_KEY, JSON.stringify(p)); } catch (e) { logSilencioso(e); } }
function abrirRespaldo(){
  const ult = leerPref().respaldo;
  $("resp-ult").textContent = ult ? `Última copia: ${new Date(ult).toLocaleDateString("es-AR")}.` : "Todavía no descargaste ninguna copia.";
  abrirDialogo("respaldo");
  renderPrevias();
}
async function descargarRespaldoBase(){
  save();
  const datos = {};
  CLAVES_RESPALDO.forEach(k => { try { const v = localStorage.getItem(k); if (v != null) datos[k] = v; } catch (e) { logSilencioso(e); } });
  let fotos = [];
  if ($("resp-fotos").checked){ try { fotos = await fotosTodas(); } catch (e) { logSilencioso(e); } }
  const o = {app:"planificador-clases", tipo:"respaldo", version:1, fecha:new Date().toISOString(), datos, fotos};
  await guardarArchivo(`copia-planificador-${hoyIso()}.json`, new Blob([JSON.stringify(o)], {type:"application/json"}), "Copia descargada. Guardala en Google Drive o pasala al otro dispositivo.");
  prefSet("respaldo", Date.now());
  $("resp-ult").textContent = `Última copia: ${new Date().toLocaleDateString("es-AR")}.`;
  renderTuDia();
}
function fusionarArr(a, b, clave){ const ids = new Set(a.map(x => x[clave || "id"])); return [...a, ...b.filter(x => x && !ids.has(x[clave || "id"]))]; }
async function aplicarRespaldoDatos(o, reemplazar){
  {
    if (reemplazar) escribirDatos(o.datos, true);
    else {
      const leer = k => { try { return JSON.parse(localStorage.getItem(k) || "null"); } catch (e) { return null; } };
      const de = k => { try { return JSON.parse(o.datos[k] || "null"); } catch (e) { return null; } };
      const arrs = ["planificador-hojas-v1", "planificador-biblioteca-v1", "planificador-banco-v1", "planificador-ppi-v1", "planificador-preguntas-v1", "planificador-salidas-v1", "planificador-actas-v1"];
      arrs.forEach(k => { const b = de(k); if (Array.isArray(b)) localStorage.setItem(k, JSON.stringify(fusionarArr(leer(k) || [], b))); });
      const cb = de("planificador-cursos-v1");
      if (cb && Array.isArray(cb.cursos)){ const ca = leer("planificador-cursos-v1") || {cursos:[], sel:""}; ca.cursos = fusionarArr(ca.cursos || [], cb.cursos); if (!ca.sel && ca.cursos[0]) ca.sel = ca.cursos[0].id; localStorage.setItem("planificador-cursos-v1", JSON.stringify(ca)); }
      const lb = de("planificador-legajo-v1");
      if (lb){ const la = leer("planificador-legajo-v1") || {}; Object.keys(lb).forEach(s => { if (Array.isArray(lb[s])) la[s] = fusionarArr(la[s] || [], lb[s]); }); localStorage.setItem("planificador-legajo-v1", JSON.stringify(la)); }
      const sg = de("planificador-seguimiento-v1");
      if (sg){ const sa = leer("planificador-seguimiento-v1") || {}; Object.keys(sg).forEach(k => { if (!sa[k]) sa[k] = sg[k]; }); localStorage.setItem("planificador-seguimiento-v1", JSON.stringify(sa)); }
      const jb = de("planificador-junta-v1");
      if (jb){ const ja = leer("planificador-junta-v1") || {}; ja.vac = fusionarArr(ja.vac || [], jb.vac || []); ["zonas", "favEsc", "recDias"].forEach(k => { ja[k] = [...new Set([...(ja[k] || []), ...(jb[k] || [])])]; }); ja.escZona = {...(jb.escZona || {}), ...(ja.escZona || {})}; ja.escCue = {...(jb.escCue || {}), ...(ja.escCue || {})}; ja.seg = {...(jb.seg || {}), ...(ja.seg || {})}; ja.origenes = fusionarArr(ja.origenes || [], jb.origenes || []); ["origen", "medio", "valorHora", "topeHoras"].forEach(k => { if (ja[k] == null || ja[k] === "") ja[k] = jb[k]; }); ja.costo = {...(jb.costo || {}), ...(ja.costo || {})}; ja.pubs = {...(jb.pubs || {}), ...(ja.pubs || {})}; ja.medidos = {...(jb.medidos || {}), ...(ja.medidos || {})}; ja.colect = {...(jb.colect || {}), ...(ja.colect || {})}; if (!ja.lim) ja.lim = jb.lim; ja.sigue = [...new Set([...(ja.sigue || []), ...(jb.sigue || [])])]; ja.histK = [...new Set([...(ja.histK || []), ...(jb.histK || [])])]; ja.hist = ja.hist || {}; Object.entries(jb.hist || {}).forEach(([m, o2]) => { ja.hist[m] = ja.hist[m] || {}; Object.entries(o2 || {}).forEach(([k2, n2]) => { ja.hist[m][k2] = Math.max(ja.hist[m][k2] || 0, n2); }); }); ja.ult = Math.max(ja.ult || 0, jb.ult || 0); localStorage.setItem("planificador-junta-v1", JSON.stringify(ja)); }
      ["planificador-encabezado-v1", "planificador-formato-v1"].forEach(k => { if (o.datos[k] && !localStorage.getItem(k)) localStorage.setItem(k, o.datos[k]); });
    }
    for (const f of (o.fotos || [])) { try { await fotoPut(f); } catch (e) { logSilencioso(e); } }
  }
  return true;
}
async function descargarSinConexion(){
  /* En la app instalada el programa viene en un archivo aparte (más rápido al abrir): se lee de ahí */
  if (!FUENTE.js && FUENTE.src){ try { const r = await fetch(FUENTE.src); if (r.ok) FUENTE.js = await r.text(); } catch (e) { logSilencioso(e); } }
  if (!FUENTE.js || !FUENTE.app){ toast("No se pudo armar la versión sin conexión en este navegador."); return; }
  const js = FUENTE.js.replace(/<\/script/gi, "<\\/script");
  /* Se incluye la librería de PDF para que la descarga en PDF también funcione sin internet */
  let pdfLib = "";
  try { const r = await fetch(JSPDF_URL); if (r.ok) pdfLib = (await r.text()).replace(/<\/script/gi, "<\\/script"); } catch (e) { logSilencioso(e); }
  let html = `<!doctype html>\n<html lang="es">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Lapacho, planificador docente</title>\n<style>body{margin:0}\n${FUENTE.css}</style>\n</head>\n<body>\n${FUENTE.app}\n<script>${js}<\/script>\n${pdfLib ? `<script type="text/plain" id="jspdf-lib">${pdfLib}<\/script>\n` : ""}</body>\n</html>\n`;
  let pdfjs = "";
  try { const [a, b] = await Promise.all([fetch(PDFJS_URL), fetch(PDFJS_WORKER)]); if (a.ok && b.ok){ const esc2 = t => t.replace(/<\/script/gi, "<\\/script"); pdfjs = `<script type="text/plain" id="pdfjs-lib">${esc2(await a.text())}<\/script>\n<script type="text/plain" id="pdfjs-worker">${esc2(await b.text())}<\/script>\n`; } } catch (e) { logSilencioso(e); }
  if (pdfjs){ const k = html.lastIndexOf("</body>"); html = html.slice(0, k) + pdfjs + html.slice(k); }
  if (!pdfLib) toast("Ojo: no se pudo incluir la librería de PDF. Sin internet, usá Word o «Más › Imprimir».");
  await guardarArchivo("lapacho.html", new Blob([html], {type:"text/html"}), "Versión sin conexión descargada. Abrila con el navegador del celular o la computadora.");
}
/* PIN: evita que otra persona vea los datos de estudiantes en el dispositivo. No cifra los datos. */
let pinOk = false, pinRes = null;
async function hashPIN(p){
  try { const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("planificador:" + p)); return [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, "0")).join(""); }
  catch (e) { let h = 5381; for (const ch of "planificador:" + p) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return "d" + h.toString(16); }
}
function dialogoPIN(modo){
  return new Promise(res => {
    pinRes = res;
    $("pin").dataset.modo = modo;
    $("pin-t").textContent = modo === "crear" ? "Proteger con PIN" : modo === "quitar" ? "Quitar el PIN" : "Ingresá tu PIN";
    $("pin-msg").textContent = modo === "crear" ? "Elegí un PIN de 4 a 8 números. Se pide al abrir Mi curso, el modo aula, el PPI, las actas y tu legajo, y la app se bloquea sola después de un rato sin uso. Ojo: el PIN no cifra los datos guardados en el navegador; para eso usá la copia de seguridad con contraseña." : modo === "quitar" ? "Escribí el PIN actual para quitarlo." : "Para ver los datos de tus estudiantes.";
    $("pin-in").value = ""; $("pin-in2").value = ""; $("pin-in2").hidden = modo !== "crear"; $("pin-err").textContent = "";
    abrirDialogo("pin");
    setTimeout(() => $("pin-in").focus(), 50);
  });
}
async function confirmarPIN(){
  const modo = $("pin").dataset.modo, v = $("pin-in").value.trim();
  if (modo === "crear"){
    if (!/^\d{4,8}$/.test(v)){ $("pin-err").textContent = "Usá entre 4 y 8 números."; return; }
    if (v !== $("pin-in2").value.trim()){ $("pin-err").textContent = "Los dos PIN no coinciden."; return; }
    prefSet("pin", await pinCrearHash(v)); pinOk = true; pinActividad = Date.now(); cerrarDialogo("pin"); toast("PIN guardado."); renderAjustesPIN(); pinRes && pinRes(true); return;
  }
  const espera = pinEspera();
  if (espera > 0){ $("pin-err").textContent = `Demasiados intentos. Esperá ${espera} segundos.`; return; }
  if (!(await pinCoincide(v, leerPref().pin))){ $("pin-err").textContent = pinMensajeFallo(pinFallo()); $("pin-in").select(); return; }
  await pinExito(v);
  if (modo === "quitar"){ prefSet("pin", ""); toast("PIN quitado."); renderAjustesPIN(); }
  pinOk = true; cerrarDialogo("pin"); pinRes && pinRes(true);
}
function exigirPIN(){ if (!leerPref().pin || pinOk) return Promise.resolve(true); return dialogoPIN("pedir"); }
function renderAjustesPIN(){ const b = $("btn-pin"); if (b) b.querySelector("b").textContent = leerPref().pin ? "Quitar el PIN" : "Proteger con PIN"; try { renderAjustes37(); renderPanel(); } catch (e) { logSilencioso(e); } }
function imprimirDocV69(){ document.body.classList.add("imprimiendo"); document.body.classList.toggle("imp-gris", !!leerPref().impGris); setTimeout(() => { try { window.print(); } catch (e) { toast("Este navegador no permite imprimir desde acá. Probá con Word o PDF."); } setTimeout(() => document.body.classList.remove("imprimiendo"), 500); }, 50); }

/* ============================================================
   Código QR (generador incluido, funciona sin internet)
   ============================================================ */
function qrSVG(texto){
  QR_LIB.stringToBytes = QR_LIB.stringToBytesFuncs["UTF-8"];
  const q = QR_LIB(0, "M"); q.addData(texto, "Byte"); q.make();
  return {svg:q.createSvgTag({cellSize:6, margin:3, scalable:true}), url:q.createDataURL(8, 3)};
}
function textoQR(){
  const m = $("qr-tipo").value, v = state.modo === "secuencia" ? null : null;
  if (m === "link") return $("qr-link").value.trim();
  const tema = temaVisible();
  const lista = m === "ticket" ? consignasDe(val("ticket")) : consignasDe(val("ficha"));
  return lista.length ? `${tema ? tema + "\n" : ""}${lista.map((x, i) => `${i + 1}. ${x}`).join("\n")}` : "";
}
function pintarQR(){
  const box = $("qr-box"), t = textoQR();
  $("qr-link-f").hidden = $("qr-tipo").value !== "link";
  if (!t){ box.innerHTML = `<p class="hint">${$("qr-tipo").value === "link" ? "Pegá un enlace (por ejemplo, del archivo en Drive o de la tarea en Classroom)." : "La planificación abierta no tiene esas consignas."}</p>`; $("qr-acc").hidden = true; return; }
  if (new TextEncoder().encode(t).length > 1100){ box.innerHTML = `<p class="hint">El texto es muy largo para un código QR. Acortá las consignas o compartí un enlace.</p>`; $("qr-acc").hidden = true; return; }
  try { const r = qrSVG(t); box.innerHTML = r.svg; box.dataset.url = r.url; $("qr-acc").hidden = false; }
  catch (e) { box.innerHTML = `<p class="hint">No se pudo generar el código.</p>`; $("qr-acc").hidden = true; }
}

/* ============================================================
   Herramientas con listas propias: preguntas, salidas, actas y legajo
   ============================================================ */
function leerLista(k, def){ try { const v = JSON.parse(localStorage.getItem(k) || "null"); return v == null ? def : v; } catch (e) { return def; } }
function guardarLista(k, v){ try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch (e) { toast("No queda espacio en este navegador."); return false; } }

/* ---------- Banco de preguntas y pruebas ---------- */
const PREG_KEY = "planificador-preguntas-v1";
const TIPOS_PREG = [["mc", "Opción múltiple"], ["vf", "Verdadero o falso"], ["des", "Desarrollo"], ["prob", "Problema"]];
const PRUEBA = {sel:[], titulo:"", versiones:"1", ed:""};
function renderPreg(){
  const l = leerLista(PREG_KEY, []), q = norm(val("pq-q")), ed = l.find(x => x.id === PRUEBA.ed) || {};
  const lista = l.filter(x => !q || norm(x.e + " " + (x.tema || "") + " " + nombreMateria(x.materia)).includes(q));
  $("pq-tipo").value = ed.tipo || $("pq-tipo").value || "mc";
  if (PRUEBA.ed){ $("pq-e").value = ed.e || ""; $("pq-op").value = (ed.op || []).join("\n"); $("pq-ok").value = ed.ok ?? ""; $("pq-pts").value = ed.pts || ""; $("pq-tema").value = ed.tema || ""; }
  pregCampos();
  $("pq-guardar").textContent = PRUEBA.ed ? "Guardar cambios" : "Guardar la pregunta";
  $("pq-list").innerHTML = lista.length ? lista.map(x => `<div class="lib-item preg"><label class="pq-sel"><input type="checkbox" data-psel="${x.id}"${PRUEBA.sel.includes(x.id) ? " checked" : ""}> <span><b>${esc(x.e)}</b><small>${esc((TIPOS_PREG.find(t => t[0] === x.tipo) || ["", ""])[1])}${x.tema ? " · " + esc(x.tema) : ""}${x.pts ? ` · ${x.pts} pts` : ""}</small></span></label>
      <span class="lib-act"><button type="button" class="linkbtn" data-ped="${x.id}">Editar</button><button type="button" class="seg-x" data-pdel="${x.id}" aria-label="Borrar">×</button></span></div>`).join("")
    : `<p class="lib-empty">${q ? "No hay preguntas con esas palabras." : "Todavía no hay preguntas. Escribí una o traelas de la planificación abierta."}</p>`;
  $("pq-cuenta").textContent = PRUEBA.sel.length ? `${PRUEBA.sel.length} ${PRUEBA.sel.length === 1 ? "pregunta elegida" : "preguntas elegidas"} para la prueba.` : "Marcá las preguntas que van en la prueba.";
}
function pregCampos(){
  const t = $("pq-tipo").value;
  $("pq-op-f").hidden = t !== "mc"; $("pq-vf-f").hidden = t !== "vf"; $("pq-ok-f").hidden = t !== "mc";
  if (t === "mc"){ const n = $("pq-op").value.split("\n").filter(x => x.trim()).length; const cur = $("pq-ok").value; $("pq-ok").innerHTML = Array.from({length:Math.max(2, n)}, (_, i) => `<option value="${i}"${String(i) === cur ? " selected" : ""}>${String.fromCharCode(97 + i)}</option>`).join(""); }
}
function guardarPregunta(){
  const tipo = $("pq-tipo").value, e = $("pq-e").value.trim();
  if (!e){ toast("Escribí el enunciado."); return; }
  const op = tipo === "mc" ? $("pq-op").value.split("\n").map(x => x.trim()).filter(Boolean) : [];
  if (tipo === "mc" && op.length < 2){ toast("Escribí al menos dos opciones, una por línea."); return; }
  const o = {tipo, e, op, ok:tipo === "mc" ? +$("pq-ok").value : tipo === "vf" ? $("pq-vf").value : "", pts:$("pq-pts").value.trim(), tema:$("pq-tema").value.trim() || val("tema"), materia:val("materia")};
  const l = leerLista(PREG_KEY, []);
  if (PRUEBA.ed){ const x = l.find(y => y.id === PRUEBA.ed); if (x) Object.assign(x, o); }
  else l.unshift({id:nuevoIdC("q"), ...o});
  if (guardarLista(PREG_KEY, l)){ PRUEBA.ed = ""; ["pq-e", "pq-op", "pq-pts"].forEach(id => { $(id).value = ""; }); renderPreg(); toast("Pregunta guardada."); }
}
function traerPreguntas(){
  const qs = [...consignasDe(val("ticket")).map(x => ({tipo:"des", e:x})), ...consignasDe(val("ficha")).map(x => ({tipo:"des", e:x}))];
  if (!qs.length){ toast("La planificación abierta no tiene consignas ni ticket de salida."); return; }
  const l = leerLista(PREG_KEY, []), nuevas = qs.filter(q => !l.some(x => x.e === q.e)).map(q => ({id:nuevoIdC("q"), ...q, op:[], ok:"", pts:"", tema:val("tema"), materia:val("materia")}));
  if (!nuevas.length){ toast("Esas preguntas ya están en el banco."); return; }
  guardarLista(PREG_KEY, [...nuevas, ...l]); renderPreg(); toast(`Se agregaron ${nuevas.length} preguntas de desarrollo. Editalas si querés cambiarlas a otro tipo.`);
}
function rngSemilla(s){ let x = 0; for (const ch of s) x = (x * 31 + ch.charCodeAt(0)) >>> 0; return () => { x = (x * 1664525 + 1013904223) >>> 0; return x / 4294967296; }; }
function mezclar(arr, r){ const a = arr.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
function versionPrueba(qs, v){
  if (v === "A") return qs.map(q => ({...q, perm:q.op.map((_, i) => i)}));
  const r = rngSemilla(qs.map(q => q.id).join("") + v);
  return mezclar(qs, r).map(q => ({...q, perm:q.tipo === "mc" ? mezclar(q.op.map((_, i) => i), r) : []}));
}
function modeloPruebaBase(clave){
  const l = leerLista(PREG_KEY, []), qs = PRUEBA.sel.map(id => l.find(x => x.id === id)).filter(Boolean);
  const titulo = $("pr-tit").value.trim() || `Evaluación${val("tema") ? " de " + val("tema") : ""}`;
  const vs = $("pr-ver").value === "2" ? ["A", "B"] : ["A"];
  const lineasDe = q => q.tipo === "prob" ? 7 : q.tipo === "des" ? 5 : 0;
  const datos = [["Espacio curricular", labelOf("materia")], ["Curso", $("pr-curso").value.trim() || val("curso")], ["Fecha", $("pr-fecha").value ? fechaCortaIso($("pr-fecha").value) : "____ / ____ / ________"]];
  const inst = val("institucion") || (cursoSel() || {}).escuela || "";
  if (clave){
    const rows = qs.map((q, i) => [String(i + 1), q.e.length > 70 ? q.e.slice(0, 68) + "…" : q.e, ...vs.map(v => {
      if (q.tipo === "vf") return q.ok === "V" ? "Verdadero" : "Falso";
      if (q.tipo !== "mc") return "Desarrollo: ver criterios";
      const ver = versionPrueba(qs, v), qq = ver.find(x => x.id === q.id), pos = qq.perm.indexOf(q.ok), num = ver.indexOf(qq) + 1;
      return `Pregunta ${num}: ${String.fromCharCode(97 + pos)}`;
    }), q.pts || ""]);
    return {inst, titulo:`Clave de corrección: ${titulo}`, subtitulo:"Solo para el docente", faltaSub:"", datos, firmas:null,
      secs:[{h:"Respuestas", tableOnly:true, table:{head:["N.º", "Pregunta (versión A)", ...vs.map(v => `Versión ${v}`), "Puntaje"], w:vs.length > 1 ? [600, 3870, 1700, 1700, 1200] : [600, 5570, 1700, 1200], rows}}]};
  }
  const secs = [];
  vs.forEach((v, k) => {
    const ver = versionPrueba(qs, v);
    secs.push({h:vs.length > 1 ? `Versión ${v}` : "Consignas", pageBreak:k > 0, lead:"Nombre y apellido: ______________________________   Curso: ________   Fecha: ________",
      sub:ver.map((q, i) => ({h:`${i + 1}. ${q.e}${q.pts ? ` (${q.pts} pts)` : ""}`, body:q.tipo === "mc" ? q.perm.map((j, n) => `${String.fromCharCode(97 + n)}) ${q.op[j]}`).join("\n") : q.tipo === "vf" ? "(   ) Verdadero      (   ) Falso" : "", lineas:lineasDe(q)}))});
  });
  return {inst, titulo, subtitulo:temaVisible() || labelOf("materia"), faltaSub:"Tema", datos, secs, firmas:null};
}

/* ---------- Salidas educativas ---------- */
const SAL_KEY = "planificador-salidas-v1";
