function guardarRevision(){
  const j = juntaLeer(), R = (CG.revision || []).filter(v => v.ok !== false).map(v => completarVac({...v}));
  if (!R.length){ toast("No hay cargos marcados para guardar."); return; }
  const modo = (document.querySelector('input[name="cg-modo"]:checked') || {}).value || "reemplazar";
  const antes = JSON.stringify(j), prev = j.vac || [];
  const prevKeys = new Set(prev.map(claveVac)), ahora = Date.now();
  const nuevos = R.map(v => ({...v, id:nuevoIdC("v"), k:claveVac(v), visto:ahora, nuevo:prev.length > 0 && !prevKeys.has(claveVac(v))}));
  nuevos.forEach(v => asignarEscuela(v, j));
  try { registrarPubs(j, prev, nuevos); } catch (e) { logSilencioso(e); }
  if (modo === "sumar"){
    const keys = new Set(prev.map(v => v.k || claveVac(v)));
    j.vac = [...prev, ...nuevos.filter(v => !keys.has(v.k))];
  } else {
    const nk = new Set(nuevos.map(v => v.k));
    j.quitadas = prev.filter(v => !nk.has(v.k || claveVac(v))).map(v => ({materia:v.materia, cargo:v.cargo, escuela:v.escuela}));
    nuevos.forEach(v => { const vieja = prev.find(p => (p.k || claveVac(p)) === v.k); if (vieja){ v.nuevo = vieja.nuevo && ahora - (vieja.visto || 0) < 3 * 864e5; v.visto = vieja.visto || ahora; v.id = vieja.id; if (vieja.diasN) v.diasN = vieja.diasN; } });
    j.vac = nuevos;
  }
  if (!prev.length) j.vac.forEach(v => { v.nuevo = false; });
  try { registrarHist(j, j.vac); } catch (e) { logSilencioso(e); }
  j.ult = ahora;
  if (!juntaGuardar(j)) return;
  CG.revision = null; renderCargos(); renderTuDia();
  const n = j.vac.filter(v => v.nuevo).length;
  toast(`Listado guardado: ${j.vac.length} ${j.vac.length === 1 ? "cargo" : "cargos"}${n ? `, ${n} nuevos` : ""}.`, {label:"Deshacer", fn:() => { localStorage.setItem(JUNTA_KEY, antes); renderCargos(); renderTuDia(); }});
}
async function procesarCapturas(files){
  if (!files || !files.length || CG.leyendo) return;
  CG.leyendo = true;
  const st = $("cg-leyendo"); st.hidden = false; st.textContent = "Leyendo las capturas…";
  try {
    let r = null;
    try { r = await leerConClaude(files); }
    catch (e) { if (e && e.code === "not_granted"){ /* sin permiso: se lee en el dispositivo */ } else if (e && e.code === "rate_limited"){ toast("Claude está ocupado ahora. Se leen en este dispositivo."); } }
    if (r){ CG.origen = "claude"; }
    else {
      st.textContent = "Leyendo las capturas en este dispositivo… la primera vez tarda un poco más.";
      const texto = await leerConTesseract(files, p => { st.textContent = `Leyendo las capturas en este dispositivo… ${Math.round(p * 100)} %`; });
      r = parsearVacantes(texto); CG.origen = "texto"; CG.textoLeido = texto;
    }
    CG.revision = r; renderCargos();
  } catch (e) {
    toast("No se pudieron leer las capturas en este navegador. Probá pegando el texto del listado.");
  } finally { CG.leyendo = false; st.hidden = true; }
}
async function ordenarConClaude(){
  const texto = CG.textoLeido || "";
  if (!caps.sample || !texto.trim()) return;
  const st = $("cg-leyendo"); st.hidden = false; st.textContent = "Claude está ordenando el listado…";
  try {
    const r = await caps.sample.json(PROMPT_VAC.replace("Estas imágenes son capturas de la pantalla", "Este texto se copió o se leyó de la pantalla") + "\n\nTexto:\n" + texto.slice(0, 20000), {modelTier:"default", cache:false});
    if (Array.isArray(r)){ CG.revision = r.map(x => completarVac({materia:x.materia, escuela:x.escuela, localidad:x.localidad, dep:x.departamento, horas:x.horas, cargo:x.cargo, turno:x.turno, revista:x.revista, cierre:x.cierre, detalle:x.detalle})); CG.origen = "claude"; renderCargos(); }
  } catch (e) { toast(e && e.code === "not_granted" ? "Esta página no tiene permiso para usar Claude." : "Claude no pudo ordenar el listado ahora."); }
  finally { st.hidden = true; }
}
function avisosCargos(){
  const j = juntaLeer(), av = [], hoy = hoyIso(), mias = misMateriasJunta();
  const mio = v => esMiMateria(v, mias) && (!(j.zonas || []).length || (j.zonas || []).includes(zonaDe(v, j)) || (j.favEsc || []).includes(norm(v.escuela)));
  const vig = (j.vac || []).filter(v => (!v.cierre || v.cierre >= hoy) && mio(v));
  vig.filter(v => v.nuevo && Date.now() - (v.visto || 0) < 4 * 864e5).slice(0, 2).forEach(v => av.push({f:"1", t:`Nuevo cargo: ${v.materia || v.cargo} en ${v.escuela}${zonaDe(v, j) ? ` (${zonaDe(v, j)})` : ""}${v.cierre ? `, cierra el ${dm(fechaDe(v.cierre))}` : ""}.`, act:"cargos"}));
  const en2 = (() => { const d = new Date(); d.setDate(d.getDate() + 2); return isoDe(d); })();
  const urg = vig.filter(v => v.cierre && v.cierre <= en2 && !v.nuevo);
  if (urg.length) av.push({f:urg[0].cierre, t:`${urg.length === 1 ? `Cierra el ${dm(fechaDe(urg[0].cierre))} la postulación a ${urg[0].materia || urg[0].cargo} en ${urg[0].escuela}` : `${urg.length} cargos de tus materias cierran en los próximos dos días`}.`, act:"cargos"});
  const dia = new Date().getDay();
  if ((j.recDias || []).includes(dia) && (!j.ult || isoDe(new Date(j.ult)) !== hoy)) av.push({f:"2", t:"Hoy toca revisar las vacantes del SIME: sacá una captura y cargala en «Cargos disponibles».", act:"cargos"});
  const L = leerLista(LEG_KEY, {}), d7 = (() => { const d = new Date(); d.setDate(d.getDate() + 7); return isoDe(d); })();
  (L.juntaf || []).forEach(x => {
    if (x.desde && x.desde >= hoy && x.desde <= d7) av.push({f:x.desde, t:`Junta: desde el ${dm(fechaDe(x.desde))}, ${x.que}.`, act:"legajo"});
    else if (x.hasta && x.hasta >= hoy && x.hasta <= d7 && (!x.desde || x.desde <= hoy)) av.push({f:x.hasta, t:`Junta: hasta el ${dm(fechaDe(x.hasta))}, ${x.que}.`, act:"legajo"});
  });
  try { av.push(...avisosPost()); } catch (e) { logSilencioso(e); }
  try { av.push(...avisosProteccion()); } catch (e) { logSilencioso(e); }
  return av;
}

