/* ============================================================
   Planilla con el formato de la escuela
   ============================================================ */
function clasificarColumna(t){
  const n = norm(t).replace(/[.:°º]/g, " ").replace(/\s+/g, " ").trim();
  if (!n) return "blank";
  if (/^(n|nro|num|numero|orden|n de orden)$/.test(n) || /^n\s?o$/.test(n)) return "num";
  if (/apellido|nombre|alumn|estudiante/.test(n)) return "nombre";
  if (/promedio/.test(n)) return "prom";
  if (/conducta|concepto/.test(n)) return "cond";
  if (/recuper|complementari/.test(n)) return "rec";
  if (/inasist|falta|ausen/.test(n)) return "faltas";
  if (/tard|llegada/.test(n)) return "tardes";
  if (/observ/.test(n)) return "obs";
  if (/parcial|evaluaci|\beval\b|^ev\b|^tp|trabajo|examen|prueba|leccion/.test(n)) return "parciales";
  if (/nota|calificaci|trimestr|cuatrimestr|periodo|definitiv|final/.test(n)) return "nota";
  if (/dni|documento/.test(n)) return "blank";
  return "blank";
}
function filasPrecFormato(c, p, tpl){
  const als = alumnosActivos(c), evs = evalsDe(c, p), head = [];
  tpl.cols.forEach(col => { if (col.k === "parciales") (evs.length ? evs : [{t:col.t}]).forEach(e => head.push(evs.length ? e.t : col.t)); else head.push(col.t); });
  const rows = als.map((a, i) => {
    const r = [], ar = asisResumen(c, a.id, p), pp = ((c.per || {})[a.id] || {})["p" + p] || {};
    tpl.cols.forEach(col => {
      switch (col.k){
        case "num": r.push(i + 1); break;
        case "nombre": r.push(a.n); break;
        case "parciales": (evs.length ? evs : [null]).forEach(e => r.push(e ? (notaEval(c, a.id, e.id) ?? "") : "")); break;
        case "prom": { const v = promPeriodo(c, a.id, p); r.push(v == null ? "" : Math.round(v * 100) / 100); break; }
        case "cond": r.push(ajusteC(c, a.id, p) || ""); break;
        case "nota": r.push(notaPeriodo(c, a.id, p) ?? ""); break;
        case "rec": r.push(esNumC(pp.rec) ? aNumC(pp.rec) : ""); break;
        case "faltas": r.push(ar.clases ? ar.A + (ar.R * 0.5) : ""); break;
        case "tardes": r.push(ar.clases ? ar.T : ""); break;
        default: r.push("");
      }
    });
    return r;
  });
  return {head, rows};
}
async function leerZip(buf){
  const dv = new DataView(buf), u8 = new Uint8Array(buf), dec = new TextDecoder();
  let e = -1;
  for (let i = buf.byteLength - 22; i >= Math.max(0, buf.byteLength - 66000); i--) if (dv.getUint32(i, true) === 0x06054b50){ e = i; break; }
  if (e < 0) throw new Error("zip");
  const n = dv.getUint16(e + 10, true); let off = dv.getUint32(e + 16, true);
  const ent = {};
  for (let k = 0; k < n; k++){
    const met = dv.getUint16(off + 10, true), csz = dv.getUint32(off + 20, true), nl = dv.getUint16(off + 28, true), xl = dv.getUint16(off + 30, true), cl = dv.getUint16(off + 32, true), lo = dv.getUint32(off + 42, true);
    const name = dec.decode(u8.subarray(off + 46, off + 46 + nl));
    ent[name] = {met, csz, lo};
    off += 46 + nl + xl + cl;
  }
  return async name => {
    const x = ent[name]; if (!x) return null;
    const start = x.lo + 30 + dv.getUint16(x.lo + 26, true) + dv.getUint16(x.lo + 28, true), data = u8.slice(start, start + x.csz);
    if (x.met === 0) return dec.decode(data);
    if (typeof DecompressionStream === "undefined") throw new Error("inflate");
    const ab = await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).arrayBuffer();
    return dec.decode(ab);
  };
}
async function columnasDeXlsx(file){
  const get = await leerZip(await file.arrayBuffer());
  const P = new DOMParser(), ss = await get("xl/sharedStrings.xml"), strs = [];
  if (ss) P.parseFromString(ss, "application/xml").querySelectorAll("si").forEach(si => strs.push([...si.querySelectorAll("t")].map(t => t.textContent).join("")));
  const sh = await get("xl/worksheets/sheet1.xml");
  if (!sh) throw new Error("hoja");
  const filas = [];
  P.parseFromString(sh, "application/xml").querySelectorAll("row").forEach(row => {
    const r = [];
    row.querySelectorAll("c").forEach(c => {
      const ref = c.getAttribute("r") || "", col = ref.replace(/\d+/g, "").split("").reduce((s, ch) => s * 26 + ch.charCodeAt(0) - 64, 0) - 1;
      const t = c.getAttribute("t"), v = c.querySelector("v");
      let val = t === "s" ? strs[+(v ? v.textContent : -1)] : t === "inlineStr" ? [...c.querySelectorAll("t")].map(x => x.textContent).join("") : (v ? v.textContent : "");
      if (col >= 0) r[col] = String(val ?? "").trim();
    });
    filas.push(r);
  });
  let mejor = null, pm = 1;
  filas.slice(0, 40).forEach(r => { const cel = [...r].map(x => x || ""); const pts = cel.filter(x => x && !/^\d+([.,]\d+)?$/.test(x) && clasificarColumna(x) !== "blank").length; if (pts > pm){ pm = pts; mejor = cel; } });
  if (!mejor) throw new Error("cabecera");
  return mejor.filter(x => x).map(t => ({t, k:clasificarColumna(t)}));
}
async function columnasDeFoto(file){
  const lim = await puedeVerImagenes();
  if (!lim) return null;
  const r = await caps.sample.json(`Esta imagen es una foto o una captura de la planilla de calificaciones que usa una escuela secundaria. Devolvé solo un array JSON con los títulos de las columnas, de izquierda a derecha, tal como aparecen (por ejemplo ["N.º","Apellido y nombre","1.er trimestre","Inasistencias"]). Si un título ocupa dos renglones, unilo en uno. No incluyas datos de estudiantes ni notas.`, {images:[file], modelTier:"default", cache:false});
  return Array.isArray(r) ? r.map(t => String(t).trim()).filter(Boolean).map(t => ({t, k:clasificarColumna(t)})) : null;
}
async function cargarFormatoEscuela(c, file){
  if (!file) return;
  let cols = null;
  try {
    if (/\.xlsx$/i.test(file.name) || /spreadsheetml/.test(file.type)) cols = await columnasDeXlsx(file);
    else if (/^image\//.test(file.type)){
      cols = await columnasDeFoto(file);
      if (!cols){ toast("Para leer una foto hace falta usar el planificador con tu cuenta de Claude. Probá con la planilla en Excel."); return; }
    } else { toast("Subí la planilla en Excel (.xlsx) o una foto."); return; }
  } catch (e) { toast(e && e.code === "not_granted" ? "Esta página no tiene permiso para usar Claude." : "No se pudieron leer las columnas de ese archivo."); return; }
  if (!cols || cols.length < 2 || !cols.some(x => x.k === "nombre")){ toast("No encontré los títulos de las columnas (por ejemplo «Apellido y nombre»). Probá con otro archivo."); return; }
  c.formatoPrec = {cols, origen:file.name || "foto"}; c.usarFormato = true; cguardar(); reCur();
  const des = cols.filter(x => x.k === "blank").length;
  toast(`Formato copiado: ${cols.length} columnas.${des ? ` ${des} quedan en blanco para completar a mano.` : ""}`);
}

/* ============================================================
   Evidencias por estudiante
   ============================================================ */
async function pintarFotosEst(c){
  const cont = $("ev-fotos"); if (!cont || !c) return;
  try {
    const fs = (await fotosTodas()).filter(x => x.cid === c.id && x.aid === CUR.famAid);
    cont.innerHTML = fs.map(x => `<span class="foto"><img src="${x.data}" alt="${x.cat === "prueba" ? esc(x.t || "Prueba") : "Evidencia"} del ${dm(fechaDe(x.f))}">${x.cat === "prueba" ? `<small class="foto-t">${esc(x.t || "Prueba")} · ${dm(fechaDe(x.f))}</small>` : ""}<button type="button" class="seg-x" data-fotodel="${x.id}" aria-label="Borrar la foto">×</button></span>`).join("");
    const k = $("ev-cuenta"); if (k) k.textContent = fs.length ? `(${fs.length})` : "";
  } catch (e) { cont.innerHTML = ""; }
}

/* ============================================================
   Eventos
   ============================================================ */
function bindNuevas13(){
  $("btn-cargos").addEventListener("click", abrirCargos);
  $("cg-file").addEventListener("change", e => { const fs = [...(e.target.files || [])]; e.target.value = ""; procesarCapturas(fs); });
  $("cg-pegar").addEventListener("click", () => { const b = $("cg-pegar-box"); b.hidden = !b.hidden; if (!b.hidden) $("cg-txt").focus(); });
  $("cg-leer").addEventListener("click", () => {
    const t = $("cg-txt").value;
    if (!t.trim()){ toast("Pegá primero el listado del SIME."); return; }
    CG.revision = parsearVacantes(t); CG.origen = "texto"; CG.textoLeido = t; $("cg-txt").value = ""; $("cg-pegar-box").hidden = true; renderCargos();
  });
  const P = $("cg-panel");
  P.addEventListener("click", e => {
    const b = e.target.closest("[data-cg]"), j = juntaLeer();
    if (b){
      const a = b.dataset.cg;
      if (a === "mias"){ j.soloMias = !j.soloMias; juntaGuardar(j); renderCargos(); }
      else if (a === "junta"){ cerrarDialogo("cargos"); legTab = "junta"; $("btn-legajo").click(); }
      else if (a === "guardar") guardarRevision();
      else if (a === "descartar"){ CG.revision = null; renderCargos(); }
      else if (a === "claude") ordenarConClaude();
      else if (a === "borrar"){ if (window.confirm("¿Borrar el listado de vacantes cargado?")){ j.vac = []; j.quitadas = []; j.ult = 0; juntaGuardar(j); renderCargos(); renderTuDia(); } }
      return;
    }
    const f = e.target.closest("[data-cgfav]");
    if (f){ const k = f.dataset.cgfav; j.favEsc = (j.favEsc || []).includes(k) ? j.favEsc.filter(x => x !== k) : [...(j.favEsc || []), k]; juntaGuardar(j); renderCargos(); return; }
    const z = e.target.closest("[data-cgzon]");
    if (z){ const d = z.dataset.cgzon; j.zonas = (j.zonas || []).includes(d) ? j.zonas.filter(x => x !== d) : [...(j.zonas || []), d]; juntaGuardar(j); renderCargos(); P.querySelector(".cg-cfg").closest("details").open = true; renderTuDia(); return; }
    const r = e.target.closest("[data-cgrec]");
    if (r){ const d = +r.dataset.cgrec; j.recDias = (j.recDias || []).includes(d) ? j.recDias.filter(x => x !== d) : [...(j.recDias || []), d]; juntaGuardar(j); renderCargos(); P.querySelector(".cg-cfg").closest("details").open = true; renderTuDia(); }
  });
  P.addEventListener("input", e => {
    const t = e.target;
    if (t.dataset.rv){ const [i, k] = t.dataset.rv.split(":"); const v = CG.revision[+i]; if (k === "ok"){ v.ok = t.checked; t.closest("tr").classList.toggle("off", !t.checked); } else { v[k] = t.value; if (k === "materia" && v.cargo && !v.materia) v.cargo = ""; } return; }
    if (t.dataset.cgf === "q"){ CG.q = t.value; const pos = t.selectionStart; renderCargos(); const n = $("cg-q"); if (n){ n.focus(); try { n.setSelectionRange(pos, pos); } catch (er) { logSilencioso(er); } } }
  });
  P.addEventListener("change", e => {
    const t = e.target, j = juntaLeer();
    if (t.dataset.cgf && t.dataset.cgf !== "q"){ CG[t.dataset.cgf] = t.dataset.cgf === "tmax" ? +t.value || 0 : t.value; renderCargos(); return; }
    if (t.dataset.cgzona != null && t.value){ j.escZona = {...(j.escZona || {}), [t.dataset.cgzona]:t.value}; juntaGuardar(j); renderCargos(); renderTuDia(); }
  });
  $("leg-panel").addEventListener("click", e => { if (e.target.closest("[data-legcargos]")){ cerrarDialogo("legajo"); abrirCargos(); } });
  /* Planilla con el formato de la escuela y evidencias por estudiante */
  $("cur-panel").addEventListener("change", async e => {
    const t = e.target, c = cursoSel(); if (!c) return;
    if (t.dataset.fmt === "archivo"){ const f = t.files && t.files[0]; t.value = ""; await cargarFormatoEscuela(c, f); return; }
    if (t.dataset.fmt === "usar"){ c.usarFormato = t.checked; cguardar(); reCur(); return; }
    if (t.dataset.fotoest){ const f = t.files && t.files[0]; t.value = ""; await agregarFoto(f, c.id, hoyIso(), t.dataset.fotoest); await pintarFotosEst(c); const bx = $("ev-box"); if (bx) bx.open = true; }
  });
  $("cur-panel").addEventListener("click", e => {
    const q = e.target.closest('[data-fmt="quitar"]'); if (!q) return;
    const c = cursoSel(); if (!c || !window.confirm("¿Quitar el formato de tu escuela? La planilla vuelve a las columnas elegidas.")) return;
    delete c.formatoPrec; c.usarFormato = false; cguardar(); reCur();
  });
}

