const ESC_FUENTE = "Padrón Oficial de Establecimientos Educativos (abril de 2022)";
const MEDIOS = {auto:{t:"Auto", gm:"driving"}, moto:{t:"Moto", gm:"driving"}, colectivo:{t:"Colectivo", gm:"transit"}, bici:{t:"Bicicleta", gm:"bicycling"}, pie:{t:"A pie", gm:"walking"}};
const TIPOS_ESC = new Set(["tecnica", "agrotecnica", "normal", "superior", "ceja", "cens", "especial", "comercio", "artistica", "nacional", "provincial", "adultos", "jovenes", "bachillerato", "comercial", "media"]);
const GENERICAS = new Set(["escuela", "colegio", "instituto", "de", "del", "la", "las", "los", "el", "y", "e", "n", "nro", "numero", "provincia", "prov", "tucuman", "anexo", "sede", "subsede", "secundaria", "educacion"]);
const ABREV = [[/\besc\b/g, "escuela"], [/\bcol\b/g, "colegio"], [/\binst\b/g, "instituto"], [/\bsec\b/g, "secundaria"], [/\btec\b/g, "tecnica"], [/\bagrotec\b/g, "agrotecnica"], [/\bsuper\b/g, "superior"], [/\beduc\b/g, "educacion"], [/\bprof\b/g, "profesor"], [/\bdr\b/g, "doctor"], [/\bgral\b/g, "general"], [/\bpte\b/g, "presidente"], [/\bsta\b/g, "santa"], [/\bsto\b/g, "santo"], [/\bnro\b|\bnum\b|\bnumero\b|\bno\b/g, "n"]];
function normEsc(s){
  let t = norm(s || "").replace(/\bn\s*\.?\s*[°º*o]?\s*\.?\s*(?=\d)/g, " n ").replace(/[°º]/g, " ").replace(/[.\-_/,;:()"«»]/g, " ").replace(/\s+/g, " ").trim();
  ABREV.forEach(([rx, r]) => { t = t.replace(rx, r); });
  t = t.replace(/\be\s?e\s?t\b|\beet\b/g, "escuela tecnica").replace(/\bc\s?e\s?j\s?a\b/g, "ceja").replace(/\bc\s?e\s?n\s?s\b/g, "cens");
  return t;
}
function numEsc(t){ const m = t.match(/\bn\s?(\d{1,4})\b/) || t.match(/\b(\d{1,4})\b/); return m ? m[1] : ""; }
const tokensEsc = t => new Set(t.split(" ").filter(w => w.length > 2 && !GENERICAS.has(w) && !TIPOS_ESC.has(w) && !/^\d+$/.test(w)));
const ESC_IDX = ESC_TUC.map(e => { const t = normEsc(e[1]); return {e, t, num:numEsc(t), tok:tokensEsc(t), loc:norm(e[4]), dep:e[5]}; });
const escPorCue = cue => ESC_TUC.find(e => e[0] === cue) || null;
function candidatosEscuela(v){
  const txt = [v.escuela, v.detalle].join(" "), cue = (txt.match(/\b90\d{7}\b/) || [])[0];
  if (cue && escPorCue(cue)) return [{e:escPorCue(cue), s:99}];
  const t = normEsc(v.escuela || ""), num = numEsc(t), tok = tokensEsc(t);
  const loc = norm(v.localidad || ""), dep = DEPTOS.findIndex(d => d === v.dep);
  if (!t) return [];
  const tipo = w => ["tecnica", "agrotecnica", "normal", "ceja", "cens", "especial", "comercio", "artistica", "media"].filter(x => new RegExp("\\b" + x + "\\b").test(w));
  const tt = tipo(t);
  return ESC_IDX.map(x => {
    let s = 0, base = false;
    if (num && x.num){ s += num === x.num ? 3 : -3; base = base || num === x.num; }
    else if (num && !x.num) s -= 1;
    else if (!num && x.num) s -= 1;
    const inter = [...tok].filter(w => x.tok.has(w)).length, uni = new Set([...tok, ...x.tok]).size || 1;
    s += 4 * inter / uni + (inter ? 0.5 * inter : 0); base = base || inter > 0;
    const locOk = loc && (x.loc === loc || x.loc.includes(loc) || loc.includes(x.loc));
    if (locOk) s += 2;
    if (dep > -1 && x.dep === dep) s += 1;
    const xt = tipo(x.t); if (tt.length){ const ok = tt.some(w => xt.includes(w)); s += ok ? 0.8 : -0.8; base = base || (ok && locOk); }
    return {e:x.e, s:base ? s : 0};
  }).filter(r => r.s >= 1.5).sort((a, b) => b.s - a.s).slice(0, 6);
}
function aplicarEscuela(v, e){
  v.cue = e[0]; v.dir = e[3]; v.localidad = e[4]; v.dep = DEPTOS[e[5]] || v.dep; v.tel = e[6]; v.lat = e[7]; v.lon = e[8]; v.prec = e[9]; v.escOficial = e[1]; v.amb = undefined;
}
function asignarEscuela(v, j){
  if (v.cue && escPorCue(v.cue)) { aplicarEscuela(v, escPorCue(v.cue)); return; }
  const k = norm(v.escuela || ""), guardada = (j.escCue || {})[k];
  if (guardada && escPorCue(guardada)){ aplicarEscuela(v, escPorCue(guardada)); return; }
  const c = candidatosEscuela(v);
  if (c.length && c[0].s >= 3 && (!c[1] || c[0].s - c[1].s >= 1.5)) aplicarEscuela(v, c[0].e);
  else v.amb = c.slice(0, 5).map(x => x.e[0]);
}

/* ---------- Distancia y tiempo de viaje (aproximados) ---------- */
function kmEntre(a, b){
  const R = 6371, r = x => x * Math.PI / 180, dLa = r(b.lat - a.lat), dLo = r(b.lon - a.lon);
  const h = Math.sin(dLa / 2) ** 2 + Math.cos(r(a.lat)) * Math.cos(r(b.lat)) * Math.sin(dLo / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
function minutosViaje(km, medio){
  const calle = km * (km < 8 ? 1.4 : 1.25);
  const urb = Math.min(calle, 8), ruta = Math.max(0, calle - 8);
  const V = {auto:[28, 75], moto:[28, 70], colectivo:[16, 42], bici:[14, 16], pie:[4.5, 4.5]}[medio] || [28, 75];
  let min = (urb / V[0] + ruta / V[1]) * 60;
  if (medio === "colectivo") min += 10;
  if (medio === "auto" || medio === "moto") min += 3;
  return {km:calle, min:Math.max(1, Math.round(min))};
}
const fmtMin = m => m < 60 ? `${m} min` : `${Math.floor(m / 60)} h${m % 60 ? ` ${m % 60} min` : ""}`;
const fmtKm = k => k < 10 ? coma(Math.round(k * 10) / 10) : String(Math.round(k));
function origenActual(j){ return (j.origenes || []).find(o => o.id === j.origen) || (j.origenes || [])[0] || null; }
function viajeDe(v, j){
  const o = origenActual(j);
  if (!o || v.lat == null || o.lat == null) return null;
  const medio = j.medio || "auto", r = minutosViaje(kmEntre(o, v), medio), md = medidoDe(v, j);
  return {...r, ...(md ? {min:md, medido:true} : {}), medio, o};
}
function minutosIda(v, j){ const r = viajeDe(v, j); return r ? r.min : null; }
const DIAS_RX = [["lunes", 1], ["martes", 2], ["miercoles", 3], ["jueves", 4], ["viernes", 5], ["sabado", 6]];
function diasDeVac(v){
  if (v.dias) return v.dias;
  const t = norm([v.detalle, v.turno].join(" ")), d = DIAS_RX.filter(([n]) => new RegExp("\\b" + n + "\\b").test(t)).map(x => x[1]);
  return d.length ? d : null;
}
function superposicion(v){
  const dias = diasDeVac(v); if (!dias || !v.turno) return [];
  const rango = {"mañana":[7, 13], "manana":[7, 13], "tarde":[13, 19], "noche":[19, 24], "vespertino":[17, 23], "intermedio":[11, 15]}[norm(v.turno)];
  if (!rango) return [];
  const out = [];
  cdatos().cursos.forEach(c => (c.horario || []).forEach(h => { const hi = +String(h.ini || "").split(":")[0]; if (dias.includes(+h.dia) && hi >= rango[0] && hi < rango[1]) out.push(`${c.curso} los ${DIAS_SEM[+h.dia]} a las ${h.ini}`); }));
  return [...new Set(out)];
}
function enlaceRecorrido(v, j){
  const o = origenActual(j), med = MEDIOS[j.medio || "auto"].gm;
  const dest = v.lat != null && v.prec ? `${v.lat},${v.lon}` : [v.escOficial || v.escuela, v.dir, v.localidad, "Tucumán"].filter(Boolean).join(", ");
  const ori = o ? (o.dir ? `${o.dir}, ${o.loc || ""}, Tucumán` : `${o.lat},${o.lon}`) : "";
  return `https://www.google.com/maps/dir/?api=1${ori ? `&origin=${encodeURIComponent(ori)}` : ""}&destination=${encodeURIComponent(dest)}&travelmode=${med}`;
}
function enlaceMapa(v){
  const q = v.lat != null && v.prec ? `${v.lat},${v.lon}` : [v.escOficial || v.escuela, v.dir, v.localidad, "Tucumán"].filter(Boolean).join(", ");
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
}
function costoViaje(km, j, v){
  const c = j.costo || {};
  if ((j.medio || "auto") === "colectivo"){ if (v){ try { const P = planCole(v, j); if (P && P.precio) return P.precio.iv || 2 * P.precio.ida; } catch (e) { logSilencioso(e); } } return +c.boleto > 0 ? 2 * +c.boleto : null; }
  if (["auto", "moto"].includes(j.medio || "auto")) return +c.litro > 0 && +c.kml > 0 ? 2 * km / +c.kml * +c.litro / Math.max(1, +c.comparten || 1) : null;
  return null;
}
function numAR(x){ let s = String(x || "").trim().replace(/[$\s]/g, ""); if (s.includes(",")) s = s.replace(/\./g, "").replace(",", "."); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ""); return parseFloat(s); }
const pesos = n => "$" + Math.round(n).toLocaleString("es-AR");

/* ---------- Pantalla: escuela y viaje dentro de cada cargo ---------- */
function htmlEscuelaViajeV48(v, j){
  const k = norm(v.escuela || ""), id = v.id;
  let h = "";
  if (v.cue){
    h += `<div class="cg-dir"><span>${esc(v.dir || "Sin domicilio en el padrón")}${v.localidad ? `, ${esc(v.localidad)}` : ""}${v.dep ? ` (${esc(v.dep)})` : ""}</span>
      ${v.escOficial && normEsc(v.escOficial) !== normEsc(v.escuela) ? `<small>En el padrón: ${esc(v.escOficial)}${v.prec ? "" : " · ubicación aproximada"}</small>` : v.prec ? "" : `<small>Ubicación aproximada (centro de la localidad)</small>`}</div>`;
  } else if ((v.amb || []).length){
    h += `<div class="cg-amb"><label for="amb-${id}">¿Cuál es esta escuela?</label><select id="amb-${id}" data-cgesc="${id}"><option value="">Elegí la escuela</option>${v.amb.map(c => { const e = escPorCue(c); return e ? `<option value="${c}">${esc(e[1])} · ${esc(e[3])}, ${esc(e[4])}</option>` : ""; }).join("")}<option value="buscar">No es ninguna: buscar…</option></select></div>`;
  } else {
    h += `<div class="cg-zona">${v.dep ? esc([...new Set([v.localidad, v.dep].filter(Boolean))].join(" · ")) : ""} <button type="button" class="linkbtn" data-cgbus="${id}">Buscar la escuela para ver la dirección</button></div>`;
  }
  if (CG.buscando === id) h += `<div class="cg-bus"><label class="sr-only" for="bus-${id}">Buscar escuela</label><input id="bus-${id}" type="search" data-cgbq="${id}" placeholder="Nombre, número o localidad" value="${esc(CG.busq || "")}"><ul class="cg-bres" id="bres-${id}">${htmlBusqueda(CG.busq || v.escuela || "")}</ul></div>`;
  const r = viajeDe(v, j);
  if (r){
    const dias = diasDeVac(v) || diasSeg(v, j), sem = dias ? dias.length : (+v.diasN || 0), cst = costoViaje(r.km, j, v);
    if (r.km < 0.4) h += `<div class="cg-viaje"><b>Queda a menos de 400 metros de ${esc(r.o.nombre)}</b></div>`;
    else h += `<div class="cg-viaje"><b>${MEDIOS[r.medio].t}: ${fmtMin(r.min)} de ida${r.medido ? " (medido por vos)" : ""} · ${fmtMin(2 * r.min)} ida y vuelta</b><span>${fmtKm(r.km)} km aprox. desde ${esc(r.o.nombre)}${sem ? ` · ${fmtMin(2 * r.min * sem)} por semana (${sem} ${sem === 1 ? "día" : "días"})` : ""}${cst ? ` · ${pesos(cst)} por día${sem ? `, ${pesos(cst * sem)} por semana` : ""}` : ""}</span></div>`;
  } else if (v.cue && !origenActual(j)) h += `<div class="cg-viaje sin"><button type="button" class="linkbtn" data-cg="partida">Elegí desde dónde salís para ver el tiempo de viaje</button></div>`;
  const sp = superposicion(v);
  if (sp.length) h += `<p class="cg-sup">Puede superponerse con tus clases: ${esc(sp.join("; "))}.</p>`;
  return h;
}
function htmlAccionesCargo(v, j){
  return `<div class="cg-acc2"><a class="btn btn-sm" href="${SIME_URL}" target="_blank" rel="noopener">Postularme en el SIME</a>
    ${v.cue || v.escuela ? `<a class="btn btn-sm" href="${enlaceRecorrido(v, j)}" target="_blank" rel="noopener">Ver el recorrido</a><a class="btn btn-sm" href="${enlaceMapa(v)}" target="_blank" rel="noopener">Ver en el mapa</a>` : ""}
    ${v.tel ? `<a class="btn btn-sm" href="tel:${esc(v.tel.replace(/[^\d+]/g, "").slice(0, 13))}">Llamar a la escuela</a>` : ""}
    ${!diasDeVac(v) && !diasSeg(v, j) && origenActual(j) && v.cue ? `<label class="cg-dn">Días por semana <select data-cgdias="${v.id}"><option value="">—</option>${[1, 2, 3, 4, 5].map(n => `<option${+v.diasN === n ? " selected" : ""}>${n}</option>`).join("")}</select></label>` : ""}</div>`;
}
function htmlBusqueda(q){
  const t = normEsc(q), ws = t.split(" ").filter(w => w.length > 1 && !GENERICAS.has(w));
  if (!ws.length) return `<li class="hint">Escribí parte del nombre, el número o la localidad.</li>`;
  const res = ESC_IDX.filter(x => ws.every(w => (x.t + " " + x.loc).includes(w))).slice(0, 8);
  return res.length ? res.map(x => `<li><button type="button" data-cgpick="${x.e[0]}"><b>${esc(x.e[1])}</b><small>${esc(x.e[3])}, ${esc(x.e[4])} (${esc(DEPTOS[x.e[5]])})</small></button></li>`).join("") : `<li class="hint">No encontré escuelas con esas palabras.</li>`;
}
function htmlPartida(j){
  const os = j.origenes || [], o = origenActual(j);
  return `<details class="cur-sub cg-partida"${CG.partidaAbierta || !os.length ? " open" : ""}><summary>${o ? `Viaje desde <b>${esc(o.nombre)}</b> en ${esc(MEDIOS[j.medio || "auto"].t.toLowerCase())}${j.valorHora ? "" : " · cargá el valor de la hora para ver cuánto rinde"}` : "Elegí desde dónde salís para ver el tiempo de viaje"}</summary>
    <div class="cg-cfg">
      ${os.length ? `<div class="cg-ors">${os.map(x => `<span class="cg-or"><button type="button" class="chip chip-sm" data-cgor="${x.id}" aria-pressed="${o && o.id === x.id}">${esc(x.nombre)}</button><button type="button" class="seg-x" data-cgordel="${x.id}" aria-label="Borrar ${esc(x.nombre)}">×</button></span>`).join("")}</div>` : ""}
      <div class="seg cg-medio" role="group" aria-label="Medio de transporte">${Object.entries(MEDIOS).map(([k, m]) => `<button type="button" data-cgmed="${k}" aria-pressed="${(j.medio || "auto") === k}">${m.t}</button>`).join("")}</div>
      <p class="hint">Agregar un lugar de partida:</p>
      <div class="cfg-grid">
        <div class="f"><label for="or-n">Nombre</label><input id="or-n" placeholder="Ej.: Casa" value="${os.length ? "" : "Casa"}"></div>
        <div class="f"><label for="or-loc">Localidad</label><input id="or-loc" list="or-locs" placeholder="Escribí y elegí de la lista"><datalist id="or-locs">${LOC_TUC.map(l => `<option value="${esc(l[0])} (${esc(DEPTOS[l[1]])})"></option>`).join("")}</datalist></div>
        <div class="f full"><label for="or-dir">Dirección (opcional, para el recorrido exacto en Google Maps)</label><input id="or-dir" placeholder="Ej.: San Martín 450"></div>
      </div>
      <div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-cg="or-add">Guardar el lugar</button><button type="button" class="btn btn-sm" data-cg="or-gps">Usar mi ubicación actual</button><button type="button" class="btn btn-sm" data-cg="or-esc">Desde una escuela donde trabajo</button></div>
      <div id="or-escs"></div>
      <p class="hint">Costo del viaje (opcional): <label>litro de combustible $<input class="cg-n2" data-cgcost="litro" inputmode="decimal" value="${esc((j.costo || {}).litro || "")}"></label> <label>km por litro <input class="cg-n2" data-cgcost="kml" inputmode="decimal" value="${esc((j.costo || {}).kml || "")}"></label> <label>boleto de colectivo $<input class="cg-n2" data-cgcost="boleto" inputmode="decimal" value="${esc((j.costo || {}).boleto || "")}"></label></p>
      <p class="hint">Para saber cuánto rinde cada cargo: <label>valor de la hora cátedra por mes $<input class="cg-n2" data-cgval="valorHora" inputmode="decimal" value="${esc(j.valorHora || "")}"></label> <label>tope de horas cátedra <input class="cg-n2" data-cgval="topeHoras" inputmode="numeric" value="${esc(j.topeHoras || "")}"></label></p><p class="hint">No hay un máximo de horas publicado para Tucumán: al tomar un cargo presentás la declaración jurada de cargos y, si hay incompatibilidad, tenés 48 horas para resolverla.</p>
      <p class="hint">¿Compartís el viaje? <label>personas en el auto <select data-cgcost="comparten">${[1, 2, 3, 4].map(n => `<option${(+((j.costo || {}).comparten) || 1) === n ? " selected" : ""}>${n}</option>`).join("")}</select></label> (el costo del combustible se divide entre todos)</p>
      <p class="hint">El valor de la hora cambia con cada paritaria: cargá el de tu recibo. El tope es el que fija el régimen de incompatibilidades vigente para tu cargo.</p>
      <p class="hint">El tiempo es aproximado: se calcula con la distancia y velocidades promedio. Para el tiempo real, con tránsito y horarios de colectivo, tocá «Ver el recorrido». Tus lugares se guardan solo en este dispositivo.</p>
    </div></details>`;
}
function locDeTexto(s){
  const t = norm(String(s || "").replace(/\s*\(.*\)\s*$/, "")), dep = (String(s || "").match(/\(([^)]+)\)\s*$/) || [])[1];
  const ls = LOC_TUC.filter(l => norm(l[0]) === t);
  return (dep ? ls.find(l => DEPTOS[l[1]] === dep) : null) || ls[0] || LOC_TUC.find(l => norm(l[0]).startsWith(t)) || null;
}
function agregarOrigen(o){
  const j = juntaLeer();
  o.id = nuevoIdC("o"); j.origenes = [...(j.origenes || []), o]; j.origen = o.id;
  juntaGuardar(j); CG.partidaAbierta = false; renderCargos(); toast(`Lugar de partida guardado: ${o.nombre}.`);
}
function reasignarEscuelas(){
  const j = juntaLeer(); let n = 0;
  (j.vac || []).forEach(v => { if (!v.cue){ asignarEscuela(v, j); if (v.cue) n++; } });
  if (n) juntaGuardar(j);
}

function bindEscuelas(){
  const P = $("cg-panel");
  P.addEventListener("click", e => {
    const t = e.target, j = juntaLeer();
    const b = t.closest("[data-cg]");
    if (b){
      const a = b.dataset.cg;
      if (a === "partida"){ CG.partidaAbierta = true; renderCargos(); const d = P.querySelector(".cg-partida"); if (d){ d.open = true; d.scrollIntoView({block:"nearest"}); } return; }
      if (a === "or-add"){
        const l = locDeTexto($("or-loc").value);
        if (!l){ toast("Elegí la localidad de la lista."); $("or-loc").focus(); return; }
        agregarOrigen({nombre:$("or-n").value.trim() || "Casa", loc:l[0], dep:DEPTOS[l[1]], dir:$("or-dir").value.trim(), lat:l[2], lon:l[3]});
        return;
      }
      if (a === "or-gps"){
        if (!navigator.geolocation){ toast("Este navegador no permite usar la ubicación. Elegí la localidad."); return; }
        navigator.geolocation.getCurrentPosition(p => agregarOrigen({nombre:$("or-n") && $("or-n").value.trim() || "Mi ubicación", lat:Math.round(p.coords.latitude * 1e5) / 1e5, lon:Math.round(p.coords.longitude * 1e5) / 1e5, dir:"", loc:""}),
          () => toast("No se pudo obtener tu ubicación desde acá. Elegí la localidad y escribí la dirección."), {timeout:10000, maximumAge:600000});
        return;
      }
      if (a === "or-esc"){
        const cs = (leerLista(LEG_KEY, {}).cargos || []).filter(x => x.escuela && !x.baja);
        const box = $("or-escs");
        if (!cs.length){ box.innerHTML = `<p class="hint">Cargá las escuelas donde trabajás en «Mi legajo › Cargos y horas».</p>`; return; }
        box.innerHTML = `<div class="chips chips-row">${cs.map(x => { const c = candidatosEscuela({escuela:x.escuela})[0]; return c ? `<button type="button" class="chip chip-sm" data-cgoresc="${c.e[0]}">${esc(c.e[1])}</button>` : `<span class="hint">${esc(x.escuela)}: no la encontré en el padrón</span>`; }).join("")}</div>`;
        return;
      }
      return;
    }
    const oe = t.closest("[data-cgoresc]");
    if (oe){ const e2 = escPorCue(oe.dataset.cgoresc); if (e2 && e2[7] != null) agregarOrigen({nombre:e2[1], loc:e2[4], dep:DEPTOS[e2[5]], dir:e2[3], lat:e2[7], lon:e2[8]}); return; }
    const or = t.closest("[data-cgor]");
    if (or){ j.origen = or.dataset.cgor; juntaGuardar(j); renderCargos(); return; }
    const od = t.closest("[data-cgordel]");
    if (od){ j.origenes = (j.origenes || []).filter(x => x.id !== od.dataset.cgordel); if (j.origen === od.dataset.cgordel) j.origen = (j.origenes[0] || {}).id || ""; juntaGuardar(j); CG.partidaAbierta = true; renderCargos(); return; }
    const md = t.closest("[data-cgmed]");
    if (md){ j.medio = md.dataset.cgmed; juntaGuardar(j); CG.partidaAbierta = true; renderCargos(); return; }
    const bu = t.closest("[data-cgbus]");
    if (bu){ CG.buscando = bu.dataset.cgbus; CG.busq = ""; renderCargos(); const i = $("bus-" + CG.buscando); if (i) i.focus(); return; }
    const pk = t.closest("[data-cgpick]");
    if (pk){ const v = (j.vac || []).find(x => x.id === CG.buscando), e2 = escPorCue(pk.dataset.cgpick); if (v && e2){ aplicarEscuela(v, e2); j.escCue = {...(j.escCue || {}), [norm(v.escuela)]:e2[0]}; (j.vac || []).forEach(x => { if (!x.cue && norm(x.escuela) === norm(v.escuela)) aplicarEscuela(x, e2); }); juntaGuardar(j); } CG.buscando = ""; renderCargos(); }
  });
  P.addEventListener("change", e => {
    const t = e.target, j = juntaLeer();
    if (t.dataset.cgesc){
      const v = (j.vac || []).find(x => x.id === t.dataset.cgesc); if (!v) return;
      if (t.value === "buscar"){ CG.buscando = v.id; CG.busq = v.escuela || ""; renderCargos(); const i = $("bus-" + v.id); if (i) i.focus(); return; }
      const e2 = escPorCue(t.value); if (!e2) return;
      aplicarEscuela(v, e2); j.escCue = {...(j.escCue || {}), [norm(v.escuela)]:e2[0]};
      (j.vac || []).forEach(x => { if (!x.cue && norm(x.escuela) === norm(v.escuela)) aplicarEscuela(x, e2); });
      juntaGuardar(j); renderCargos(); return;
    }
    if (t.dataset.cgdias){ const v = (j.vac || []).find(x => x.id === t.dataset.cgdias); if (v){ v.diasN = +t.value || 0; juntaGuardar(j); renderCargos(); } return; }
    if (t.dataset.cgcost){ const n = numAR(t.value); j.costo = {...(j.costo || {}), [t.dataset.cgcost]:isFinite(n) && n > 0 ? n : ""}; juntaGuardar(j); CG.partidaAbierta = true; renderCargos(); }
  });
  P.addEventListener("input", e => {
    const t = e.target;
    if (t.dataset.cgbq){ CG.busq = t.value; const ul = $("bres-" + t.dataset.cgbq); if (ul) ul.innerHTML = htmlBusqueda(t.value); }
  });
}

/* ============================================================
   Para decidir: postulaciones, cómo queda la semana y cuánto rinde
   ============================================================ */
const ESTADOS_POST = [["postulado", "Me postulé"], ["asignado", "Me lo asignaron"], ["no", "No me lo asignaron"], ["descartado", "Lo descarté"]];
const HORA_CATEDRA_MIN = 40;
CG.abiertos = new Set();
const kDe = v => v.k || claveVac(v);
function segDe(j, v){ return (j.seg || {})[kDe(v)] || null; }
function snapVac(v){ const o = {}; ["materia", "cargo", "escuela", "escOficial", "cue", "dir", "localidad", "dep", "lat", "lon", "prec", "horas", "turno", "revista", "cierre", "tel"].forEach(k => { if (v[k] != null && v[k] !== "") o[k] = v[k]; }); return o; }
function diasSeg(v, j){ const s = segDe(j, v), d = [...new Set(((s && s.horario) || []).filter(h => aMin(h.ini) != null).map(h => +h.dia))]; return d.length ? d : null; }
function segAsegurar(j, v){ j.seg = j.seg || {}; const k = kDe(v); if (!j.seg[k]) j.seg[k] = {estado:"", f:"", horario:[], snap:snapVac(v)}; else j.seg[k].snap = {...j.seg[k].snap, ...snapVac(v)}; return j.seg[k]; }
const aMin = h => { if (!/^\d{1,2}:\d{2}/.test(String(h || ""))) return null; const [a, b] = String(h).split(":").map(Number); return a * 60 + (b || 0); };
const deMin = m => `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
function horasActuales(){ return (leerLista(LEG_KEY, {}).cargos || []).filter(x => !x.baja || x.baja >= hoyIso()).reduce((s, x) => s + (+x.horas || 0), 0); }

/* Lugar de cada bloque de la semana: escuela del padrón (si se reconoce) */
const LUGAR_CACHE = {};
function lugarDeEscuela(nombre){
  if (!nombre) return null;
  const k = norm(nombre);
  if (k in LUGAR_CACHE) return LUGAR_CACHE[k];
  const t = {escuela:nombre}; try { asignarEscuela(t, juntaLeer()); } catch (e) { logSilencioso(e); }
  return (LUGAR_CACHE[k] = t.cue ? {cue:t.cue, lat:t.lat, lon:t.lon, n:t.escOficial} : null);
}
function bloquesSemana(j, excluirK){
  const out = [];
  cdatos().cursos.forEach(c => (c.horario || []).forEach(h => { const a = aMin(h.ini), b = aMin(h.fin) ?? (a != null ? a + 80 : null); if (a == null) return; const l = lugarDeEscuela(c.escuela); out.push({dia:+h.dia, a, b, t:`${c.curso} · ${nombreMateria(c.materia)}`, esc:c.escuela || "", lugar:l}); }));
  Object.entries(j.seg || {}).forEach(([k, s]) => { if (k === excluirK || s.estado !== "asignado") return; (s.horario || []).forEach(h => { const a = aMin(h.ini), b = aMin(h.fin); if (a == null || b == null) return; out.push({dia:+h.dia, a, b, t:s.snap.materia || s.snap.cargo || "Cargo asignado", esc:s.snap.escOficial || s.snap.escuela || "", lugar:s.snap.lat != null ? {cue:s.snap.cue, lat:s.snap.lat, lon:s.snap.lon} : null}); }); });
  /* sin repetidos: mismo día, mismo horario y misma escuela */
  return out.filter((x, i) => out.findIndex(y => y.dia === x.dia && y.a === x.a && norm(y.esc) === norm(x.esc)) === i);
}
const mismoLugar = (x, y) => (x.lugar && y.lugar && x.lugar.cue && x.lugar.cue === y.lugar.cue) || (!x.lugar && !y.lugar && norm(x.esc) === norm(y.esc));
function minutosEntre(x, y, j){
  if (mismoLugar(x, y)) return 0;
  if (!x.lugar || !y.lugar || x.lugar.lat == null || y.lugar.lat == null) return null;
  return minutosViaje(kmEntre(x.lugar, y.lugar), j.medio || "auto").min;
}
function analizarSemana(v, j){
  const s = segDe(j, v), hor = (s && s.horario || []).filter(h => aMin(h.ini) != null && aMin(h.fin) != null);
  if (!hor.length) return null;
  const nuevos = hor.map(h => ({dia:+h.dia, a:aMin(h.ini), b:aMin(h.fin), t:`${v.materia || v.cargo} (este cargo)`, esc:v.escOficial || v.escuela, lugar:v.lat != null ? {cue:v.cue, lat:v.lat, lon:v.lon} : null, nuevo:true}));
  const todos = [...bloquesSemana(j, kDe(v)), ...nuevos], o = origenActual(j);
  const dias = [...new Set(todos.map(x => x.dia))].sort(), res = [];
  let problemas = 0, viajeSem = 0;
  dias.forEach(d => {
    const bl = todos.filter(x => x.dia === d).sort((p, q) => p.a - q.a), filas = [];
    if (!bl.some(x => x.nuevo)) { res.push({d, filas:bl.map(x => ({x})), sinCambio:true}); return; }
    let viajeDia = 0;
    if (o && bl[0].lugar){ const m = minutosViaje(kmEntre(o, bl[0].lugar), j.medio || "auto").min; viajeDia += m; filas.push({ida:m, desde:o.nombre}); }
    bl.forEach((x, i) => {
      if (i > 0){
        const p = bl[i - 1], gap = x.a - p.b, via = minutosEntre(p, x, j);
        let estado = "ok", txt = "";
        if (gap < 0){ estado = "mal"; txt = `Se superpone con ${p.t} (${deMin(p.a)}–${deMin(p.b)}).`; }
        else if (via == null){ estado = "?"; txt = `Tenés ${fmtMin(gap)} para cambiar de escuela; no se pudo calcular el viaje.`; }
        else if (via === 0){ txt = gap ? `${fmtMin(gap)} libres en la misma escuela.` : ""; }
        else if (gap < via){ estado = "mal"; txt = `No llegás: tenés ${fmtMin(gap)} y el viaje lleva unos ${fmtMin(via)}.`; viajeDia += via; }
        else if (gap - via < 10){ estado = "justo"; txt = `Llegás justo: tenés ${fmtMin(gap)} y el viaje lleva unos ${fmtMin(via)}.`; viajeDia += via; }
        else { txt = `Viaje de unos ${fmtMin(via)}; te sobran ${fmtMin(gap - via)}.`; viajeDia += via; }
        if (estado === "mal") problemas++;
        if (txt) filas.push({entre:txt, estado});
      }
      filas.push({x});
    });
    const ult = bl[bl.length - 1];
    if (o && ult.lugar){ const m = minutosViaje(kmEntre(o, ult.lugar), j.medio || "auto").min; viajeDia += m; filas.push({vuelta:m, a:o.nombre}); }
    viajeSem += viajeDia;
    res.push({d, filas, viajeDia});
  });
  const horas = horasActuales(), nuevasH = +v.horas || 0;
  const tope = +j.topeHoras || 0;
  if (tope && horas + nuevasH > tope) problemas++;
  return {res, problemas, viajeSem, horas, total:horas + nuevasH, tope};
}
function htmlSemana(v, j){
  const A = analizarSemana(v, j);
  if (!A) return `<p class="hint">Cargá los días y horarios del cargo para ver cómo queda tu semana junto con tus clases de «Mi curso» y los cargos que ya te asignaron.</p>`;
  const lin = f => f.x ? `<li class="sm-b${f.x.nuevo ? " nuevo" : ""}"><span class="sm-h">${deMin(f.x.a)}–${deMin(f.x.b)}</span><span>${esc(f.x.t)}${f.x.esc ? `<small>${esc(f.x.esc)}</small>` : ""}</span></li>`
    : f.entre ? `<li class="sm-v ${f.estado}">${esc(f.entre)}</li>`
    : f.ida != null ? `<li class="sm-v">Salís de ${esc(f.desde)}: unos ${fmtMin(f.ida)} de viaje.</li>`
    : `<li class="sm-v">Volvés a ${esc(f.a)}: unos ${fmtMin(f.vuelta)}.</li>`;
  const avisoTope = A.tope && A.total > A.tope ? `<p class="cg-sup">Con este cargo llegás a ${A.total} horas cátedra y tu tope es ${A.tope}.</p>` : "";
  return `<div class="sm">
    <p class="sm-res ${A.problemas ? "mal" : "ok"}">${A.problemas ? `${A.problemas === 1 ? "Hay un problema" : `Hay ${A.problemas} problemas`}: revisalo abajo.` : "Te entra en la semana."}${A.viajeSem ? ` Viaje en los días de este cargo: ${fmtMin(A.viajeSem)} por semana.` : ""} Horas cátedra: ${A.horas ? `${A.horas} actuales + ` : ""}${+v.horas || 0} = ${A.total}${A.tope ? ` (tope ${A.tope})` : ""}.</p>${avisoTope}
    <div class="sm-dias">${A.res.map(r => `<section class="sm-dia${r.sinCambio ? " igual" : ""}"><h4>${cap(DIAS_SEM[r.d] || "")}</h4><ul>${r.filas.map(lin).join("")}</ul></section>`).join("")}</div>
    ${A.horas ? "" : `<p class="hint">Para sumar tus horas actuales al tope, cargalas en «Mi legajo › Cargos y horas».</p>`}</div>`;
}
function rindeDe(v, j){
  const vh = +j.valorHora || 0, h = +v.horas || 0;
  if (!vh || !h) return null;
  const s = segDe(j, v), dias = (s && s.horario || []).length ? new Set(s.horario.map(x => +x.dia)).size : (diasDeVac(v) || []).length || +v.diasN || 0;
  const r = viajeDe(v, j), cst = r ? costoViaje(r.km, j, v) : null;
  const ingreso = vh * h, viajeMes = cst && dias ? cst * dias * 4.3 : 0;
  const horasClase = h * HORA_CATEDRA_MIN / 60, horasViaje = r && dias ? 2 * r.min * dias / 60 : 0, horasInv = horasInvisiblesCargo(h, j), horasSem = horasClase + horasViaje + horasInv;
  return {ingreso, viajeMes, queda:ingreso - viajeMes, horasSem, horasClase, horasViaje, horasInv, porHora:horasSem ? (ingreso - viajeMes) / (horasSem * 4.3) : 0, dias};
}
function htmlDecision(v, j){
  const s = segDe(j, v), k = kDe(v), R = rindeDe(v, j);
  const est = s && s.estado ? `<div class="cg-post"><select data-segest="${esc(k)}" aria-label="Estado de la postulación">${ESTADOS_POST.map(([e, l]) => `<option value="${e}"${s.estado === e ? " selected" : ""}>${l}</option>`).join("")}<option value="">Quitar de mis postulaciones</option></select>${s.f ? `<small>desde el ${dm(fechaDe(s.f))}</small>` : ""}${s.estado === "asignado" && !s.legajo ? `<button type="button" class="btn btn-sm btn-primary" data-legsum="${esc(k)}">Sumar a Mi legajo</button>` : s.legajo ? `<small>En «Mi legajo»</small>` : ""}</div>`
    : `<button type="button" class="btn btn-sm" data-cgpost="${esc(k)}">Me postulé</button>`;
  const rinde = R ? `<div class="cg-rinde"><b>${pesos(R.ingreso)} por mes aprox.</b><span>${R.viajeMes ? `Viaje ${pesos(R.viajeMes)} por mes · te quedan ${pesos(R.queda)} · ` : ""}${coma(Math.round(R.horasSem * 10) / 10)} h por semana: clase ${coma(Math.round(R.horasClase * 10) / 10)} h${R.horasViaje ? ` · viaje ${coma(Math.round(R.horasViaje * 10) / 10)} h` : ""}${R.horasInv ? ` · planificar y corregir ${coma(Math.round(R.horasInv * 10) / 10)} h` : ""}${R.porHora ? ` · ${pesos(R.porHora)} por hora dedicada` : ""}${R.dias ? "" : " (indicá los días para sumar el viaje)"}</span>${R.horasInv ? `<small>Planificar y corregir: proporcional a lo que anotaste en «Mis límites» para tus horas actuales.</small>` : (+(juntaLeer().lim || {}).hPlan || +(juntaLeer().lim || {}).hCorr) ? "" : `<small>Anotá en «Mis límites» cuánto planificás y corregís por semana para ver las horas reales.</small>`}</div>` : "";
  const hor = (s && s.horario) || [];
  const DIAS = [[1, "Lunes"], [2, "Martes"], [3, "Miércoles"], [4, "Jueves"], [5, "Viernes"], [6, "Sábado"]];
  return `${rinde}${est}
    <details class="cg-sem" data-k="${esc(k)}"${CG.abiertos.has(k) ? " open" : ""}><summary>Horario y cómo queda mi semana</summary>
      <div class="cg-hor">${hor.map((h, i) => `<div class="hor-fila"><select data-hk2="${esc(k)}" data-hi="${i}" data-hc="dia" aria-label="Día">${DIAS.map(([d, l]) => `<option value="${d}"${+h.dia === d ? " selected" : ""}>${l}</option>`).join("")}</select><input type="time" data-hk2="${esc(k)}" data-hi="${i}" data-hc="ini" value="${esc(h.ini || "")}" aria-label="Entrada"><input type="time" data-hk2="${esc(k)}" data-hi="${i}" data-hc="fin" value="${esc(h.fin || "")}" aria-label="Salida"><button type="button" class="seg-x" data-hdel="${esc(k)}" data-hi="${i}" aria-label="Quitar">×</button></div>`).join("")}
      <button type="button" class="btn btn-sm" data-hadd="${esc(k)}">Agregar día y horario</button></div>
      ${htmlSemana(v, j)}</details>`;
}
function htmlPostulaciones(j){
  const ents = Object.entries(j.seg || {}).filter(([, s]) => s.estado);
  if (!ents.length) return "";
  const vk = new Set((j.vac || []).map(kDe));
  const orden = {asignado:0, postulado:1, no:2, descartado:3};
  ents.sort((a, b) => (orden[a[1].estado] - orden[b[1].estado]) || (b[1].f || "").localeCompare(a[1].f || ""));
  const cuenta = e => ents.filter(([, s]) => s.estado === e).length;
  return `<details class="cur-sub cg-posts"><summary>Mis postulaciones (${ents.length})${cuenta("asignado") ? ` · ${cuenta("asignado")} ${cuenta("asignado") === 1 ? "asignado" : "asignados"}` : ""}${cuenta("postulado") ? ` · ${cuenta("postulado")} esperando resultado` : ""}</summary>
    <ul class="cg-plist">${ents.map(([k, s]) => `<li><div><b>${esc(s.snap.materia || s.snap.cargo || "Cargo")}</b> · ${esc(s.snap.escOficial || s.snap.escuela || "")}${s.snap.horas ? ` · ${esc(s.snap.horas)} h` : ""}<small>${s.f ? `Desde el ${dm(fechaDe(s.f))}` : ""}${s.snap.cierre ? ` · cierre ${dm(fechaDe(s.snap.cierre))}` : ""}${vk.has(k) ? "" : " · ya no figura en el último listado"}</small></div>
      <select data-segest="${esc(k)}" aria-label="Estado">${ESTADOS_POST.map(([e, l]) => `<option value="${e}"${s.estado === e ? " selected" : ""}>${l}</option>`).join("")}<option value="">Quitar</option></select>${s.estado === "no" ? `<label class="cg-corte-in">Puntaje de quien quedó <input inputmode="decimal" data-segcorte="${esc(k)}" value="${esc(s.corte || "")}" aria-label="Puntaje de quien quedó con el cargo"></label><button type="button" class="linkbtn" data-reclamo="${esc(k)}">Armar nota de reclamo</button>` : ""}${s.estado === "asignado" ? htmlTramites(k, s) : ""}${s.estado === "postulado" ? htmlComprobante(k, s) : ""}${s.estado === "asignado" && !s.legajo ? `<button type="button" class="btn btn-sm" data-legsum="${esc(k)}">Sumar a Mi legajo</button>` : ""}</li>`).join("")}</ul></details>`;
}
function avisosPost(){
  const j = juntaLeer(), hoy = hoyIso(), av = [];
  Object.values(j.seg || {}).forEach(s => {
    if (s.estado === "postulado" && s.snap.cierre && s.snap.cierre < hoy) av.push({f:"3", t:`Ya cerró la postulación a ${s.snap.materia || s.snap.cargo} en ${s.snap.escOficial || s.snap.escuela}: fijate el resultado en el SIME y anotalo.`, act:"cargos"});
  });
  return av.slice(0, 2);
}

function bindDecision(){
  const P = $("cg-panel");
  P.addEventListener("toggle", e => { const d = e.target; if (d.classList && d.classList.contains("cg-sem")){ if (d.open) CG.abiertos.add(d.dataset.k); else CG.abiertos.delete(d.dataset.k); } }, true);
  const vacK = (j, k) => (j.vac || []).find(v => kDe(v) === k);
  P.addEventListener("click", e => {
    const t = e.target, j = juntaLeer();
    const po = t.closest("[data-cgpost]");
    if (po){ const v = vacK(j, po.dataset.cgpost); if (!v) return; const s = segAsegurar(j, v); s.estado = "postulado"; s.f = hoyIso(); try { const PC = paramsChance(v, j); if (PC) s.ch = {a:PC.a, p:PC.p, vac:PC.vac, puntaje:PC.puntaje}; } catch (e) { logSilencioso(e); } juntaGuardar(j); renderCargos(); toast("Anotado en «Mis postulaciones». Guardá una captura del comprobante del SIME con fecha y hora, y cuando salga el resultado cambialo ahí."); return; }
    const ha = t.closest("[data-hadd]");
    if (ha){ const v = vacK(j, ha.dataset.hadd); if (!v) return; const s = segAsegurar(j, v); const prev = s.horario[s.horario.length - 1]; s.horario.push(prev ? {dia:Math.min(6, +prev.dia + 1), ini:prev.ini, fin:prev.fin} : {dia:1, ini:"", fin:""}); CG.abiertos.add(ha.dataset.hadd); juntaGuardar(j); renderCargos(); return; }
    const hd = t.closest("[data-hdel]");
    if (hd){ const k = hd.dataset.hdel, i = hd.dataset.hi; const s = (j.seg || {})[k]; if (s){ s.horario.splice(+i, 1); juntaGuardar(j); renderCargos(); } return; }
    const ls = t.closest("[data-legsum]");
    if (ls){
      const s = (j.seg || {})[ls.dataset.legsum]; if (!s) return;
      const L = leerLista(LEG_KEY, {});
      L.cargos = [...(L.cargos || []), {id:nuevoIdC("l"), escuela:s.snap.escOficial || s.snap.escuela || "", cargo:s.snap.materia || s.snap.cargo || "", horas:s.snap.horas || "", revista:s.snap.revista || "", alta:hoyIso(), baja:""}];
      if (guardarLista(LEG_KEY, L)){ s.legajo = true; juntaGuardar(j); renderCargos(); renderTuDia(); toast("Sumado a «Mi legajo › Cargos y horas»."); }
    }
  });
  P.addEventListener("change", e => {
    const t = e.target, j = juntaLeer();
    if (t.dataset.segest != null){
      const k = t.dataset.segest; j.seg = j.seg || {}; const s = j.seg[k]; if (!s) return;
      if (!t.value){ if (!(s.horario || []).length) delete j.seg[k]; else s.estado = ""; }
      else { s.estado = t.value; if (!s.f) s.f = hoyIso(); }
      juntaGuardar(j); renderCargos(); renderTuDia(); return;
    }
    if (t.dataset.hk2){
      const k = t.dataset.hk2, i = t.dataset.hi, c = t.dataset.hc; const s = (j.seg || {})[k]; if (!s || !s.horario[+i]) return;
      s.horario[+i][c] = t.value; juntaGuardar(j); CG.abiertos.add(k); renderCargos(); return;
    }
    if (t.dataset.cgval){ const n = numAR(t.value); j[t.dataset.cgval] = isFinite(n) && n > 0 ? n : ""; juntaGuardar(j); CG.partidaAbierta = true; renderCargos(); }
  });
}

