/* Áreas afines para reconocer la relación con el título */
const AREAS_AFINES = {
  "fisica":["física", "fisicoquímica", "ciencias naturales", "química", "matemática", "tecnología", "astronomía"],
  "quimica":["química", "fisicoquímica", "ciencias naturales", "biología"],
  "biologia":["biología", "ciencias naturales", "química", "educación ambiental"],
  "matematica":["matemática", "física", "economía", "tecnología"],
  "geografia":["geografía", "ciencias sociales", "historia"],
  "historia":["historia", "ciencias sociales", "geografía", "formación ética"],
  "lengua":["lengua", "literatura"],
  "ingles":["inglés", "idiomas"]
};
function misAreas(){
  const L = leerLista(LEG_KEY, {});
  const textos = [...(L.junta || []).map(x => `${x.materia} ${x.otros || ""}`), ...(L.titulos || []).map(x => x.titulo || "")].join(" ");
  const t = norm(textos), out = new Set();
  Object.entries(AREAS_AFINES).forEach(([k, a]) => { if (t.includes(k) || a.slice(0, 1).some(x => t.includes(norm(x)))) a.forEach(x => out.add(norm(x))); });
  if (/fisicoquimica/.test(t)) AREAS_AFINES.fisica.forEach(x => out.add(norm(x)));
  if (/ciencias naturales/.test(t)) ["ciencias naturales", "física", "química", "biología"].forEach(x => out.add(norm(x)));
  return out;
}
function relacionCurso(areas, texto){
  const mias = misAreas();
  if (!mias.size) return null;
  const a = (areas || []).map(norm), t = norm(texto || "");
  if (a.length){
    if (a.some(x => mias.has(x))) return {k:"alta", t:"Relacionado con tus materias"};
    if (a.includes("todas")) return {k:"media", t:"Sirve para cualquier materia"};
    return {k:"baja", t:"De otra área"};
  }
  if (!t) return null;
  if ([...mias].some(m => new RegExp(`\\b${m}`).test(t))) return {k:"alta", t:"Relacionado con tus materias"};
  if (/todas las areas|todas las materias|todos los niveles|docentes de (nivel )?secundari/.test(t)) return {k:"media", t:"Sirve para cualquier materia"};
  return null;
}
/* ¿Este curso me suma? */
function datosDeTexto(txt){
  const t = String(txt || ""), o = {};
  const h = /(?:carga horaria[^\d]{0,15})?(\d{2,3})\s*(?:h\b|hs\b|hs\.|horas)/i.exec(t);
  if (h) o.horas = +h[1];
  const r = /\b(?:res(?:oluci[oó]n)?|r\.?\s?m\.?)\.?\s*(?:ministerial\s*)?(?:n(?:ro)?\s*[°º.o*#]*\s*)?(\d{2,5})\s*[\/-]\s*5\b/i.exec(t);
  if (r) o.res = `${r[1]}/5`;
  o.infod = /\binfod\b|instituto nacional de formaci[oó]n docente|red\.infd|nuestra escuela/i.test(t);
  o.web = /webinar|webinario|conversatorio/i.test(t);
  o.otroNivel = /\b(nivel )?(inicial|primari[oa])\b/i.test(t) && !/secundari/i.test(t);
  return o;
}
function evaluarCursoV43(o){
  const motivos = [], horas = +o.horas || 0;
  let suma = null, pts = null;
  if (o.web){ suma = false; motivos.push("Los webinarios, charlas y conversatorios no tienen resolución del Ministerio y no otorgan puntaje."); }
  else if (o.infod){
    if (!horas){ suma = true; motivos.push("Es de INFoD: suma según la carga horaria (Res. 1741/5 MEd). Cargá las horas para ver cuánto."); }
    else if (horas < 20){ suma = false; motivos.push(`Tiene ${horas} horas: los cursos de INFoD suman desde 20 horas.`); }
    else { suma = true; pts = puntosInfod(horas); motivos.push(`Curso de INFoD de ${horas} horas: ${coma(pts)} puntos según la Res. 1741/5 (MEd) de 2026.`); }
  } else {
    if (!o.res){ suma = false; motivos.push("No figura una resolución del Ministerio de Educación de Tucumán («Res. N.º …/5 (MEd)»). Sin resolución no suma: preguntá a quien lo dicta si la tiene."); }
    else if (o.fuera){ suma = false; motivos.push("Desde el Decreto 3128 (2025), los cursos dictados fuera de Tucumán no suman, salvo los de INFoD."); }
    else if (horas && horas < 40){ suma = false; motivos.push(`Tiene ${horas} horas: desde el Decreto 3128 (2025) los cursos de menos de 40 horas no suman, salvo los de INFoD.`); }
    else {
      suma = true;
      motivos.push(`Tiene la Res. ${o.res} (MEd)${horas ? ` y ${horas} horas` : ""}: suma puntaje.${horas ? "" : " Fijate que tenga al menos 40 horas."}`);
      motivos.push("Cuántos puntos exactos depende del Anexo X del Decreto 3128: queda «a confirmar» hasta tener el texto oficial.");
    }
  }
  if (o.otroNivel) motivos.push("Parece dirigido a inicial o primaria: el puntaje vale para el nivel en el que concursás.");
  const rel = relacionCurso(o.areas, o.txt);
  return {suma, pts, motivos, rel};
}
const PROMPT_CURSO = `Esta imagen es el flyer o la publicación de un curso o capacitación para docentes (Tucumán, Argentina). Extraé los datos que se vean y devolvé solo un objeto JSON con estas claves (texto vacío o null si no aparece): "nombre", "institucion", "horas" (número, carga horaria total), "resolucion" (como aparece, por ejemplo "Res. N.º 1926/5 (MEd)"), "modalidad", "destinatarios", "inscripcion_hasta" (fecha AAAA-MM-DD), "costo", "enlace", "texto" (todo el texto relevante del flyer, en una sola línea).`;
async function leerCursoCaptura(files){
  const lim = await puedeVerImagenes().catch(() => null);
  if (lim){
    try {
      const r = await caps.sample.json(PROMPT_CURSO, {images:[...files].slice(0, lim.maxCount || 3), modelTier:"default", cache:false});
      if (r && typeof r === "object") return {txt:[r.nombre, r.institucion, r.horas ? r.horas + " horas" : "", r.resolucion, r.modalidad, r.destinatarios, r.costo, r.texto].filter(Boolean).join("\n"), nombre:r.nombre || "", inst:r.institucion || "", cierre:r.inscripcion_hasta || "", url:r.enlace || ""};
    } catch (e) { /* se lee en el dispositivo */ }
  }
  const texto = await leerConTesseract(files, p => { const st = $("cp-leyendo"); if (st) st.textContent = `Leyendo la imagen en este dispositivo… ${Math.round(p * 100)} %`; });
  return {txt:texto};
}
const CP = {tab:"buscar", q:"", soloMias:true, soloGratis:false, chk:null, extra:0};
function capInt(){ return leerLista(LEG_KEY, {}).capInt || []; }
