    <div class="f"><label for="fi-doc">¿Qué documento es?</label><select id="fi-doc">${DOCS_CARP.map(d => `<option value="${d.id}"${FI.doc === d.id ? " selected" : ""}>${esc(d.n)}</option>`).join("")}</select></div>
