  const t = ($("fi-t").value || "").trim() || "Evaluación", eid = $("fi-eid").value, f = hoyIso();
  let ok = 0, notas = 0, saltadas = 0;
  if (eid) E.notas.forEach((n, i) => { if (n == null || E.cargar[i] === false) return; const aid = E.asig[i]; c.notas = c.notas || {}; c.notas[aid] = c.notas[aid] || {}; const prev = c.notas[aid][eid]; if (prev === "" || prev == null){ c.notas[aid][eid] = String(n).replace(".", ","); notas++; } else if (aNumC(prev) !== n) saltadas++; });
