  const cv = document.createElement("canvas"); cv.width = W; cv.height = Hh; const cx = cv.getContext("2d"); cx.drawImage(im, 0, 0, W, Hh);
  const d = cx.getImageData(0, 0, W, Hh).data, g = new Uint8Array(W * Hh);
  for (let i = 0; i < g.length; i++) g[i] = Math.round(0.299 * d[i * 4] + 0.587 * d[i * 4 + 1] + 0.114 * d[i * 4 + 2]);
  const t = otsu(g);
