  const items = L.length ? L.map((s, i) => contraer(`${i + 1}. ¿Qué sabés sobre ${temaArt(sinPunto(s.includes(":") ? s.split(":")[0] : s))}? Explicalo con tus palabras y da un ejemplo.`)) : ["1. ¿Qué temas recordás de esta materia del año pasado?", "2. Elegí uno y explicalo con un ejemplo."];
