/* ============================================================
   Alerta temprana de trayectorias en riesgo
   ============================================================ */
function riesgoAlumnos(c){
  const p = periodoActual(c), ap = aprobC(c), h21 = (() => { const d = new Date(); d.setDate(d.getDate() - 21); return isoDe(d); })(), out = [];
  alumnosActivos(c).forEach(a => {
    const m = [], r = asisResumen(c, a.id, p);
    if (r.clases >= 4 && r.pct >= 15) m.push(`${r.pct} % de faltas`);
    const pr = promPeriodo(c, a.id, p); if (pr != null && pr < ap) m.push(`promedio ${fmtN(pr)}`);
    const ns = evalsDe(c, p).map(e => notaEval(c, a.id, e.id)).filter(x => x != null);
    if (ns.length >= 2 && ns[ns.length - 1] <= ns.slice(0, -1).reduce((s, x) => s + x, 0) / (ns.length - 1) - 1.5) m.push("notas en baja");
    const cond = (c.cond || []).filter(k => k.aid === a.id && k.f >= h21);
    const tareas = cond.filter(k => /no entrega la tarea/i.test(k.t)).length; if (tareas >= 2) m.push(`${tareas} tareas sin entregar`);
    const neg = cond.filter(k => k.tipo === "-").length; if (neg >= 3) m.push("conducta a mejorar");
    if (m.length >= 2) out.push({a, m});
  });
  return out;
}
function htmlRiesgoV69(c){
  const R = riesgoAlumnos(c);
  if (!R.length) return "";
  return `<section class="rs-b rs-riesgo"><h3>Señales de riesgo <span>${R.length}</span></h3><ul>${R.map(x => `<li>${esc(x.a.n)}<small>${esc(x.m.join(", "))}</small><button type="button" class="linkbtn" data-rsint="${x.a.id}">Registrar una intervención</button></li>`).join("")}</ul><p class="hint">Dos o más señales juntas (faltas, notas, tareas o conducta). Mejor actuar ahora que al cierre del período.</p></section>`;
}
function avisosAula22(){
  const av = [], hoy = hoyIso(), man = (() => { const d = new Date(); d.setDate(d.getDate() + 1); return isoDe(d); })();
  cdatos().cursos.forEach(c => {
    (c.interv || []).filter(x => x.rev && !x.hecho && x.rev <= man).slice(0, 2).forEach(x => { const a = alumnosActivos(c).find(y => y.id === x.aid); if (a) av.push({f:x.rev, t:`${x.rev < hoy ? "Quedó pendiente" : "Toca"} volver a ver lo acordado con ${a.n} (${c.curso}): ${x.acu || x.que}`.slice(0, 160), act:"familias", cid:c.id}); });
    const R = riesgoAlumnos(c); if (R.length) av.push({f:"4", t:`En ${c.curso}, ${R.length === 1 ? `${R[0].a.n} muestra señales de riesgo (${R[0].m.slice(0, 2).join(", ")}).` : `${R.length} alumnos muestran señales de riesgo: ${R.slice(0, 2).map(x => x.a.n.split(",")[0]).join(", ")}${R.length > 2 ? " y otros" : ""}.`}`, act:"semana", cid:c.id});
  });
  return av.slice(0, 3);
}

