/* ============================================================
   Memoria del año por unidad
   ============================================================ */
const MEM_STOP = new Set(["unidad", "clase", "clases", "trabajo", "practico", "actividad", "actividades", "sobre", "entre", "desde", "hasta", "segun", "donde", "cuando", "tema", "temas", "introduccion", "repaso", "evaluacion"]);
function palabrasMem(s){ return norm(s || "").split(/[^a-zñ0-9]+/).filter(w => w.length >= 5 && !MEM_STOP.has(w)); }
function unidadesDelCurso(c){
  let L = planesDelCurso(c).filter(e => e.data.modo === "anual");
  if (!L.length) L = libLeer().filter(e => e.data.modo === "anual" && e.data.v.materia === c.materia && String(e.data.v.anio || "") === String(c.anio || ""));
  const e = L.sort((a, b) => (b.upd || 0) - (a.upd || 0))[0]; if (!e) return [];
  const v = e.data.v, out = [];
  for (let n = 1; n <= 8; n++){ const t = (v[`an${n}_t`] || "").trim(); if (t) out.push({t, pal:new Set(palabrasMem(`${t} ${v[`an${n}_s`] || ""}`))}); }
  return out;
}
function memoriaAnual(c){
  const temas = (c.temas || []).slice().sort((a, b) => (a.f || "").localeCompare(b.f || ""));
  const U = unidadesDelCurso(c);
  let G;
  if (U.length){
    G = U.map(u => ({t:u.t, pal:u.pal, L:[]})); const otros = {t:"Otros temas", L:[]};
    temas.forEach(t => { const w = palabrasMem(`${t.tema} ${t.act || ""}`); let best = null, bh = 0; G.forEach(g => { const h = w.filter(x => g.pal.has(x)).length; if (h > bh){ bh = h; best = g; } }); (best || otros).L.push(t); });
    G = G.filter(g => g.L.length); if (otros.L.length) G.push(otros);
  } else {
    const per = {}; temas.forEach(t => { const p = periodoDe(c, t.f); (per[p] = per[p] || []).push(t); });
    G = Object.keys(per).map(Number).sort((a, b) => a - b).map(p => { const n = nombrePeriodo(c, p); return {t:n.charAt(0).toUpperCase() + n.slice(1), L:per[p]}; });
  }
  const cuenta = L => ({bien:L.filter(t => t.val === "bien").length, regular:L.filter(t => t.val === "regular").length, mal:L.filter(t => t.val === "mal").length, sin:L.filter(t => !t.val).length});
  return {porUnidad:!!U.length, G:G.map(g => ({t:g.t, L:g.L, n:cuenta(g.L)})), tot:cuenta(temas), clases:temas.length};
}
function lineaMem(t){ return `${fechaCortaIso(t.f)} · ${t.tema || "Sin tema"}${t.obs ? `: ${t.obs}` : t.act ? `: ${t.act}` : ""}`; }
function htmlMemoriaAnual(c){
  const M = memoriaAnual(c), T = M.tot;
  if (T.bien + T.regular + T.mal < 3) return "";
  return `<details class="memoria mem-anual"><summary><b>Memoria del año</b> · ${T.bien} bien, ${T.regular} regular, ${T.mal} mal${T.sin ? ` · ${T.sin} sin valorar` : ""}</summary>
    <ul>${M.G.map(g => { const rev = g.L.filter(t => t.val === "mal" || t.val === "regular"); return `<li><b>${esc(g.t)}</b> <span class="mem-n">✓ ${g.n.bien} · ~ ${g.n.regular} · ✗ ${g.n.mal}</span>${rev.length ? `<small>Para revisar: ${esc(rev.slice(0, 3).map(lineaMem).join(" | "))}${rev.length > 3 ? " …" : ""}</small>` : ""}</li>`; }).join("")}</ul>
    <p class="hint">${M.porUnidad ? "Agrupado por las unidades de tu planificación anual." : "Agrupado por período. Si guardás la planificación anual en este curso, se agrupa por unidad."}</p>
    <div class="cur-bar"><button type="button" class="btn btn-sm" data-act2="mem-doc">Descargar la memoria (Word)</button></div></details>`;
}
function modeloMemoria(c){
  const M = memoriaAnual(c), T = M.tot;
  const secs = [{h:"Resumen", body:`Clases registradas en el libro de temas: ${M.clases}.\nSalieron bien: ${T.bien}. Regular: ${T.regular}. Mal: ${T.mal}.${T.sin ? ` Sin valorar: ${T.sin}.` : ""}`}];
  M.G.forEach(g => {
    const bien = g.L.filter(t => t.val === "bien"), rev = g.L.filter(t => t.val === "mal" || t.val === "regular");
    const partes = [`Clases: ${g.L.length} (bien ${g.n.bien}, regular ${g.n.regular}, mal ${g.n.mal}).`];
    if (bien.length) partes.push("Lo que funcionó:\n" + bien.map(t => "• " + lineaMem(t)).join("\n"));
    if (rev.length) partes.push("Para revisar el año que viene:\n" + rev.map(t => `• ${t.val === "mal" ? "Salió mal" : "Regular"} · ${lineaMem(t)}`).join("\n"));
    secs.push({h:g.t, body:partes.join("\n\n")});
  });
  const stA = estadisticas(c, "anual");
  if (stA.conNota || stA.asis != null) secs.splice(1, 0, {h:"Resultados del curso", body:toList([`Estudiantes: ${stA.total}. Con calificación final: ${stA.conNota}.`, stA.conNota ? `Aprobados: ${stA.aprob} (${Math.round(stA.aprob / stA.conNota * 100)} %). Promedio: ${stA.prom != null ? fmtN(Math.round(stA.prom * 10) / 10) : "sin datos"}.` : "Todavía no hay calificaciones finales.", `Asistencia media: ${stA.asis != null ? stA.asis + " %" : "sin datos"}.`])});
  secs.push({h:"Notas para el año próximo", body:notasAnioProximo(c), falta:"Completar"});
  return {inst:c.escuela || val("institucion") || "", titulo:"Memoria del año", subtitulo:nombreCurso(c), faltaSub:"Curso", datos:datosBaseCurso(c), secs, firmas:[[c.docente || val("docente") || "", "Docente"]]};
}
function avisoMemoria(){
  const m = new Date().getMonth(); if (m < 10) return [];
  const av = [];
  cdatos().cursos.forEach(c => { const T = memoriaAnual(c).tot; if (T.bien + T.regular + T.mal >= 5) av.push({f:"5", t:`Cerrá el año en ${c.curso}: descargá la memoria de lo que salió bien y mal, para planificar el que viene.`, act:"temas", cid:c.id}); });
  return av.slice(0, 1);
}

/* ============================================================
   Horas invisibles en cada cargo: planificación y corrección proporcionales
   ============================================================ */
function horasInvisiblesCargo(h, j){
  const L = (j && j.lim) || {}, inv = (+L.hPlan || 0) + (+L.hCorr || 0), act = horasActuales();
  return inv && act && h ? inv / act * h : 0;
}

