/* Pantalla de carga: se ve mientras arranca la app (una vez por sesión) */
function ocultarSplash(){
  const sp = document.getElementById("splash"); if (!sp) return;
  let visto = false; try { visto = !!sessionStorage.getItem("lapacho-splash"); sessionStorage.setItem("lapacho-splash", "1"); } catch (e) { logSilencioso(e); }
  const quitar = () => { sp.classList.add("fuera"); setTimeout(() => sp.remove(), 450); };
  if (navigator.webdriver || visto) { sp.remove(); return; }
  setTimeout(quitar, Math.max(0, 900 - performance.now()));
}
/* ============================================================
   Sincronización con Google Drive (opcional, con la cuenta del docente)
   Permiso drive.file: la app solo ve los archivos y carpetas que crea o que el docente elige.
   Funciona en la app instalada (GitHub Pages), no dentro de claude.ai ni en el archivo sin conexión.
   ============================================================ */
const GD_SCOPE = "https://www.googleapis.com/auth/drive.file";
const GD_API = "https://www.googleapis.com/drive/v3";
const GD_UP = "https://www.googleapis.com/upload/drive/v3";
const GD = {token:"", vence:0, cliente:null, ocupado:false, pendiente:false, timer:null, error:""};
function gdCfg(){ const w = window.LAPACHO_GD || {}, p = leerPref().gdCfg || {}; return {clientId:w.clientId || p.clientId || "", apiKey:w.apiKey || p.apiKey || "", appId:w.appId || p.appId || "", forzar:!!w.forzar}; }
function gdEstado(){ return leerPref().gd || {}; }
function gdGuardarEstado(o){ prefSet("gd", {...gdEstado(), ...o}); }
function gdDisponibleBase(){
  const c = gdCfg();
  if (c.forzar) return {ok:true};
  if (!/^https:$/.test(location.protocol) || window.top !== window || /(^|\.)claude\.ai$|claudeusercontent|claude\.site/.test(location.hostname)) return {ok:false, motivo:"lugar"};
  if (!c.clientId) return {ok:false, motivo:"config"};
  return {ok:true};
}
function gdConectado(){ return !!GD.token && Date.now() < GD.vence - 60000; }
async function gdCargarGIS(){
  if (window.google && window.google.accounts && window.google.accounts.oauth2) return;
  await cargarScript("https://accounts.google.com/gsi/client");
}
async function gdPedirToken(silencioso){
  await gdCargarGIS();
  return new Promise((res, rej) => {
    try {
      GD.cliente = window.google.accounts.oauth2.initTokenClient({client_id:gdCfg().clientId, scope:GD_SCOPE, callback:r => {
        if (!r || r.error || !r.access_token){ rej(new Error((r && r.error) || "sin permiso")); return; }
        GD.token = r.access_token; GD.vence = Date.now() + (+r.expires_in || 3600) * 1000; res(true);
      }, error_callback:e => rej(new Error((e && e.type) || "cancelado"))});
      GD.cliente.requestAccessToken({prompt:silencioso ? "" : (gdEstado().cuenta ? "" : "consent")});
    } catch (e) { rej(e); }
  });
}
async function gdFetch(url, opt, reintento){
  const r = await fetch(url, {...(opt || {}), headers:{...((opt || {}).headers || {}), Authorization:`Bearer ${GD.token}`}});
  if (r.status === 401 && !reintento){ GD.token = ""; throw new Error("vencido"); }
  if (!r.ok){ let m = ""; try { m = (await r.json()).error.message; } catch (e) { logSilencioso(e); } throw new Error(m || `Drive respondió ${r.status}`); }
  return r;
}
async function gdJson(url, opt){ return (await gdFetch(url, opt)).json(); }
async function gdCrearCarpeta(nombre, padre){
  return gdJson(`${GD_API}/files?fields=id,name,webViewLink`, {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({name:nombre, mimeType:"application/vnd.google-apps.folder", ...(padre ? {parents:[padre]} : {})})});
}
async function gdSubir(nombre, mime, datos, carpeta, id){
  if (id){
    try { return await gdJson(`${GD_UP}/files/${id}?uploadType=media&fields=id,name,webViewLink,modifiedTime`, {method:"PATCH", headers:{"Content-Type":mime}, body:datos}); }
    catch (e) { if (!/404|not found|File not found/i.test(e.message)) throw e; }
  }
  const b = "lapacho" + Math.random().toString(36).slice(2), meta = JSON.stringify({name:nombre, mimeType:mime, parents:[carpeta]});
  const cuerpo = new Blob([`--${b}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${meta}\r\n--${b}\r\nContent-Type: ${mime}\r\n\r\n`, datos, `\r\n--${b}--`]);
  return gdJson(`${GD_UP}/files?uploadType=multipart&fields=id,name,webViewLink,modifiedTime`, {method:"POST", headers:{"Content-Type":`multipart/related; boundary=${b}`}, body:cuerpo});
}
function gdRespaldo(){
  try { save(); } catch (e) { logSilencioso(e); }
  const datos = {};
  CLAVES_RESPALDO.forEach(k => { try { const v = localStorage.getItem(k); if (v != null) datos[k] = v; } catch (e) { logSilencioso(e); } });
  return {app:"planificador-clases", tipo:"respaldo", version:1, fecha:new Date().toISOString(), origen:"drive", datos, fotos:[]};
}
function gdNombreCurso(c){ return `Lapacho · ${nombreCurso(c)}${c.ciclo ? ` · ${c.ciclo}` : ""}.xlsx`.replace(/[\\/:*?"<>|]/g, "-"); }
async function gdAsegurarCarpeta(){
  const st = gdEstado();
  if (st.carpeta){
    try { const f = await gdJson(`${GD_API}/files/${st.carpeta}?fields=id,name,trashed,webViewLink`); if (!f.trashed){ if (f.name !== st.carpetaNom) gdGuardarEstado({carpetaNom:f.name, carpetaUrl:f.webViewLink}); return st.carpeta; } }
    catch (e) { if (!/404|not found/i.test(e.message)) throw e; }
  }
  const f = await gdCrearCarpeta("Lapacho - mis cursos");
  gdGuardarEstado({carpeta:f.id, carpetaNom:f.name, carpetaUrl:f.webViewLink, archivos:{}});
  return f.id;
}
async function gdSincronizarV43(manual){
  if (GD.ocupado) return;
  const st = gdEstado();
  if (!st.activo) return;
  if (!gdConectado()){
    if (!manual){ GD.pendiente = true; renderTuDia(); return; }
    await gdPedirToken(true);
  }
  GD.ocupado = true; GD.error = ""; renderGD();
  try {
    const carpeta = await gdAsegurarCarpeta(), arch = {...(gdEstado().archivos || {})};
    const que = gdEstado().que || {};
    if (que.respaldo !== false){
      const r = await gdSubirSeguro("lapacho-copia-de-seguridad.json", "application/json", JSON.stringify(gdRespaldo()), carpeta, arch.respaldo);
      arch.respaldo = {id:r.id, url:r.webViewLink, n:"Copia de seguridad", mod:r.modifiedTime};
    }
    for (const c of (que.cursos !== false ? cdatos().cursos : [])){
      const bytes = xlsxLibro(hojaCursoCompleto(c));
      const x = await gdSubirSeguro(gdNombreCurso(c), XLSX_MIME, new Blob([bytes], {type:XLSX_MIME}), carpeta, arch["c:" + c.id]);
      arch["c:" + c.id] = {id:x.id, url:x.webViewLink, n:nombreCurso(c), mod:x.modifiedTime};
    }
    gdGuardarEstado({archivos:arch, ult:Date.now()});
    GD.pendiente = false;
    setTimeout(gdAvisarConflictos, 0);
    if (manual) toast("Listo: tus cursos quedaron en Google Drive.", gdEstado().carpetaUrl ? {label:"Abrir la carpeta", fn:() => window.open(gdEstado().carpetaUrl, "_blank", "noopener")} : undefined);
  } catch (e) {
    GD.error = /vencido/.test(e.message) ? "Se venció el permiso de Google. Tocá «Sincronizar ahora» para renovarlo." : /popup|cancel|sin permiso|access_denied/i.test(e.message) ? "No se dio permiso en Google." : `No se pudo sincronizar: ${e.message}`;
    GD.pendiente = true;
    if (manual) toast(GD.error);
  } finally { GD.ocupado = false; renderGD(); renderTuDia(); }
}
function gdProgramar(){
  if (!gdEstado().activo) return;
  GD.pendiente = true;
  clearTimeout(GD.timer);
  GD.timer = setTimeout(() => { if (gdConectado()) gdSincronizar(false); else renderTuDia(); }, 20000);
}
/* Combina un curso de Drive con el de este dispositivo sin borrar nada */
function gdMezclarCurso(a, b){
  const arr = k => { a[k] = fusionarArr(a[k] || [], b[k] || []); };
  ["alumnos", "evals", "temas", "cond", "agenda", "interv", "planes", "horario"].forEach(k => { if (Array.isArray(b[k])) { if (k === "planes") a.planes = [...new Set([...(a.planes || []), ...b.planes])]; else if (k === "horario") a.horario = (a.horario || []).length ? a.horario : b.horario; else arr(k); } });
  a.asis = a.asis || {}; Object.entries(b.asis || {}).forEach(([f, m]) => { a.asis[f] = {...m, ...(a.asis[f] || {})}; });
  a.notas = a.notas || {}; Object.entries(b.notas || {}).forEach(([aid, m]) => { const x = a.notas[aid] = a.notas[aid] || {}; Object.entries(m || {}).forEach(([e, v]) => { if (x[e] === "" || x[e] == null) x[e] = v; }); });
  a.fichas = {...(b.fichas || {}), ...(a.fichas || {})};
  return a;
}
async function gdTraerV43(){
  const st = gdEstado(), arch = (st.archivos || {}).respaldo;
  if (!arch){ toast("Todavía no hay una copia en Drive. Sincronizá primero desde el dispositivo donde cargás los datos."); return; }
  if (!gdConectado()) await gdPedirToken(true);
  GD.ocupado = true; renderGD();
  try {
    const o = await gdJson(`${GD_API}/files/${arch.id}?alt=media`);
    if (!o || o.tipo !== "respaldo" || !o.datos) throw new Error("la copia de Drive no es válida");
    const cb = JSON.parse(o.datos["planificador-cursos-v1"] || "null");
    if (cb && Array.isArray(cb.cursos)){
      const ca = cdatos();
      cb.cursos.forEach(c => { const x = ca.cursos.find(y => y.id === c.id); if (x) gdMezclarCurso(x, c); else ca.cursos.push(c); });
      if (!ca.sel && ca.cursos[0]) ca.sel = ca.cursos[0].id;
      cguardar();
      delete o.datos["planificador-cursos-v1"];
    }
    $("resp-modo").value = "agregar";
    await restaurarRespaldo(new File([JSON.stringify(o)], "drive.json", {type:"application/json"}));
  } catch (e) { toast(/vencido/.test(e.message) ? "Se venció el permiso de Google: tocá de nuevo." : `No se pudo traer la copia: ${e.message}`); }
  finally { GD.ocupado = false; renderGD(); }
}
async function gdElegirCarpeta(){
  const c = gdCfg();
  if (!c.apiKey){ toast("Para elegir la carpeta de la cátedra hace falta configurar la clave de Google Picker. Mientras tanto, mové la carpeta «Lapacho - mis cursos» adentro de la de la cátedra: sigue sincronizando."); return; }
  if (!gdConectado()) await gdPedirToken(true);
  if (!(window.google && window.google.picker)){ await cargarScript("https://apis.google.com/js/api.js"); await new Promise(r => window.gapi.load("picker", r)); }
  const vista = new window.google.picker.DocsView(window.google.picker.ViewId.FOLDERS).setSelectFolderEnabled(true).setIncludeFolders(true).setMimeTypes("application/vnd.google-apps.folder");
  const p = new window.google.picker.PickerBuilder().addView(vista).setOAuthToken(GD.token).setDeveloperKey(c.apiKey).setLocale("es").setTitle("Elegí la carpeta de la cátedra")
    .setCallback(d => { if (d.action !== window.google.picker.Action.PICKED) return; const f = d.docs[0]; gdGuardarEstado({carpeta:f.id, carpetaNom:f.name, carpetaUrl:f.url, archivos:{}}); renderGD(); toast(`Se va a sincronizar en «${f.name}».`); });
  if (c.appId) p.setAppId(c.appId);
  p.build().setVisible(true);
}
function avisosGD(){
  const st = gdEstado(); if (!st.activo) return [];
  if (GD.pendiente && !gdConectado()) return [{f:"0", t:"Hay cambios de tus cursos sin subir a Google Drive. Tocá para sincronizar.", act:"gdrive"}];
  if (GD.error) return [{f:"0", t:GD.error, act:"gdrive"}];
  return [];
}
function renderGDBase(){
  const P = $("gd-panel"); if (!P || !$("gdrive").open) return;
  const d = gdDisponible(), st = gdEstado(), c = gdCfg();
  if (!d.ok){
    P.innerHTML = d.motivo === "lugar" ? `<p>La sincronización con Google Drive funciona en la aplicación instalada (la versión publicada en GitHub). En esta versión podés usar la copia de seguridad y guardar el archivo en tu Drive.</p><div class="cur-bar"><button type="button" class="btn btn-sm" data-gd="respaldo">Copia de seguridad</button></div>`
      : `<p>Falta configurar el acceso a Google en esta instalación. Quien publica la aplicación tiene que cargar el «ID de cliente» de Google (está explicado en el LEEME del paquete).</p>${htmlGDConfig(c)}`;
    return;
  }
  const arch = Object.values(st.archivos || {});
  P.innerHTML = !st.activo ? `<p>Guardá una copia de tus cursos en tu Google Drive: asistencia, notas, conducta y libro de temas de cada curso en una planilla, más una copia completa para pasar todo a otro dispositivo. Se actualiza sola cuando hacés cambios.</p>
      <ul class="gd-l"><li>Entrás con tu cuenta de Google. Lapacho nunca ve ni guarda tu contraseña.</li><li>Lapacho solo puede ver los archivos que crea en tu Drive o la carpeta que elijas, nada más.</li><li>Si la carpeta es compartida, las personas con acceso ven los datos de tus estudiantes. Usá la cuenta institucional si tu escuela lo pide.</li></ul>
      <label class="cp-ck"><input type="checkbox" id="gd-ok"> Entiendo que los nombres, notas y asistencias de mis estudiantes se van a guardar en Google Drive.</label>
      <div class="cur-bar"><button type="button" class="btn btn-primary" data-gd="conectar">Conectar con Google</button></div>`
    : `<p class="gd-est">${GD.ocupado ? "Sincronizando…" : st.ult ? `Última sincronización: ${(() => { const d = new Date(st.ult); return `${fechaCortaIso(isoDe(d))} a las ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`; })()}.` : "Todavía no se sincronizó."}${GD.pendiente && !GD.ocupado ? " Hay cambios sin subir." : ""}</p>
      ${GD.error ? `<p class="aviso-c" role="alert">${esc(GD.error)}</p>` : ""}
      <p>Carpeta: ${st.carpetaUrl ? `<a href="${esc(st.carpetaUrl)}" target="_blank" rel="noopener">${esc(st.carpetaNom || "Lapacho - mis cursos")}</a>` : "se crea «Lapacho - mis cursos» en tu Drive la primera vez"}</p>
      <fieldset class="gd-que"><legend>Qué se sube</legend><label class="cp-ck"><input type="checkbox" data-gdque="respaldo"${(st.que || {}).respaldo !== false ? " checked" : ""}> La copia completa, para pasar todo a otro dispositivo</label><label class="cp-ck"><input type="checkbox" data-gdque="cursos"${(st.que || {}).cursos !== false ? " checked" : ""}> Una planilla por curso: asistencia, notas, conducta y libro de temas</label></fieldset>
      <div class="cur-bar"><button type="button" class="btn btn-primary" data-gd="sync"${GD.ocupado ? " disabled" : ""}>${GD.error ? "Reintentar" : "Sincronizar ahora"}</button><button type="button" class="btn btn-sm" data-gd="carpeta">Elegir la carpeta de la cátedra</button><button type="button" class="btn btn-sm" data-gd="traer"${GD.ocupado ? " disabled" : ""}>Traer desde Drive</button></div>
      ${arch.length ? `<details class="cur-sub"><summary>Archivos en Drive (${arch.length})</summary><ul class="gd-l">${arch.map(a => `<li><a href="${esc(a.url || "#")}" target="_blank" rel="noopener">${esc(a.n)}</a></li>`).join("")}</ul></details>` : ""}
      <p class="hint">«Traer desde Drive» suma a este dispositivo lo que se cargó en otro (alumnos, fechas de asistencia y notas que falten). Lo que ya está acá no se pisa. Las fotos no se suben.</p>
      <div class="cur-bar"><button type="button" class="linkbtn" data-gd="desconectar">Dejar de sincronizar</button></div>`;
}
function htmlGDConfig(c){
  return `<details class="cur-sub"><summary>Configurar el acceso a Google</summary><div class="cfg-grid"><div class="f full"><label for="gd-cid">ID de cliente de OAuth</label><input id="gd-cid" value="${esc(c.clientId)}" placeholder="…apps.googleusercontent.com"></div><div class="f"><label for="gd-key">Clave de API (opcional, para elegir la carpeta)</label><input id="gd-key" value="${esc(c.apiKey)}"></div><div class="f"><label for="gd-app">Número de proyecto (opcional)</label><input id="gd-app" value="${esc(c.appId)}" inputmode="numeric"></div></div><div class="cur-bar"><button type="button" class="btn btn-sm" data-gd="guardarcfg">Guardar</button></div></details>`;
}
function abrirGD(){ abrirDialogo("gdrive"); renderGD(); }
function bindGD(){
  $("btn-gdrive").addEventListener("click", abrirGD);
  $("gdrive").addEventListener("click", async e => {
    const b = e.target.closest("[data-gd]"); if (!b) return;
    const v = b.dataset.gd;
    if (v === "respaldo"){ cerrarDialogo("gdrive"); abrirRespaldo(); return; }
    if (v === "guardarcfg"){ gdGuardarCfg(); return; }
    if (v === "conectar"){
      if (!$("gd-ok").checked){ toast("Marcá que entendés dónde se guardan los datos."); return; }
      try { await gdPedirToken(false); gdGuardarEstado({activo:true, cuenta:true}); renderGD(); await gdSincronizar(true); }
      catch (err) { toast("No se pudo conectar con Google. Probá de nuevo."); }
      return;
    }
    if (v === "sync"){ try { await gdSincronizar(true); } catch (err) { toast("No se pudo conectar con Google."); } return; }
    if (v === "traer"){ try { await gdTraer(); } catch (err) { toast("No se pudo conectar con Google."); } return; }
    if (v === "carpeta"){ try { await gdElegirCarpeta(); } catch (err) { toast("No se pudo abrir el selector de carpetas."); } return; }
    if (v === "desconectar"){
      if (!window.confirm("Lapacho deja de subir tus cursos a Drive. Los archivos que ya están en Drive no se borran. ¿Seguimos?")) return;
      try { if (GD.token && window.google && window.google.accounts) window.google.accounts.oauth2.revoke(GD.token, () => {}); } catch (err) { logSilencioso(err); }
      GD.token = ""; GD.pendiente = false; GD.error = ""; prefSet("gd", {}); renderGD(); renderTuDia();
    }
  });
}

