function contextoLocal(area, pesos, I, tema, caso){
  const R = lugarRefs(I);
  const rc = new Set(raices(caso || "").filter(r => !LB_GEN.has(r)));
  const adelanta = c => rc.size && raices(ctxRellenar(c.ver + " " + c.q, R)).filter(r => rc.has(r)).length >= 2;
  const cand = CONTEXTOS.filter(c => c.a.includes(area) && ctxDiscOk(c) && (!c.z || c.z.includes(I.zona)) && (!c.sinZ || !c.sinZ.includes(I.zona)) && !adelanta(c))
    .map(c => ({c, s:napPuntaje({r:[...new Set(raices(c.k))]}, pesos)})).filter(x => x.s > 0).sort((a, b) => b.s - a.s);
  if (cand.length){ const c = cand[0].c; return {ver:contraer(ctxRellenar(c.ver, R)), q:contraer(ctxRellenar(c.q, R)), cts:contraer(ctxRellenar(c.cts, R))}; }
  return {ver:contraer(`una foto o un video corto de un lugar conocido de ${R.lugar} donde ${taVerbo(tema, "aparezca", "aparezcan")} ${temaArt(tema)}`), q:contraer(`¿Qué ven en esta imagen que tenga que ver con ${temaArt(tema)}?`), cts:""};
}
