function cientificosDe(texto, pesos, max){
  const n = " " + norm(texto || "") + " ";
  const nombrados = CIENTIFICOS.filter(c => n.includes(" " + c.n + " ") || n.includes(" " + c.n.slice(0, 6)));
  const porTema = CIENTIFICOS.filter(c => !nombrados.includes(c)).map(c => ({c, h:napCoinciden({r:[...new Set(raices(c.k))]}, pesos)})).filter(x => x.h >= 2).sort((a, b) => b.h - a.h).map(x => x.c);
  return [...nombrados, ...porTema].slice(0, max || 2);
}
