  /* ideas previas y conflicto */
  const aperturaTxt = m === "secuencia" ? val("sc1_a") : m === "proyecto" ? val("etapa1") + "\n" + val("etapa2") : m === "anual" ? val("diagnostica") : val("inicio");
  add("previas", "Ideas previas", RX_PREVIAS.test(aperturaTxt + "\n" + val("diagnostica")) ? "ok" : "mejorar", RX_PREVIAS.test(aperturaTxt + "\n" + val("diagnostica")) ? "Se relevan las ideas previas al comenzar." : "El comienzo no recupera las ideas previas del grupo.", "Empezá con una pregunta o una situación que haga aparecer lo que el grupo ya piensa, y registralo para volver al final.", m === "secuencia" ? "sc1_a" : m === "proyecto" ? "etapa2" : m === "anual" ? "diagnostica" : "inicio");
