  add("biblio", "Bibliografía", val("bibliografia") ? "ok" : "falta", val("bibliografia") ? "Está la bibliografía." : "Falta la bibliografía.", "Citá el material que usás (autor, año, título y editorial) y el diseño curricular.", "bibliografia");
  /* criterios propios de la secuencia */
