/* ============================================================
   Versión 37: seguridad, diagnóstico, copias cifradas, panel principal y navegación de escritorio
   ============================================================ */
const LAPACHO_VERSION = "85 (22/11/2026)";

/* ---------- Registro de errores ----------
   Autocontenido (sin constantes externas) porque se usa desde cualquier punto del script, incluso durante la carga.
   Guarda fecha, módulo y descripción técnica; limpia correos, números largos, datos en base64 y tokens. */
var ERRLOG_MEM = null, ERRLOG_VISTOS = null, ERRLOG_TOAST = 0, ERRLOG_QUOTA = 0;
function errLeer(){
  if (ERRLOG_MEM) return ERRLOG_MEM;
  try { const r = JSON.parse(localStorage.getItem("planificador-errores-v1") || "[]"); ERRLOG_MEM = Array.isArray(r) ? errNormalizar(r) : []; }
  catch (e) { ERRLOG_MEM = []; /* registro dañado o sin acceso: se empieza uno nuevo en memoria */ }
  return ERRLOG_MEM;
}
function errLimpiarTexto(t){
  return String(t == null ? "" : t)
    .replace(/data:[^\s"')]{16,}/g, "data:…")
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, "[correo]")
    .replace(/\b\d{7,}\b/g, "[número]")
    .replace(/\b(access_token|token|pin|clave|password|contraseña)\b\s*[=:]\s*[^\s&"]+/gi, "$1=[oculto]")
    .slice(0, 400);
}
function errModulo(err){
  const st = String(err && err.stack || "");
  const m = /at (?:async )?([A-Za-z_$][\w$]*)/.exec(st) || /^([A-Za-z_$][\w$]*)@/m.exec(st);
  return m ? m[1] : "app";
}
function avisoUsuario(msg, accion){
  try { if (typeof toast === "function" && document.getElementById("toast")) toast(msg, accion); }
  catch (e) { /* sin interfaz todavía: el aviso queda solo en el registro */ }
}
function registrarError(mod, err, nivel){
  try {
    const msg = errLimpiarTexto(err && (err.message || err.reason) || err || "Error desconocido");
    const stack = errLimpiarTexto(String(err && err.stack || "").split("\n").slice(0, 4).join(" | "));
    ERRLOG_VISTOS = ERRLOG_VISTOS || new Set();
    const k = `${mod}|${msg}`, L = errLeer();
    const prev = L.find(y => y.k === k);
    if (prev){ prev.n = (prev.n || 1) + 1; prev.f = new Date().toISOString(); }
    else L.push({k, f:new Date().toISOString(), mod:String(mod || "app").slice(0, 60), nivel:nivel || "error", msg, stack, n:1});
    while (L.length > 100) L.shift();
    if (!ERRLOG_VISTOS.has(k) || (prev && prev.n % 10 === 0)){
      ERRLOG_VISTOS.add(k);
      try { localStorage.setItem("planificador-errores-v1", JSON.stringify(L)); }
      catch (e2) { /* sin espacio para el registro: queda en memoria y se puede exportar igual */ }
    }
    const cuota = err && (err.name === "QuotaExceededError" || err.code === 22 || /quota|exceeded the quota/i.test(msg));
    if (cuota && Date.now() - ERRLOG_QUOTA > 30000){ ERRLOG_QUOTA = Date.now(); avisoUsuario("No queda espacio en este navegador. Descargá una copia de seguridad y borrá fotos o cursos que ya no uses."); }
  } catch (e) { /* el registro de errores nunca puede romper la aplicación */ }
}
/* Reemplaza a los antiguos catch vacíos: deja constancia sin interrumpir al docente */
function logSilencioso(err){ registrarError(errModulo(err), err, "aviso"); }
window.addEventListener("error", ev => {
  if (!ev || !ev.error && !ev.message) return;
  registrarError(errModulo(ev.error), ev.error || ev.message, "error");
  if (Date.now() - ERRLOG_TOAST > 20000){ ERRLOG_TOAST = Date.now(); avisoUsuario("Algo no salió como esperábamos. Quedó anotado en Ajustes › Diagnóstico.", {label:"Ver", fn:() => abrirDiag()}); }
});
window.addEventListener("unhandledrejection", ev => {
  const r = ev && ev.reason;
  registrarError(errModulo(r), r || "Promesa rechazada", "error");
  if (Date.now() - ERRLOG_TOAST > 20000){ ERRLOG_TOAST = Date.now(); avisoUsuario("Una operación no terminó bien. Quedó anotado en Ajustes › Diagnóstico.", {label:"Ver", fn:() => abrirDiag()}); }
});

/* ---------- Diagnóstico ---------- */
async function datosDiagnostico(){
  let est = null;
  try { if (navigator.storage && navigator.storage.estimate) est = await navigator.storage.estimate(); } catch (e) { logSilencioso(e); }
  let persist = null;
  try { if (navigator.storage && navigator.storage.persisted) persist = await navigator.storage.persisted(); } catch (e) { logSilencioso(e); }
  const D = cdatos(), claves = {};
  CLAVES_RESPALDO.forEach(k => { try { const v = localStorage.getItem(k); if (v != null) claves[k] = v.length; } catch (e) { logSilencioso(e); } });
  return {app:"Lapacho", version:LAPACHO_VERSION, fecha:new Date().toISOString(), navegador:navigator.userAgent, idioma:navigator.language, pantalla:`${innerWidth}x${innerHeight}`, enLinea:navigator.onLine,
    protocolo:location.protocol, almacenamiento:est ? {usadoMB:Math.round(est.usage / 1048576 * 10) / 10, cuotaMB:Math.round(est.quota / 1048576)} : "no disponible", almacenamientoPersistente:persist,
    tamañoPorClave:claves, conteos:{cursos:D.cursos.length, estudiantes:D.cursos.reduce((a, c) => a + (c.alumnos || []).length, 0), planificaciones:libLeer().length},
    pin:!!leerPref().pin, drive:!!(leerPref().gd || {}).activo,
    errores:errLeer().map(({k, ...x}) => x)};
}
function abrirDiag(){ abrirDialogo("diag"); renderDiag(); }
async function renderDiagBase(){
  const P = $("diag-panel"); if (!P) return;
  const L = errLeer().slice().reverse(), D = await datosDiagnostico();
  P.innerHTML = `<p class="hint">Si algo no funciona, este registro ayuda a encontrar la causa. Guarda la fecha, la parte de la app y la descripción técnica del problema. No guarda nombres de estudiantes, notas, contraseñas, PIN ni permisos de Google.</p>
    <dl class="inf-datos"><div><dt>Versión</dt><dd>${esc(D.version)}</dd></div><div><dt>Espacio usado</dt><dd>${typeof D.almacenamiento === "object" ? `${D.almacenamiento.usadoMB} MB de ${D.almacenamiento.cuotaMB} MB` : "no disponible"}</dd></div>
    <div><dt>Almacenamiento protegido</dt><dd>${D.almacenamientoPersistente == null ? "no disponible" : D.almacenamientoPersistente ? "sí: el navegador no lo borra solo" : "no: el navegador puede borrarlo si falta espacio"}</dd></div><div><dt>Conexión</dt><dd>${D.enLinea ? "con internet" : "sin internet"}</dd></div></dl>
    ${L.length ? `<ul class="diag-l">${L.slice(0, 50).map(x => `<li class="${x.nivel === "error" ? "err" : "av"}"><b>${esc(fechaCortaIso(x.f.slice(0, 10)))} ${esc(x.f.slice(11, 16))} · ${esc(x.mod)}${x.n > 1 ? ` · ${x.n} veces` : ""}</b><span>${x.nivel === "error" ? "Error" : "Aviso"}: ${esc(x.msg)}</span></li>`).join("")}</ul>` : `<p class="hint">No hay errores registrados.</p>`}
    <div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-dg="exportar">Exportar el diagnóstico</button>${L.length ? `<button type="button" class="btn btn-sm" data-dg="limpiar">Limpiar el registro</button>` : ""}</div>
    <p class="hint">El diagnóstico exportado incluye la versión, el navegador, el espacio usado, cuántos cursos y planificaciones hay (solo la cantidad) y los errores. Revisalo antes de compartirlo.</p>`;
}
function bindDiag(){
  $("diag").addEventListener("click", async e => {
    const b = e.target.closest("[data-dg]"); if (!b) return;
    if (b.dataset.dg === "exportar"){ const D = await datosDiagnostico(); await guardarArchivo(`diagnostico-lapacho-${hoyIso()}.json`, new Blob([JSON.stringify(D, null, 2)], {type:"application/json"}), "Diagnóstico descargado."); }
    if (b.dataset.dg === "limpiar"){
      if (!window.confirm("Se borra el registro de errores de este navegador. ¿Seguimos?")) return;
      ERRLOG_MEM = []; ERRLOG_VISTOS = new Set();
      try { localStorage.removeItem("planificador-errores-v1"); } catch (err) { logSilencioso(err); }
      renderDiag(); toast("Registro de errores limpio.");
    }
  });
}

/* ---------- Utilidades de bytes y base64 (por partes, para archivos grandes) ---------- */
const B64 = {
  de(bytes){ let s = ""; for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000)); return btoa(s); },
  a(str){ const bin = atob(String(str || "")); const u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; }
};
async function sha256Hex(texto){ const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(texto)); return [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, "0")).join(""); }

/* ---------- PIN reforzado: PBKDF2 con sal, intentos limitados y bloqueo por inactividad ----------
   El PIN bloquea la interfaz; no cifra los datos guardados en el navegador. */
const PIN_INT_KEY = "planificador-pin-intentos";
async function pinDerivar(pin, salB64, iter){
  const base = await crypto.subtle.importKey("raw", new TextEncoder().encode(pin), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({name:"PBKDF2", hash:"SHA-256", salt:B64.a(salB64), iterations:iter}, base, 256);
  return B64.de(new Uint8Array(bits));
}
async function pinCrearHash(pin){ const sal = B64.de(crypto.getRandomValues(new Uint8Array(16))), it = 200000; return `p2$${it}$${sal}$${await pinDerivar(pin, sal, it)}`; }
async function pinCoincide(pin, guardado){
  if (!guardado) return false;
  if (String(guardado).startsWith("p2$")){ const [, it, sal, h] = guardado.split("$"); return (await pinDerivar(pin, sal, +it)) === h; }
  return (await hashPIN(pin)) === guardado;
}
function pinIntentos(){ try { return JSON.parse(localStorage.getItem(PIN_INT_KEY) || "{}") || {}; } catch (e) { logSilencioso(e); return {}; } }
function pinEspera(){ const t = pinIntentos(); return t.hasta && t.hasta > Date.now() ? Math.ceil((t.hasta - Date.now()) / 1000) : 0; }
function pinFallo(){
  const t = pinIntentos(); t.n = (t.n || 0) + 1;
  if (t.n >= 3) t.hasta = Date.now() + Math.min(15 * 60, 30 * Math.pow(2, t.n - 3)) * 1000;
  try { localStorage.setItem(PIN_INT_KEY, JSON.stringify(t)); } catch (e) { logSilencioso(e); }
  return t;
}
function pinMensajeFallo(t){ return t.n < 3 ? `PIN incorrecto. Te ${3 - t.n === 1 ? "queda 1 intento" : `quedan ${3 - t.n} intentos`} antes de una espera.` : `PIN incorrecto. Esperá ${pinEspera()} segundos para volver a intentar.`; }
async function pinExito(pin){
  try { localStorage.removeItem(PIN_INT_KEY); } catch (e) { logSilencioso(e); }
  const g = leerPref().pin;
  if (g && !String(g).startsWith("p2$")) prefSet("pin", await pinCrearHash(pin));
  pinActividad = Date.now();
}
var pinActividad = Date.now();
const DLG_SENSIBLES = ["micurso", "aula", "ppi", "actas", "legajo", "capac", "carpeta", "fotoia", "corregir", "respaldo", "cargos"];
function bloquearAhora(motivo){
  if (!leerPref().pin) return;
  pinOk = false;
  DLG_SENSIBLES.forEach(id => { const d = $(id); if (d && d.open){ try { cerrarDialogo(id); } catch (e) { logSilencioso(e); d.close(); } } });
  if (motivo) toast(motivo);
}
function iniciarBloqueoInactividad(){
  ["pointerdown", "keydown", "touchstart", "wheel"].forEach(t => document.addEventListener(t, () => { pinActividad = Date.now(); }, {passive:true, capture:true}));
  let oculto = 0;
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) oculto = Date.now();
    else if (oculto && pinOk && Date.now() - oculto > minutosBloqueo() * 60000) bloquearAhora("Lapacho se bloqueó porque estuvo un rato sin usarse. Para volver a ver los datos, ingresá el PIN.");
  });
  setInterval(revisarInactividad, 30000);
}
function revisarInactividad(){ if (pinOk && leerPref().pin && minutosBloqueo() > 0 && Date.now() - pinActividad > minutosBloqueo() * 60000) bloquearAhora("Lapacho se bloqueó por inactividad. Para volver a ver los datos, ingresá el PIN."); }
function minutosBloqueo(){ const m = leerPref().pinMin; return m === 0 ? 0 : +m || 10; }

/* ---------- Copia interna en IndexedDB (espejo) y almacenamiento protegido ---------- */
function idbSeg(){
  return new Promise((res, rej) => {
    const r = indexedDB.open("lapacho-seguridad", 1);
    r.onupgradeneeded = () => { const db = r.result; ["espejo", "previas"].forEach(s => { if (!db.objectStoreNames.contains(s)) db.createObjectStore(s); }); };
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
}
async function idbOp(store, modo, fn){
  const db = await idbSeg();
  return new Promise((res, rej) => {
    const tx = db.transaction(store, modo), os = tx.objectStore(store); let out;
    const rq = fn(os); if (rq) rq.onsuccess = () => { out = rq.result; };
    tx.oncomplete = () => { db.close(); res(out); }; tx.onerror = () => { db.close(); rej(tx.error); }; tx.onabort = () => { db.close(); rej(tx.error); };
  });
}
const idbPut = (s, k, v) => idbOp(s, "readwrite", os => os.put(v, k));
const idbGet = (s, k) => idbOp(s, "readonly", os => os.get(k));
const idbDel = (s, k) => idbOp(s, "readwrite", os => os.delete(k));
const idbKeys = s => idbOp(s, "readonly", os => os.getAllKeys());
function datosLocales(){
  const d = {};
  CLAVES_RESPALDO.forEach(k => { try { const v = localStorage.getItem(k); if (v != null) d[k] = v; } catch (e) { logSilencioso(e); } });
  return d;
}
let ESPEJO_ULT = "", ESPEJO_FECHA = "";
async function espejoGuardar(){
  try {
    const d = datosLocales(), s = JSON.stringify(d);
    if (s === ESPEJO_ULT || s === "{}") return;
    await idbPut("espejo", "ultimo", {fecha:new Date().toISOString(), datos:d});
    ESPEJO_ULT = s; ESPEJO_FECHA = new Date().toISOString();
  } catch (e) { logSilencioso(e); }
}
const cuentaDe = (d, k, f) => { try { const v = JSON.parse(d[k] || "null"); return v ? f(v) : 0; } catch (e) { logSilencioso(e); return 0; } };
function resumenDatos(d){
  const cursos = cuentaDe(d, "planificador-cursos-v1", v => Array.isArray(v.cursos) ? v.cursos.length : 0);
  return {cursos, estudiantes:cuentaDe(d, "planificador-cursos-v1", v => (v.cursos || []).reduce((a, c) => a + (c.alumnos || []).length, 0)),
    planificaciones:cuentaDe(d, "planificador-biblioteca-v1", v => Array.isArray(v) ? v.length : 0), legajo:cuentaDe(d, "planificador-legajo-v1", v => Object.values(v).reduce((a, x) => a + (Array.isArray(x) ? x.length : 0), 0))};
}
