/* ---------- PDF: símbolos científicos ---------- */
const PDF_SIMB = {"Α":"A", "Β":"B", "Γ":"Gamma", "Δ":"Delta ", "Θ":"Theta", "Λ":"Lambda", "Π":"Pi", "Σ":"Sigma", "Φ":"Phi", "Ψ":"Psi", "Ω":" ohm", "α":"alfa", "β":"beta", "γ":"gamma", "δ":"delta", "ε":"epsilon", "θ":"theta", "λ":"lambda", "μ":"µ", "ν":"nu", "π":"pi", "ρ":"rho", "σ":"sigma", "τ":"tau", "φ":"phi", "ω":"omega",
  "≈":"~", "≠":"!=", "√":"raíz de ", "∞":"infinito", "∝":" prop. a ", "⋅":"·", "∙":"·", "∆":"Delta ", "←":"<-", "⇒":"=>", "↔":"<->",
  "₀":"0", "₁":"1", "₂":"2", "₃":"3", "₄":"4", "₅":"5", "₆":"6", "₇":"7", "₈":"8", "₉":"9", "₊":"+", "₋":"-",
  "⁰":"^0", "⁴":"^4", "⁵":"^5", "⁶":"^6", "⁷":"^7", "⁸":"^8", "⁹":"^9", "⁻":"^-", "⁺":"^+", "ⁿ":"^n"};
var PDF_REEMPLAZOS = 0;
function pdfTxt2(s){
  return String(s || "").replace(/[…–—“”‘’•≥≤−→↑↓]/g, c => PDF_MAP[c])
    .replace(/[^\x09\x0A\x0D\x20-\xFF]/g, c => { PDF_REEMPLAZOS++; return c in PDF_SIMB ? PDF_SIMB[c] : ""; });
}

