/* ============================================================
   Versión 37.1: fusión con la versión publicada el 23/10
   ============================================================ */
/* Revisión de la coherencia didáctica */
const VERBOS_VAGOS = ["comprender", "comprendan", "comprenda", "conocer", "conozcan", "conozca", "saber", "sepan", "sepa", "entender", "entiendan", "entienda", "aprender", "aprendan", "aprenda", "valorar", "valoren", "valore", "apreciar", "aprecien", "tomar conciencia", "tomen conciencia", "familiarizarse", "se familiaricen", "interiorizarse", "internalizar", "internalicen", "reflexionar sobre", "reflexionen sobre"];
const VACIAS = new Set("que los las estudiantes alumnos alumnas logren puedan para sobre entre desde hasta como cuando donde porque segun mediante traves tambien ademas cada este esta estos estas otros otras partir respecto cotidianos cotidianas situaciones distintos distintas diferentes".split(" "));
function recorte(t){ t = String(t); return t.length > 70 ? t.slice(0, 67) + "…" : t; }
function sinSujeto(o){ return norm(o).replace(/^que\s+(los|las|el|la)?\s*(estudiantes|alumnos|alumnas|alumno|alumna|estudiante|chicos|chicas)?\s*(logren|puedan|sean capaces de)?\s*/, "").trim(); }
function clavesDe(o){ const w = sinSujeto(o).replace(/[^a-zñ0-9\s]/g, " ").split(/\s+/).filter(Boolean); return w.slice(1).filter(x => x.length >= 6 && !VACIAS.has(x)).map(x => x.slice(0, 6)); }
function enClase(){ return !state.modo || state.modo === "clase"; }
function textoActividades(){ return ["inicio", "desarrollo", "cierre", "caso", ...(enClase() ? [] : ALL_IDS.filter(id => /^(sc\d+_[ta]|etapa\d)$/.test(id)))].map(val).join("\n"); }
function textoEvaluacion(){ return ["diagnostica", "formativa", "sumativa", "instrumentos", "criterios", "rubrica", "rubrica_est", "cotejo", "escala", "ticket", ...(enClase() ? [] : ALL_IDS.filter(id => /^sc\d+_e$/.test(id)))].map(val).join("\n"); }
function revisarCoherenciaBase(){
  const av = [], A = (n, t, id) => av.push({n, t, id});
  const gen = itemsLista(val("objgen")), esp = itemsLista(val("objetivos")), todos = [...gen.map(o => ({o, id:"objgen"})), ...esp.map(o => ({o, id:"objetivos"}))];
  const act = norm(textoActividades()), ev = norm(textoEvaluacion());
  if (!todos.length) A("alto", "No hay objetivos cargados. Sin objetivos no se puede revisar si las actividades y la evaluación apuntan a algo.", "objetivos");
  if (!act.trim()) A("alto", "Faltan las actividades: inicio, desarrollo y cierre.", "inicio");
  if (!ev.trim()) A("alto", "No hay criterios ni instrumentos de evaluación: no queda claro cómo se va a saber si se lograron los objetivos.", "criterios");
  todos.forEach(({o, id}) => {
    const s = sinSujeto(o), primera = s.split(/[,.;:]/)[0];
    const vago = VERBOS_VAGOS.find(v => new RegExp("(^|\\s)" + norm(v) + "(\\s|$)").test(primera));
    if (vago) A("medio", `«${recorte(o)}» usa «${vago}», que no se puede observar. Reemplazalo por lo que el estudiante hace para demostrarlo: explicar, describir, resolver, dibujar, comparar, argumentar.`, id);
    const n = s.split(/\s+/).length;
    if (n > 32) A("info", `«${recorte(o)}» es largo (${n} palabras). Un objetivo claro tiene un verbo principal y una sola idea.`, id);
  });
  const exO = /(experiment|medir|midan|mida |registren datos|hipotesis|indag|laboratorio|disenen un dispositivo|construyan un dispositivo)/, exA = /(experiment|medi|registr|hipotesis|laboratorio|simulad|simulacion|phet|dispositivo|procedimiento|materiales)/;
  if (todos.some(x => exO.test(norm(x.o)))){
    if (act.trim() && !exA.test(act)) A("alto", "Hay un objetivo experimental (medir, experimentar, formular hipótesis), pero ninguna actividad incluye una experiencia, una medición o un simulador.", "desarrollo");
    if (ev.trim() && !/(procedimiento|registro|datos|hipotesis|informe|experien|medici)/.test(ev)) A("medio", "Hay un objetivo experimental, pero la evaluación no dice cómo se valora esa habilidad: registro de datos, procedimiento, informe.", "criterios");
  }
  if (todos.some(x => /(argument|justifiqu|justificar|fundament)/.test(norm(x.o))) && act.trim() && !/(argument|justific|fundament|debate|defiend|explicacion oral|expong|exposicion)/.test(act)) A("medio", "Hay un objetivo de argumentación, pero ninguna actividad pide argumentar, justificar o debatir.", "desarrollo");
  if (/(phet|simulador|simulacion)/.test(act) && !/(predic|anticip|que creen|hipotesis|antes de)/.test(act)) A("info", "Se usa un simulador sin una consigna de predicción. Pedir que anticipen el resultado antes de usarlo lo convierte en una actividad de indagación.", "desarrollo");
  const mins = ((enClase() ? ["inicio", "desarrollo", "cierre"].map(val).join("\n") : "").match(/\((\d{1,3})\s*(?:min|minutos)\)|(\d{1,3})\s*(?:min|minutos)\b/gi) || []).map(x => parseInt(x.replace(/\D/g, ""), 10)).filter(Boolean);
  const dur = parseInt(val("tiempo"), 10);
  if (dur && mins.length >= 2){ const tot = mins.reduce((a, b) => a + b, 0); if (tot > dur + 5) A("medio", `Los tiempos de las actividades suman ${tot} minutos y la clase dura ${dur}.`, "desarrollo"); }
  if (!["adecuaciones", "apoyo", "general", "avanzada", "dua_rep", "dua_acc", "dua_imp"].some(id => val(id))) A("info", "No hay adecuaciones ni alternativas para la diversidad del grupo. Aunque no haya estudiantes con PPI, conviene prever otra forma de presentar la información o de mostrar lo aprendido.", "adecuaciones");
  const mapa = esp.map(o => { const k = clavesDe(o); return {o, enAct:!k.length || k.some(x => act.includes(x)), enEv:!k.length || k.some(x => ev.includes(x))}; });
  mapa.forEach(m => { if (act.trim() && !m.enAct) A("medio", `Ninguna actividad parece trabajar «${recorte(m.o)}». Revisá que haya al menos una tarea en la que el estudiante haga eso.`, "desarrollo"); });
  return {av, mapa, ev:!!ev.trim()};
}
function abrirCoherenciaBase(){
  const {av, mapa, ev} = revisarCoherencia();
  const orden = {alto:0, medio:1, info:2}, nom = {alto:"Importante", medio:"Conviene revisar", info:"Sugerencia"};
  av.sort((a, b) => orden[a.n] - orden[b.n]);
  const lista = av.length ? `<ul class="coh-l">${av.map(a => `<li class="coh-${a.n}"><span class="coh-n">${nom[a.n]}</span><span>${esc(a.t)}</span><button type="button" class="linkbtn" data-goto-coh="${a.id}">Ir al campo</button></li>`).join("")}</ul>` : `<p class="coh-ok">No se encontraron contradicciones ni vacíos. Igual conviene leer la planificación completa: la revisión es automática y no reemplaza tu criterio.</p>`;
  const tabla = mapa.length ? `<h3 class="coh-h">Cada objetivo y su evidencia</h3><div class="d-table-wrap" tabindex="0" role="region" aria-label="Tabla, se desplaza hacia los costados"><table class="d-table coh-t"><thead><tr><th>Objetivo</th><th>¿Hay actividad?</th><th>¿Se evalúa?</th></tr></thead><tbody>${mapa.map(m => `<tr><td>${esc(m.o)}</td><td>${m.enAct ? "Sí" : "<b>No se encontró</b>"}</td><td>${!ev ? "<b>Falta la evaluación</b>" : m.enEv ? "Sí" : "No se menciona"}</td></tr>`).join("")}</tbody></table></div><p class="hint">La relación se detecta por las palabras clave de cada objetivo. Si un objetivo se trabaja con otras palabras, marcalo vos como resuelto.</p>` : "";
  $("coh-res").innerHTML = lista + tabla;
  abrirDialogo("coher");
}


/* ---------- Compatibilidad con la versión del 23/10 ---------- */
/* Copias cifradas de esa versión: {tipo:"respaldo-cifrado", cifrado:{alg, kdf, iter, salt, iv, datos}} sin datos adicionales */
async function descifrarLegado(c, pass){
  if (!c || c.alg !== "AES-GCM-256" || c.kdf !== "PBKDF2-SHA256" || !(c.iter >= 100000 && c.iter <= 10000000)) throw new Error("formato");
  const sal = B64.a(c.salt), iv = B64.a(c.iv);
  if (sal.length < 16 || iv.length !== 12) throw new Error("formato");
  const key = await derivarClaveResp(pass, sal, c.iter);
  return new TextDecoder().decode(await crypto.subtle.decrypt({name:"AES-GCM", iv}, key, B64.a(c.datos)));
}
/* Copias automáticas que esa versión guardó en la base «planificador-seguridad»: se suman a las de ahora sin borrar las originales */
function migrarPreviasLegado(){
  if (!window.indexedDB || leerPref().previasMigradas) return;
  let nueva = false;
  try {
    const r = indexedDB.open("planificador-seguridad", 1);
    r.onupgradeneeded = () => { nueva = true; try { r.transaction.abort(); } catch (e) { logSilencioso(e); } };
    r.onerror = () => { if (nueva) prefSet("previasMigradas", true); };
    r.onsuccess = () => {
      const db = r.result;
      try {
        if (!db.objectStoreNames.contains("previas")){ db.close(); prefSet("previasMigradas", true); return; }
        const q = db.transaction("previas").objectStore("previas").getAll();
        q.onsuccess = async () => {
          try {
            for (const p of (q.result || [])){
              if (!p || !p.o || !p.o.datos) continue;
              const fecha = new Date(p.id).toISOString();
              if (!(await idbGet("previas", fecha))) await idbPut("previas", fecha, {fecha, datos:p.o.datos, origen:"versión del 23/10"});
            }
            prefSet("previasMigradas", true);
          } catch (e) { registrarError("migrarPrevias", e, "aviso"); }
          db.close();
        };
        q.onerror = () => { registrarError("migrarPrevias", q.error, "aviso"); db.close(); };
      } catch (e) { registrarError("migrarPrevias", e, "aviso"); db.close(); }
    };
  } catch (e) { registrarError("migrarPrevias", e, "aviso"); }
}
/* Registro de errores escrito por esa versión ({f, m, s, v}) */
function errNormalizar(L){
  return L.map(x => x && !x.msg && x.m ? {k:`anterior|${x.m}`, f:x.f || new Date().toISOString(), mod:String(x.s || "versión anterior").slice(0, 60), nivel:"error", msg:errLimpiarTexto(x.m), stack:"", n:1} : x).filter(x => x && x.f && x.msg);
}

/* ---------- Autodiagnóstico (no modifica los datos) ---------- */
async function autodiagnostico(){
  const out = [], ok = (b, t, d) => out.push({b, t, d});
  try { localStorage.setItem("planificador-prueba", "1"); ok(localStorage.getItem("planificador-prueba") === "1", "Guardado en el navegador", "Lapacho puede guardar y leer datos."); localStorage.removeItem("planificador-prueba"); }
  catch (e) { ok(false, "Guardado en el navegador", "El navegador no deja guardar: puede estar lleno o en modo privado."); }
  const malos = [];
  Object.entries(datosLocales()).forEach(([k, v]) => { try { JSON.parse(v); } catch (e) { malos.push(k.replace("planificador-", "")); } });
  ok(!malos.length, "Integridad de los datos", malos.length ? `Hay datos dañados en: ${malos.join(", ")}. Recuperá una copia de seguridad.` : "Todos los registros se leen sin errores.");
  try { await fotosTodas(); ok(true, "Base de fotos", "Las fotos se pueden leer."); } catch (e) { ok(false, "Base de fotos", "No se pudo abrir la base de fotos de este navegador."); }
  try { const e = await idbGet("espejo", "datos"); ok(true, "Copia interna", e && e.fecha ? `Última copia interna: ${new Date(e.fecha).toLocaleString("es-AR", {dateStyle:"short", timeStyle:"short"})}.` : "Todavía no hay copia interna: se guarda sola al minuto de usar Lapacho."); }
  catch (e) { ok(false, "Copia interna", "El navegador no permite la copia interna (IndexedDB)."); }
  try {
    const muestra = JSON.stringify({prueba:"áéíóú ñ 25 °C · σ = F/A"}), pass = "prueba-lapacho";
    const sal = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await derivarClaveResp(pass, sal, 100000);
    const ct = new Uint8Array(await crypto.subtle.encrypt({name:"AES-GCM", iv, additionalData:RESP_AAD}, key, new TextEncoder().encode(muestra)));
    const o = {kdf:{nombre:"PBKDF2", hash:"SHA-256", iteraciones:100000, sal:B64.de(sal)}, cifra:{nombre:"AES-GCM", bits:256, iv:B64.de(iv)}, datos_cifrados:B64.de(ct)};
    let rechaza = false; try { await descifrarRespaldo(o, "otra-clave"); } catch (e) { rechaza = true; }
    ok((await descifrarRespaldo(o, pass)) === muestra && rechaza, "Copias protegidas", "El cifrado funciona y una contraseña equivocada se rechaza.");
  } catch (e) { ok(false, "Copias protegidas", "Este navegador no permite cifrar copias (abrí Lapacho desde https o desde el archivo descargado)."); }
  try {
    const c = await armarContenidoRespaldo(false), txt = JSON.stringify(c), v = validarContenidoResp(JSON.parse(txt));
    ok(v.ok, "Copia de seguridad", v.ok ? `Una copia de ahora tendría ${tamLegible(txt.length)} de datos.` : v.motivo);
  } catch (e) { ok(false, "Copia de seguridad", "No se pudo armar una copia de prueba."); }
  const pdfIn = !!(window.jspdf || window.jsPDF || document.getElementById("jspdf-lib"));
  ok(pdfIn || navigator.onLine, "Descarga en PDF", pdfIn ? "La librería de PDF está disponible." : navigator.onLine ? "Se descarga al pedir el primer PDF." : "Sin internet y sin la librería de PDF: usá Word o «Imprimir».");
  ok(true, "Conexión", navigator.onLine ? (esAppInstalada() ? "Hay conexión. La aplicación instalada también funciona sin internet." : "Hay conexión. Para usar Lapacho sin internet, descargalo desde «Ajustes › Usar sin internet».") : "Sin conexión: funcionan la planificación, Mi curso, Word y las copias.");
  const L = $("dg-auto"); if (L) L.innerHTML = out.map(x => `<li class="${x.b ? "dg-ok" : "dg-mal"}"><b>${x.b ? "✓" : "✕"} ${esc(x.t)}</b><span>${esc(x.d)}</span></li>`).join("");
  if (out.some(x => !x.b)) registrarError("autodiagnóstico", "Fallas: " + out.filter(x => !x.b).map(x => x.t).join(", "), "aviso");
  return out;
}
async function renderDiag(){
  await renderDiagBase();
  const P = $("diag-panel"); if (!P || $("dg-auto")) return;
  P.insertAdjacentHTML("afterbegin", `<section class="resp-card dg-auto-card"><h3>Autodiagnóstico</h3><p class="hint">Comprueba el guardado, la integridad de los datos, la base de fotos, la copia interna, el cifrado de las copias y la descarga en PDF. No modifica tus datos.</p><div><button type="button" class="btn btn-sm btn-primary" data-dg="auto">Revisar ahora</button></div><ul class="ac-diag" id="dg-auto" aria-live="polite"></ul></section>`);
}

function init371(){
  try { const p = $("aj-gris"); if (p){ p.checked = !!leerPref().impGris; p.addEventListener("change", e => prefSet("impGris", e.target.checked)); } } catch (e) { registrarError("init371.gris", e); }
  try { const b = $("btn-coher"); if (b) b.addEventListener("click", abrirCoherencia); } catch (e) { registrarError("init371.coher", e); }
  try { $("coh-res").addEventListener("click", e => { const b = e.target.closest("[data-goto-coh]"); if (!b) return; cerrarDialogo("coher"); irPlanSiDesk(); irACampo(b.dataset.gotoCoh); }); } catch (e) { registrarError("init371.coher2", e); }
  try { $("diag").addEventListener("click", e => { const b = e.target.closest('[data-dg="auto"]'); if (!b) return; b.disabled = true; autodiagnostico().finally(() => { b.disabled = false; }); }); } catch (e) { registrarError("init371.diag", e); }
  window.addEventListener("pagehide", () => { try { if (saveTimer){ clearTimeout(saveTimer); save(); } } catch (e) { logSilencioso(e); } });
  setTimeout(migrarPreviasLegado, 2500);
}

/* ---------- Google Drive: nunca reemplazar en silencio un archivo que cambió en Drive ---------- */
/* Si el archivo en Drive se modificó desde otro lugar después de la última subida de este dispositivo,
   no se toca: lo de este dispositivo se sube como un archivo aparte y se avisa. */
async function gdSubirSeguro(nombre, mime, datos, carpeta, ref){
  if (ref && ref.id && ref.mod){
    let m = null;
    try { m = await gdJson(`${GD_API}/files/${ref.id}?fields=id,modifiedTime,trashed`); }
    catch (e) { if (!/404|not found/i.test(e.message)) throw e; }
    if (m && !m.trashed && m.modifiedTime && m.modifiedTime !== ref.mod){
      const alt = nombre.replace(/(\.[a-z0-9]+)$/i, ` (desde este dispositivo, ${hoyIso()})$1`);
      const r = await gdSubir(alt, mime, datos, carpeta, null);
      GD.conflictos = (GD.conflictos || []).concat(nombre);
      registrarError("drive.conflicto", `«${nombre}» cambió en Drive; se subió aparte`, "aviso");
      return r;
    }
  }
  return gdSubir(nombre, mime, datos, carpeta, ref && ref.id);
}
function gdAvisarConflictos(){
  const l = GD.conflictos || []; GD.conflictos = [];
  if (l.length) toast(`En Drive, ${l.length === 1 ? `«${l[0]}» cambió` : `${l.length} archivos cambiaron`} desde otro lugar. No se reemplazó nada: lo de este dispositivo quedó en un archivo aparte, con la fecha de hoy.`);
}

