/* ---------- Rótulo del docente según el contexto ---------- */
/* Con docente co-formador se trata de una residencia: «Docente practicante». Si no, «Docente». */
function rotuloDocente(){ return val("coformador") ? "Docente practicante" : "Docente"; }

/* ---------- Saberes: géneros y temas habituales que el diseño nombra de forma general ---------- */
const SABER_ALIAS = [
  [/\b(cuento|cuentos|policial|policiales|fantastic|ciencia ficcion|leyenda|leyendas|mito|mitos|fabula|fabulas|novela|novelas|relato|relatos|microrrelato|terror|realista|maravillos)/, "narrativa literatura relato textos literarios lectura"],
  [/\b(poesia|poema|poemas|verso|versos|soneto|copla|coplas|rima|haiku)/, "poesia literatura textos literarios lectura"],
  [/\b(teatro|teatral|dramatic|obra de teatro|dialogo teatral)/, "teatro literatura textos literarios"],
  [/\b(noticia|noticias|cronica|cronicas|entrevista|periodis)/, "periodisticos textos lectura"],
  [/\b(argument|opinion|debate|tesis|editorial|resena)/, "argumentativos argumentacion discursos"],
  [/\b(informe|monografia|exposit|explicativ|divulgacion|enciclopedi)/, "expositivos textos"],
  [/\b(carta|cartas|nota formal|solicitud|curriculum)/, "produccion escrita"],
  [/\b(ortografia|tilde|tildes|acentuacion|puntuacion|coma|comas)/, "ortografia gramatica"],
  [/\b(sustantivo|adjetivo|verbo|verbos|adverbio|pronombre|morfolog|clases de palabras)/, "morfologia gramatica"],
  [/\b(oracion|sujeto|predicado|sintaxis|subordinad|coordinad)/, "sintaxis oracion gramatica"],
  [/\b(exposicion oral|oralidad|debate oral|entrevista oral)/, "oral oralidad"],
  [/\b(cohesion|conectores|referencia|sinonimo)/, "cohesion coherencia"]
];
function aliasSaberes(tema){
  const t = norm(tema || ""), extra = [];
  SABER_ALIAS.forEach(([re, w]) => { if (re.test(t)) extra.push(w); });
  return extra.join(" ");
}
function autoSaberes(lista, tema){
  const r = autoSaberesBase(lista, tema);
  if (r.length) return r;
  const ex = aliasSaberes(tema);
  return ex ? autoSaberesBase(lista, `${tema} ${ex}`) : r;
}

