function lenAntDe(terms){
  /* primero el tema; los saberes solo desempatan o sirven si el tema no coincide con nada */
  const tema = terms.slice(0, 1), resto = terms.slice(1);
  const a = LEN_ANT.map(x => ({x, s:puntajePalabras(tema, x.k) * (x.gen ? 5 : 10) + puntajePalabras(resto, x.k)})).filter(x => x.s > 0).sort((a, b) => b.s - a.s)[0];
  return a ? a.x : null;
}

/* ---------- Planificación de clase: Química, Biología y Lengua ---------- */
function mejorarClase(o, ctx){
  o = mejorarClaseBase(o, ctx);
  try {
    if (!o || state.modo !== "clase") return o;
    const C = ctxClase(ctx, itemsLista(o.contenidos || ""));
    if (!C) return o;
    const punto = x => /»$/.test(x) ? x : lbPunto(x);
    if (C.area === "cn" && ctx.materia !== "fisica" && C.antic && C.antic.exp){
      const des = itemsLista(o.desarrollo || "");
      if (!des.some(d => /^Experiencia:/i.test(d))){
        des[0] = `Experiencia: ${C.antic.exp}. Antes de hacerla, cada grupo anota qué espera que pase; después lo compara con lo observado`;
        o.desarrollo = toList(des.map(contraer).map(punto));
      }
    }
    if (C.area === "lengua"){
      const F = lenAntDe([ctx.tema || "", ...C.terms]);
      if (F){
        const ini = itemsLista(o.inicio || "");
        ini[0] = `Se lee en voz alta este fragmento, escrito para la clase: ${lbComillas(F.f)} Se pregunta: ${F.q}`;
        if (ini.length > 1) ini[1] = "Las respuestas se anotan en el pizarrón como anticipaciones, para retomarlas después de leer el texto completo";
        o.inicio = toList(ini.map(contraer).map(punto));
      }
    }
    /* Que cada contenido tenga una actividad y que los objetivos de argumentación tengan su momento */
    if (["mat", "cs", "lengua"].includes(C.area)){
      const des = itemsLista(o.desarrollo || ""), actTxt = norm([o.inicio, des.join("\n"), o.cierre].join("\n"));
      const conts = itemsLista(o.contenidos || "").filter(x => !esProced(x));
      const falta = conts.filter(c => { const k = palabrasClave(c); return k.length && !k.some(x => actTxt.includes(x)); });
      const objs = norm([o.objgen || val("objgen"), o.objetivos || val("objetivos")].join(" "));
      const add = [];
      if (falta.length){
        const T2 = taLista(falta.slice(0, 3).map(x => lcFirst(sinPunto(x))));
        if (C.area === "lengua") add.push(`Leen el texto completo y analizan ${T2}: quién narra o quién habla, qué recursos usa y cómo se organiza`);
        else if (C.area === "mat") add.push(`Se sistematiza en el pizarrón ${T2} a partir de las estrategias de los grupos, con el vocabulario y la notación correspondientes`);
        else add.push(`Se sistematiza en un cuadro ${T2}, con las causas, los actores y las consecuencias que surgen de las fuentes`);
      }
      if (/(argument|justifiqu|justificar|fundament)/.test(objs) && !/(argument|justific|fundament|debate|defiend)/.test(actTxt)) add.push(C.area === "mat" ? "En la puesta en común, cada grupo justifica su procedimiento y lo compara con el de otro grupo" : "Debaten en pequeños grupos y argumentan su postura con información del texto o de las fuentes");
      if (add.length){ des.splice(Math.max(1, des.length - 1), 0, ...add); o.desarrollo = toList(des.map(contraer).map(punto)); }
    }
  } catch (e) { registrarError("mejorarClase", e, "aviso"); }
  return o;
}
function mejorarExtra(o, ctx, t, items, crit){
  o = mejorarExtraBase(o, ctx, t, items, crit);
  try {
    if (!o || !o.ficha || LB_AREA(ctx.materia) !== "lengua") return o;
    const F = lenAntDe([ctx.tema || "", ...(items || [])]);
    if (!F) return o;
    const L = o.ficha.split("\n");
    L[0] = `Leé este fragmento: ${lbComillas(F.f)} ${F.q}`;
    o.ficha = L.join("\n");
  } catch (e) { registrarError("mejorarExtra", e, "aviso"); }
  return o;
}

/* ---------- Libretos en PDF: páginas a dos columnas ---------- */
/* Busca un corte vertical entre el 35 % y el 65 % del ancho que casi ningún texto cruce y que tenga
   renglones a los dos lados a la misma altura. Si lo encuentra, lee primero la columna izquierda y
   después la derecha; los títulos que ocupan todo el ancho quedan en su lugar. */
function lbCorteColumnas(its, ancho){
  const T = its.filter(i => i.s.trim() && i.w > 0);
  if (!ancho || T.length < 12) return null;
  let mejor = null, min = Infinity;
  for (let c = ancho * 0.35; c <= ancho * 0.65; c += ancho / 120){
    const n = T.filter(i => i.x < c - 2 && i.x + i.w > c + 2).length;
    if (n < min){ min = n; mejor = c; }
  }
  /* renglones con texto a los dos lados del corte, a la misma altura */
  const filas = {};
  T.forEach(i => { const k = Math.round(i.y / 3), f = filas[k] = filas[k] || {iz:[], de:[], cruza:false};
    if (i.x < mejor - 2 && i.x + i.w > mejor + 2) f.cruza = true; else (i.x + i.w / 2 < mejor ? f.iz : f.de).push(i.s.trim()); });
  const F = Object.values(filas), dos = F.filter(f => !f.cruza && f.iz.length && f.de.length), cruzan = F.filter(f => f.cruza).length;
  if (dos.length < 6 || cruzan >= dos.length) return null;
  /* las tablas tienen celdas cortas; las columnas de texto, renglones largos */
  const prom = k => dos.reduce((a, f) => a + f[k].join(" ").length, 0) / dos.length;
  return prom("iz") >= 18 && prom("de") >= 18 ? mejor : null;
}
function lbFilasPagina(tc, ancho){
  const its = [];
  tc.items.forEach(it => {
    if (!it.str) return;
    const y = it.transform[5], x = it.transform[4], h = Math.abs(it.transform[3]) || it.height || 0;
    its.push({x, y, s:it.str, h, w:it.width || 0, b:/bold|black|heavy|semibold/i.test(it.fontName || "") || /bold|black|heavy/i.test(((tc.styles || {})[it.fontName] || {}).fontFamily || "")});
  });
  const agrupar = L => {
    const filas = [];
    L.forEach(i => { let f = filas.find(r => Math.abs(r.y - i.y) < Math.max(2, i.h * 0.45)); if (!f){ f = {y:i.y, it:[]}; filas.push(f); } f.it.push(i); });
    return filas.sort((a, b) => b.y - a.y);
  };
  const corte = lbCorteColumnas(its, ancho);
  if (corte == null) return agrupar(its);
  const cruza = i => i.x < corte - 2 && i.x + i.w > corte + 2;
  const out = []; let izq = [], der = [];
  const volcar = () => { out.push(...agrupar(izq), ...agrupar(der)); izq = []; der = []; };
  agrupar(its).forEach(f => {
    if (f.it.some(cruza)){ volcar(); out.push(f); }
    else f.it.forEach(i => (i.x + i.w / 2 < corte ? izq : der).push(i));
  });
  volcar();
  return out;
}

/* ---------- Lectura de fotos sin conexión (aplicación instalada) ---------- */
/* El paquete de Android trae Tesseract y el modelo en español en la carpeta ocr/. Si están, se usan
   esos archivos y la lectura funciona sin internet; si no, se descargan como antes. */
let OCR_LOCAL = null;
async function ocrLocal(){
  if (OCR_LOCAL !== null) return OCR_LOCAL;
  OCR_LOCAL = false;
  if (!/^https?:$/.test(location.protocol)) return false;
  try { const r = await fetch("ocr/tesseract.min.js"); OCR_LOCAL = r.ok && /javascript/.test(r.headers.get("content-type") || "javascript"); }
  catch (e) { logSilencioso(e); }
  return OCR_LOCAL;
}
async function rutasTesseract(){
  if (await ocrLocal()){
    const base = new URL("ocr/", location.href).href;
    return {script:base + "tesseract.min.js", workerPath:base + "worker.min.js", corePath:base + "core", langPath:base + "lang"};
  }
  return {script:TESS_URL, workerPath:TESS_WORKER, corePath:TESS_CORE, langPath:TESS_LANG};
}

