/* ---------- Menú lateral: íconos y búsqueda de herramientas ---------- */
function mejorarSidenav(){
  const S = $("sidenav"); if (!S || S.dataset.v39) return;
  S.dataset.v39 = "1";
  const mapa = {"inicio":"inicio", "plan":"plan", "btn-curso":"curso", "btn-lib":"carpeta", "btn-ayuda":"ayuda"};
  S.querySelectorAll(".sn-p, [data-proxy='btn-ayuda']").forEach(b => { const k = mapa[b.dataset.dnav || b.dataset.proxy]; if (k && !b.querySelector("svg")) b.insertAdjacentHTML("afterbegin", ico(k)); });
  S.querySelectorAll(".sn-d > summary").forEach(s => { const k = /carrera/i.test(s.textContent) ? "carrera" : "herr"; if (!s.querySelector("svg")) s.insertAdjacentHTML("afterbegin", ico(k)); });
  const nav = S.querySelector("nav");
  if (nav) nav.insertAdjacentHTML("beforebegin", `<div class="sn-busca" role="search"><label class="sr-only" for="sn-q">Buscar una herramienta</label>${ico("buscar")}<input id="sn-q" type="search" placeholder="Buscar herramienta" autocomplete="off"><p class="sr-only" id="sn-q-est" aria-live="polite"></p></div>`);
  const q = $("sn-q");
  q.addEventListener("input", () => filtrarHerramientas(S, q.value, $("sn-q-est")));
  q.addEventListener("keydown", e => {
    if (e.key === "Enter"){ const b = [...S.querySelectorAll("nav .sn-i")].find(x => !x.hidden); if (b){ e.preventDefault(); b.click(); q.value = ""; filtrarHerramientas(S, "", $("sn-q-est")); } }
    if (e.key === "Escape"){ q.value = ""; filtrarHerramientas(S, "", $("sn-q-est")); }
  });
  /* estado del guardado, visible en la computadora */
  const pie = S.querySelector(".sn-pie");
  if (pie && !$("sn-guardado")) pie.insertAdjacentHTML("beforebegin", `<p class="sn-guardado" id="sn-guardado" aria-live="polite"></p>`);
}
function filtrarHerramientasV45(cont, texto, est){
  const t = norm(texto || "").trim();
  let n = 0;
  cont.querySelectorAll(".sn-i, .hoja-i").forEach(b => { const ok = !t || norm(b.textContent).includes(t); b.hidden = !ok; if (ok && t) n++; });
  cont.querySelectorAll(".sn-g, .hoja-g").forEach(g => { g.hidden = !!t; });
  cont.querySelectorAll(".sn-d").forEach(d => { if (t) d.open = true; });
  if (est) est.textContent = t ? (n ? `${n} ${n === 1 ? "herramienta encontrada" : "herramientas encontradas"}. Enter abre la primera.` : "No hay herramientas con ese nombre.") : "";
}
