/* ---------- Estado del guardado en la cabecera de escritorio ---------- */
function espejarEstado(){
  const st = $("status"); if (!st) return;
  const copiar = () => {
    const t = st.textContent || "", G = $("sn-guardado"), H = $("sec-guardado");
    const mal = /Sin guardado|no se guardan|Solo lectura/i.test(t);
    [G, H].forEach(el => { if (el){ el.textContent = t; el.classList.toggle("mal", mal); } });
  };
  new MutationObserver(copiar).observe(st, {childList:true, characterData:true, subtree:true});
  const sm = document.querySelector(".sec-ctx");
  if (sm && !$("sec-guardado")) sm.insertAdjacentHTML("beforeend", `<span class="sec-guardado" id="sec-guardado" aria-hidden="true"></span>`);
  copiar();
}

