/* ---------- Formulario: campos necesarios, validación y progreso ---------- */
const NECESARIOS = {materia:"Elegí el espacio curricular.", anio:"Elegí el año.", tema:"Escribí el tema para que Lapacho arme la planificación."};
function marcarNecesarios(){
  Object.keys(NECESARIOS).forEach(id => {
    const el = $(id); if (!el || el.dataset.req) return;
    el.dataset.req = "1"; el.setAttribute("aria-required", "true");
    const lb = document.querySelector(`label[for="${id}"]`);
    if (lb && !lb.querySelector(".req")) lb.insertAdjacentHTML("beforeend", ` <span class="req">necesario</span>`);
    const err = document.createElement("p"); err.className = "f-err"; err.id = "err-" + id; err.hidden = true; err.setAttribute("role", "alert");
    el.insertAdjacentElement("afterend", err);
    el.setAttribute("aria-describedby", [el.getAttribute("aria-describedby"), err.id].filter(Boolean).join(" "));
    const validar = () => { const mal = !String(el.value || "").trim(); el.setAttribute("aria-invalid", String(mal)); err.hidden = !mal; err.textContent = mal ? NECESARIOS[id] : ""; };
    el.addEventListener("blur", validar);
    el.addEventListener("change", validar);
    el.addEventListener("input", () => { if (el.getAttribute("aria-invalid") === "true") validar(); });
  });
}
function progresoFormularioV63(){
  const secs = [...document.querySelectorAll("#form-secs details.sec.esen")].filter(d => !d.dataset.solo || d.dataset.solo.split(/\s+/).includes(state.modo || "clase"));
  if (!secs.length) return;
  const ok = secs.filter(d => { const h = d.querySelector(".sum-hint"); return !h || !h.textContent.trim(); }).length;
  let bar = $("prog-form");
  if (!bar){
    const ref = $("form-secs"); if (!ref) return;
    ref.insertAdjacentHTML("beforebegin", `<div class="prog-form" id="prog-form"><div class="pf-top"><span id="pf-txt"></span><button type="button" class="linkbtn" data-proxy="btn-coher">Revisar la coherencia</button></div><div class="pf-bar" role="progressbar" aria-labelledby="pf-txt" aria-valuemin="0"><span></span></div></div>`);
    bar = $("prog-form");
  }
  const pb = bar.querySelector(".pf-bar");
  pb.setAttribute("aria-valuemax", String(secs.length)); pb.setAttribute("aria-valuenow", String(ok));
  pb.querySelector("span").style.width = `${Math.round(ok / secs.length * 100)}%`;
  $("pf-txt").textContent = ok === secs.length ? `Las ${secs.length} secciones esenciales están completas` : `${ok} de ${secs.length} secciones esenciales completas`;
}

/* ---------- Revisión de la coherencia, ampliada ---------- */
const VAGO_A = {comprender:"explicar", comprendan:"expliquen", comprenda:"explique", conocer:"identificar", conozcan:"identifiquen", conozca:"identifique",
  saber:"describir", sepan:"describan", sepa:"describa", entender:"explicar", entiendan:"expliquen", entienda:"explique", aprender:"aplicar", aprendan:"apliquen", aprenda:"aplique",
  valorar:"argumentar sobre", valoren:"argumenten sobre", valore:"argumente sobre", apreciar:"reconocer", aprecien:"reconozcan", aprecie:"reconozca", internalizar:"aplicar", internalicen:"apliquen"};
const RECURSO_COMUN = /^(pizarr|fibron|tiza|marcador|carpeta|cuaderno|hoja|lapiz|lapice|birome|util|aula|banco)/;
/* Solo se controlan los recursos puntuales (simulaciones, videos, enlaces, materiales con nombre propio); los útiles y materiales de siempre no */
const RECURSO_ESPECIFICO = /(simula|phet|video|https?:|«|aplicaci|software|juego|pelicula|documental|cortometraje|podcast|cancion|laboratorio virtual)/;
/* Palabras de los criterios transversales (participación, revisión, comunicación), que no dependen del tema */
const CRIT_GENERICO = /^(estudi|alumno|correc|adecua|pertin|claram|utiliz|partic|trabaj|grupal|respet|compro|revisa|mejora|produc|devolu|consig|entreg|tiempo|propia|palabr|vocabu|especi|fundam|comuni|expres|escrit|oralme|respon|colabo|organi|presen|autono|activi|tareas|cumpli|interp|respue|explic|resuel|resolu|identi|recono|analiz|aplica|descri|compar|calcul|justif|argume|relaci|establ|formul|regist|observ|proble|situac|concep|conten|ejerci|ejempl|cotidi|import|distin|difere|propie|caract|interv|seleci|selecc|estrat|proced|result|razona|valida|apropi|lengua|matema|cienti|fisica|quimic|biolog)/;
function palabrasClave(t){ return norm(t).replace(/[^a-zñ0-9\s]/g, " ").split(/\s+/).filter(x => x.length >= 6 && !VACIAS.has(x)).map(x => x.slice(0, 6)); }
function revisarCoherenciaV60(){
  const R = revisarCoherenciaBase(), A = (n, t, id, fix) => R.av.push({n, t, id, fix});
  try {
    const act = norm(textoActividades()), ev = norm(textoEvaluacion());
    const objs = norm([val("objgen"), val("objetivos")].join("\n"));
    /* sugerencias aplicables para los verbos que no se pueden observar */
    R.av.forEach(a => {
      const m = /«(.+?)» usa «(.+?)»/.exec(a.t); if (!m || a.fix) return;
      const vago = m[2], alt = VAGO_A[norm(vago)]; if (!alt) return;
      const linea = itemsLista(val(a.id)).find(l => new RegExp("(^|\\s)" + norm(vago) + "(\\s|$)").test(norm(l)));
      if (linea) a.fix = {id:a.id, linea, de:vago, a:alt};
    });
    /* contenidos sin actividad */
    const cont = itemsLista(val("contenidos")).filter(x => !esProced(x));
    if (act.trim()){
      const sinAct = cont.filter(c => { const k = palabrasClave(c); return k.length && !k.some(x => act.includes(x)); });
      if (sinAct.length) A("medio", sinAct.length === 1 ? `El contenido «${recorte(sinAct[0])}» no aparece en ninguna actividad. Sumá una consigna que lo trabaje o sacalo de esta planificación.` : `Estos contenidos no aparecen en ninguna actividad: ${sinAct.slice(0, 5).map(c => `«${recorte(c)}»`).join(", ")}${sinAct.length > 5 ? " y otros" : ""}. Sumá consignas que los trabajen o dejá solo los que vas a enseñar en esta clase.`, "contenidos");
    }
    /* criterios que evalúan algo que no se enseñó */
    const crit = itemsLista(val("criterios"));
    if (act.trim()) crit.forEach(c => { const k = palabrasClave(c).filter(x => !CRIT_GENERICO.test(x)); if (k.length && !k.some(x => act.includes(x) || objs.includes(x) || norm(val("contenidos")).includes(x))) A("medio", `El criterio «${recorte(c)}» evalúa algo que no aparece en los objetivos, los contenidos ni las actividades.`, "criterios"); });
    /* criterios vagos */
    crit.forEach(c => { if (/^(la |el |buena |su )?(participacion|predisposicion|interes|actitud|compromiso|prolijidad|presentacion prolija|cumplimiento|esfuerzo)\b/.test(norm(c)) && !/(cuando|al |explica|resuelve|argumenta|identifica|registra|propone|formula)/.test(norm(c))) A("info", `«${recorte(c)}» es un criterio difícil de observar. Conviene decir qué tiene que hacer el estudiante para mostrarlo (por ejemplo, «aporta una explicación con evidencia en la puesta en común»).`, "criterios"); });
    /* evidencias de aprendizaje */
    if (act.trim() && !/(entreg|present|resuelv|resolu|registr|informe|ticket|ficha|producc|escrib|elabor|expon|explic|dibuj|grafic|esquema|mapa)/.test(act + " " + ev)) A("medio", "No se ve qué producen los estudiantes para mostrar lo aprendido (una resolución, un registro, un texto, un esquema, un ticket de salida). Sin evidencia no hay qué evaluar.", "cierre");
    /* recursos que no se usan */
    if (act.trim()) itemsLista(val("recursos")).filter(r => RECURSO_ESPECIFICO.test(norm(r))).forEach(r => { const k = palabrasClave(r).filter(x => !RECURSO_COMUN.test(x) && !/^(simula|digita|interac|virtua)/.test(x)); if (k.length && !k.some(x => act.includes(x))) A("info", `El recurso «${recorte(r)}» figura en la lista pero ninguna actividad dice cuándo se usa.`, "recursos"); });
    /* secuencia: evaluación de cierre */
    const actSec = norm(ALL_IDS.filter(id => /^sc\d+_[tae]$/.test(id)).map(val).join("\n"));
    if (state.modo === "secuencia" && !val("sumativa").trim() && !/(evaluac|prueba|integrador|sumativ)/.test(actSec)) A("alto", "La secuencia no tiene una evaluación de cierre: falta la evaluación sumativa o una actividad integradora en la última clase.", "sumativa");
    /* diversidad: barreras y apoyos, no etiquetas */
    const div = norm(["adecuaciones", "apoyo", "general", "avanzada"].map(val).join("\n"));
    if (/(\btea\b|tdah|discapacidad|sindrome|dislexia|diagnostic|autis)/.test(div) && !/(barrera|apoyo|ajuste|anticip|accesib|alternativ|tiempo|organiz)/.test(div)) A("info", "En atención a la diversidad aparece una etiqueta o un diagnóstico, pero no qué barreras hay ni qué apoyos se prevén. Describí barreras y apoyos concretos; los objetivos no se reducen solo por la etiqueta: esa decisión es del equipo docente, con el estudiante y su familia.", "adecuaciones");
    /* diagnóstico y conocimientos previos */
    if (state.modo === "clase" && act.trim() && !/(previ|anticip|que creen|que saben|diagnost|hipotes)/.test(act + " " + norm(val("diagnostica")))) A("info", "No se recuperan los conocimientos previos. Una pregunta o una situación para anticipar al inicio ayuda a saber de dónde parte el grupo.", "inicio");
  } catch (e) { registrarError("revisarCoherencia", e, "aviso"); }
  return R;
}
function abrirCoherenciaV43(){
  const {av, mapa, ev} = revisarCoherencia();
  const orden = {alto:0, medio:1, info:2}, nom = {alto:"Importante", medio:"Conviene revisar", info:"Sugerencia"};
  av.sort((a, b) => orden[a.n] - orden[b.n]);
  const n = {alto:av.filter(a => a.n === "alto").length, medio:av.filter(a => a.n === "medio").length, info:av.filter(a => a.n === "info").length};
  const nota = `<p class="hint coh-origen">${ico("check")}Revisión automática con reglas fijas de Lapacho (no usa inteligencia artificial). Son avisos para pensar la planificación: vos decidís qué cambiar.</p>`;
  const resumen = av.length ? `<p class="coh-res-t">${[n.alto ? `${n.alto} importante${n.alto > 1 ? "s" : ""}` : "", n.medio ? `${n.medio} para revisar` : "", n.info ? `${n.info} ${n.info > 1 ? "sugerencias" : "sugerencia"}` : ""].filter(Boolean).join(" · ")}</p>` : "";
  const lista = av.length ? `<ul class="coh-l">${av.map((a, i) => `<li class="coh-${a.n}"><span class="coh-n">${nom[a.n]}</span><span>${a.rot ? criChip(a.rot) : ""}${esc(a.t)}</span><span class="coh-acc"><button type="button" class="linkbtn" data-goto-coh="${esc(a.id)}">Ir al campo</button>${a.fix ? `<button type="button" class="btn btn-sm" data-coh-fix="${i}">Usar «${esc(a.fix.a)}» en lugar de «${esc(a.fix.de)}»</button>` : ""}</span></li>`).join("")}</ul>` : `<p class="coh-ok">No se encontraron contradicciones ni vacíos. Igual conviene leer la planificación completa: la revisión es automática y no reemplaza tu criterio.</p>`;
  const tabla = mapa.length ? `<h3 class="coh-h">Cada objetivo y su evidencia</h3><div class="d-table-wrap" tabindex="0" role="region" aria-label="Tabla, se desplaza hacia los costados"><table class="d-table coh-t"><thead><tr><th scope="col">Objetivo</th><th scope="col">¿Hay actividad?</th><th scope="col">¿Se evalúa?</th></tr></thead><tbody>${mapa.map(m => `<tr><td>${esc(m.o)}</td><td>${m.enAct ? "Sí" : "<b>No se encontró</b>"}</td><td>${!ev ? "<b>Falta la evaluación</b>" : m.enEv ? "Sí" : "No se menciona"}</td></tr>`).join("")}</tbody></table></div>` : "";
  COH_ULT = av;
  $("coh-res").innerHTML = nota + resumen + lista + tabla;
  if (!$("coher").open) abrirDialogo("coher");
}
let COH_ULT = [];
function aplicarFixCoherencia(i){
  const a = COH_ULT[+i]; if (!a || !a.fix) return;
  const el = $(a.fix.id); if (!el) return;
  const antes = el.value, re = new RegExp("(^|[^\\p{L}])(" + a.fix.de.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")(?=[^\\p{L}]|$)", "iu");
  const L = antes.split("\n"), k = L.findIndex(l => l.includes(a.fix.linea.slice(0, 20)) && re.test(l));
  if (k < 0){ toast("No encontré esa frase en el campo: puede que ya la hayas cambiado."); return; }
  L[k] = L[k].replace(re, (m, pre, v) => pre + (v[0] === v[0].toUpperCase() ? a.fix.a[0].toUpperCase() + a.fix.a.slice(1) : a.fix.a));
  el.value = L.join("\n");
  el.dispatchEvent(new Event("input", {bubbles:true}));
  toast(`Cambiado: ahora dice «${a.fix.a}».`, {label:"Deshacer", fn:() => { el.value = antes; el.dispatchEvent(new Event("input", {bubbles:true})); if ($("coher").open) abrirCoherencia(); }});
  abrirCoherencia();
}
/* Aviso discreto junto al documento */
function cohMini(){
  const pend = $("pend"); if (!pend) return;
  let b = $("coh-mini");
  if (!b){ pend.insertAdjacentHTML("afterend", `<button type="button" class="coh-mini" id="coh-mini" hidden></button>`); b = $("coh-mini"); b.addEventListener("click", abrirCoherencia); }
  if (!val("tema") || state.example){ b.hidden = true; return; }
  const av = revisarCoherencia().av, imp = av.filter(a => a.n !== "info").length;
  b.hidden = !av.length;
  b.textContent = imp ? `Revisión didáctica: ${imp} ${imp === 1 ? "aviso" : "avisos"}` : `Revisión didáctica: ${av.length} ${av.length === 1 ? "sugerencia" : "sugerencias"}`;
  b.classList.toggle("hay", imp > 0);
}

/* ---------- Contenidos de una clase: los del saber que corresponde al tema ---------- */
function contenidosDesde(saberes, tema){
  if ((state.modo || "clase") !== "clase" || !tema || !saberes || !saberes.length) return contenidosDesdeBase(saberes, tema);
  /* Para una clase: solo lo que el tema comparte con el saber (dos palabras si el tema tiene dos o más);
     si no coincide nada, el tema solo, sin sumar contenidos de otros temas */
  const tw = temaWords(tema), aw = temaWords(aliasSaberes(tema)).filter(w => !/^(texto|lectu|liter|grama|escri|produ)/.test(w)), min = Math.min(2, tw.length || 1);
  const items = [...new Set(saberes.flatMap(l => itemsLista(contenidosDesdeBase([l], ""))))];
  let hits = items.filter(x => score(x, tw) >= min);
  if (!hits.length && aw.length) hits = items.filter(x => score(x, aw) > 0).slice(0, 2);
  const cubre = hits.some(x => tw.length && tw.every(w => norm(x).includes(w)));
  return toList([...new Set([...(cubre ? [] : [cap(tema)]), ...hits])].slice(0, 5));
}

/* ---------- Saberes: origen claro ---------- */
function notaOrigenSaberes(){
  const h = $("saberes-hint"); if (!h) return;
  const an = +val("anio");
  let o = $("saberes-origen");
  if (!o){ h.insertAdjacentHTML("afterend", `<p class="hint saberes-origen" id="saberes-origen"></p>`); o = $("saberes-origen"); }
  o.textContent = !val("materia") || !an ? "" : an >= 10
    ? "Origen: propuesta orientativa de Lapacho basada en los NAP. No es un texto oficial: ajustala al diseño de tu orientación."
    : "Origen: síntesis de los saberes del diseño curricular de Tucumán cargada en Lapacho. No es el texto oficial: compará con el documento vigente de tu escuela antes de entregar.";
}

/* ---------- Notas: cómo se calcula y qué falta ---------- */
function explicarNota(){
  const box = document.querySelector("#cur-panel .notas-t"); if (!box || $("nota-explica")) return;
  const c = cursoSel(); if (!c) return;
  const p = CUR.per, evs = evalsDe(c, p), g = condCfgC(c), r = (c.escala || {}).redondeo || "entero";
  const al = alumnosActivos(c), faltan = [];
  al.forEach(a => { const sin = evs.filter(e => notaEval(c, a.id, e.id) == null).length; if (evs.length && sin) faltan.push([a, sin]); });
  const wrap = box.closest(".seg-wrap");
  const txt = `La nota del período es el promedio de las notas cargadas en ese período. Una evaluación sin nota no cuenta como cero: no entra en el promedio.${g.usar ? ` Después se suma o resta el ajuste por conducta (${fmtN(g.mas)} por cada registro positivo y ${fmtN(g.menos)} por cada negativo, hasta ${fmtN(g.tope)} en total); se puede desactivar en la configuración del curso.` : ""} El resultado se redondea ${r === "medio" ? "al medio punto" : r === "decimal" ? "a un decimal" : "al entero"} y queda entre 1 y ${maxC(c)}. Si escribís la nota del período a mano, vale la tuya; con recuperatorio, se toma la mayor.`;
  wrap.insertAdjacentHTML("afterend", `<details class="nota-explica" id="nota-explica"><summary>Cómo se calcula la nota${faltan.length ? ` · ${faltan.length} ${faltan.length === 1 ? "estudiante tiene" : "estudiantes tienen"} evaluaciones sin nota` : ""}</summary><p>${esc(txt)}</p>${faltan.length ? `<p><b>Sin nota todavía:</b> ${esc(faltan.slice(0, 12).map(([a, n]) => `${a.n} (${n})`).join(", "))}${faltan.length > 12 ? "…" : ""}. Lapacho no completa esas notas: cargalas o dejá constancia de por qué faltan.</p>` : ""}</details>`);
}

/* ---------- Protección de los datos ---------- */
const DATOS_VER_KEY = "planificador-version-datos";
let SOLO_LECTURA = false;
function numVersion(s){ const m = /(\d+)(?:\.(\d+))?/.exec(String(s || "")); return m ? +m[1] + (+m[2] || 0) / 100 : 0; }
function revisarVersionDatos(){
  let r = null;
  try { r = JSON.parse(localStorage.getItem(DATOS_VER_KEY) || "null"); } catch (e) { logSilencioso(e); }
  if (r && numVersion(r.app) > numVersion(LAPACHO_VERSION)){
    activarSoloLectura(r.app);
    return;
  }
  try { localStorage.setItem(DATOS_VER_KEY, JSON.stringify({app:LAPACHO_VERSION, esquema:2, fecha:new Date().toISOString()})); } catch (e) { logSilencioso(e); }
}
/* Si los datos los guardó una versión más nueva, esta versión no escribe nada hasta que la docente lo decida */
function activarSoloLectura(vNueva){
  SOLO_LECTURA = true; congelado = true;
  const orig = Storage.prototype.setItem;
  Storage.prototype.setItem = function(k, v){
    if (SOLO_LECTURA && this === window.localStorage && /^planificador-/.test(String(k)) && k !== "planificador-errores-v1") return;
    return orig.call(this, k, v);
  };
  const st = $("status"); if (st) st.textContent = "Solo lectura: los cambios no se guardan";
  document.body.insertAdjacentHTML("afterbegin", `<div class="aviso-version" id="aviso-version" role="alert"><p><b>Estos datos los guardó una versión más nueva de Lapacho (${esc(String(vNueva))}).</b> Esta es la ${esc(LAPACHO_VERSION)}. Para no perder información, Lapacho no guarda cambios desde esta versión. Abrí la versión más nueva o descargá una copia de seguridad antes de seguir.</p><div><button type="button" class="btn btn-sm" id="av-copia">Descargar una copia</button><button type="button" class="btn btn-sm" id="av-seguir">Guardar igual con esta versión</button></div></div>`);
  $("av-copia").addEventListener("click", () => { const b = $("btn-respaldo"); if (b) b.click(); });
  $("av-seguir").addEventListener("click", () => {
    if (!window.confirm("Si guardás con esta versión, los datos nuevos que esta versión no conoce pueden perderse. ¿Seguimos?")) return;
    SOLO_LECTURA = false; congelado = false;
    try { localStorage.setItem(DATOS_VER_KEY, JSON.stringify({app:LAPACHO_VERSION, esquema:2, fecha:new Date().toISOString()})); } catch (e) { logSilencioso(e); }
    $("aviso-version").remove(); save();
  });
}
/* Antes de cerrar: se guarda lo pendiente y, si no se pudo guardar, el navegador avisa */
function avisoAlCerrar(){
  window.addEventListener("beforeunload", e => {
    try { if (saveTimer && !congelado){ clearTimeout(saveTimer); save(); } } catch (err) { logSilencioso(err); }
    const t = ($("status") || {}).textContent || "";
    if (SOLO_LECTURA || /Sin guardado/i.test(t)){ e.preventDefault(); e.returnValue = ""; }
  });
}

function init39(){
  try { revisarVersionDatos(); } catch (e) { registrarError("init39.version", e); }
  try { mejorarSidenav(); } catch (e) { registrarError("init39.sidenav", e); }
  try { espejarEstado(); } catch (e) { registrarError("init39.estado", e); }
  try { bindPanel39(); renderPanel(); } catch (e) { registrarError("init39.panel", e); }
  try { marcarNecesarios(); } catch (e) { registrarError("init39.necesarios", e); }
  try { avisoAlCerrar(); } catch (e) { registrarError("init39.cerrar", e); }
  try {
    $("coh-res").addEventListener("click", e => { const b = e.target.closest("[data-coh-fix]"); if (b) aplicarFixCoherencia(b.dataset.cohFix); });
  } catch (e) { registrarError("init39.coher", e); }
  let tmr = null;
  const tarde = () => { clearTimeout(tmr); tmr = setTimeout(() => { try { progresoFormulario(); cohMini(); notaOrigenSaberes(); } catch (err) { registrarError("init39.tarde", err, "aviso"); } }, 500); };
  document.addEventListener("input", tarde); document.addEventListener("change", tarde); document.addEventListener("click", tarde);
  tarde();
  try {
    const cp = $("cur-panel");
    if (cp) new MutationObserver(() => { try { explicarNota(); } catch (err) { registrarError("explicarNota", err, "aviso"); } }).observe(cp, {childList:true, subtree:true});
  } catch (e) { registrarError("init39.notas", e); }
}

