      <div class="f"><label for="gp-base">Ordenar por</label><select id="gp-base"><option value="per"${GP.base === "per" ? " selected" : ""}>Nota del período (${esc(perCorto(c, periodoActual(c)))})</option><option value="anual"${GP.base === "anual" ? " selected" : ""}>Promedio de los períodos</option>${evs.map(e => `<option value="ev:${esc(e.id)}"${GP.base === "ev:" + e.id ? " selected" : ""}>${esc(e.t || "Evaluación")}</option>`).join("")}${crs.map(x => `<option value="${esc(x.v)}"${GP.base === x.v ? " selected" : ""}>Criterio · ${esc(x.t)}</option>`).join("")}</select></div>
