    const fila = (a, esAc) => {
      const ac = esAc ? (g.pares.find(p => p.de.id === a.id) || {a:[]}).a : [], rol = R[a.id] || ((GP.est === "rompe" || GP.est === "cabezas") ? pc[a.id] : "");
      return `<li><button type="button" class="gp-al${GP.sel && GP.sel.id === a.id ? " on" : ""}" data-gpal="${esc(a.id)}" aria-pressed="${!!(GP.sel && GP.sel.id === a.id)}">${esc(gpNombre(a.n))}</button>${GP.ver ? ` <span class="gp-nota">${esc(gpNum(a.nota))}</span>` : ""}${rol ? ` <span class="gp-rol">${esc(rol)}</span>` : ""}${AP.has(a.id) ? ` <span class="gp-rol gp-apoyo">Apoyo</span>` : ""}${ac.length ? `<small>${GP.est === "tutoria" || GP.est === "pds" ? "Empieza explicando a" : "Acompaña a"} ${esc(ac.map(x => gpNombre(x.n).split(" ")[0]).join(" y "))}</small>` : ""}</li>`;
    };
