  const cs = cdatos().cursos || [];
  if (!cs.some(c => c.id === AUS.cid)){ const m = cs.find(c => norm(c.curso || "") === norm(val("curso") || "")) || cursoSel(); AUS.cid = m ? m.id : ""; }
  const c = ausCursoDe(AUS.cid);
