  const F = ausFuente(c), L = ausTemas(F.P);
  if (AUS.desde == null || (AUS.desde !== "otro" && +AUS.desde >= L.length)) AUS.desde = L.length ? ausDesdeDefault(c, L) : "otro";
  const minAuto = ausMinDe(c, AUS.fecha, F.P);
