    if (id === "aus-fecha"){ AUS.fecha = e.target.value || hoyIso(); AUS.min = 0; renderAus(); return; }
    if (id === "aus-desde"){ AUS.desde = e.target.value === "otro" ? "otro" : +e.target.value; renderAus(); return; }
