/* Formatos que sirven para cualquier tema */
const MU_GEN = [
  {id:"gen-voto", gen:true, t:"Votá antes de ver", que:"El visitante lee una pregunta sobre el tema y elige una respuesta poniendo una ficha en una de cuatro cajas. Después, el stand explica la respuesta y muestra cómo votó la gente.", mat:"Cartel con la pregunta y las opciones, cuatro cajas o sobres, fichas de cartón.", ojo:""},
  {id:"gen-antes", gen:true, t:"Antes pensaba, ahora pienso", que:"El visitante escribe en un papel qué pensaba del tema al llegar y, después de la explicación, qué piensa ahora. Las respuestas se pegan en un mural.", mat:"Papelitos autoadhesivos o tarjetas, un afiche dividido en dos columnas.", ojo:""},
  {id:"gen-desafio", gen:true, t:"Desafío de un minuto", que:"El stand propone una pregunta o un problema corto que el visitante resuelve en un minuto con la ayuda de los estudiantes; quien lo logra firma el «muro de los que resolvieron».", mat:"Tarjetas con desafíos, reloj de arena o cronómetro, afiche para firmar.", ojo:""},
  {id:"gen-qr", gen:true, t:"El proceso en video", que:"El visitante escanea un QR y mira, en un minuto, cómo trabajó el curso: las pruebas, los errores y lo que aprendieron.", mat:"QR impreso grande, el video subido a la cuenta de la escuela.", ojo:"Solo con la autorización de imagen de quienes aparecen."},
  {id:"gen-guiado", gen:true, t:"Recorrido guiado de tres minutos", que:"Un estudiante guía al visitante por los tres paneles del stand: qué preguntamos, qué hicimos y qué descubrimos, y le deja una pregunta para pensar.", mat:"Tres paneles numerados, guion de la explicación.", ojo:""},
  {id:"gen-libro", gen:true, t:"Libro de visitas con preguntas", que:"El visitante deja una pregunta o un comentario sobre el tema. El curso las responde en clase después de la muestra.", mat:"Cuaderno o afiche, lapiceras.", ojo:""}
];
const muKey = s => norm(`${s.curso}|${s.tema}`);
function muIdeasDe(s){
  const tema = String(s.tema || "").trim(), out = [];
  if (tema){
    out.push(...bancoOrden(MU_ACT, [tema]));
    const p = pcDe([tema], "", 1)[0];
    if (p) out.push({id:"pc-" + p.id, t:"Votá antes de ver", que:`El visitante elige una respuesta con una ficha antes de la explicación: «${p.q}» ${p.op.map((o, j) => `${PC_L[j]}) ${sinPunto(o)}`).join("; ")}. Después el stand muestra por qué la correcta es la ${PC_L[p.ok]} y qué idea lleva a elegir las otras.`, mat:"Cartel con la pregunta y las opciones, cuatro cajas o sobres, fichas de cartón.", ojo:""});
  }
  const ya = new Set(out.map(x => x.id));
  out.push(...MU_GEN.filter(g => !ya.has(g.id) && !(g.id === "gen-voto" && out.some(x => /^pc-/.test(x.id)))));
  return out;
}
const muIdeaPorId = (s, id) => muIdeasDe(s).find(x => x.id === id) || MU_ACT.find(x => x.id === id) || MU_GEN.find(x => x.id === id) || null;
function muElegidas(s){ const m = muLeer(); return ((m.act || {})[muKey(s)] || []).map(id => muIdeaPorId(s, id)).filter(Boolean); }
/* Las que se muestran: primero las elegidas y después tres sugerencias (que rotan con «Ver otras») */
function muMostradas(s){
  const m = muLeer(), k = muKey(s), todas = muIdeasDe(s), ele = (m.act || {})[k] || [], rot = +((m.rot || {})[k] || 0);
  const resto = todas.filter(x => !ele.includes(x.id));
  const n = resto.length, ini = n ? (rot * 3) % n : 0;
  const sug = n <= 3 ? resto : [...resto, ...resto].slice(ini, ini + 3);
  return {ele:todas.filter(x => ele.includes(x.id)), sug, hayMas:n > 3, tema:!!String(s.tema || "").trim()};
}
const muTxtIdea = x => `${x.t}. ${x.que}\nMateriales: ${sinPunto(x.mat)}.${x.ojo ? `\nCuidado: ${sinPunto(x.ojo)}.` : ""}`;
function htmlIdeasMu(){
  const S = muStands(muDatos().stands);
  if (!S.length) return `<p class="hint">Cargá los stands con su tema y acá vas a ver actividades para que los visitantes participen, elegidas según el tema.</p>`;
  return S.map((s, i) => {
    const M = muMostradas(s), k = muKey(s);
    const card = (x, ele) => `<li class="mu-idea${ele ? " ele" : ""}"><div><b>${esc(x.t)}</b><p>${esc(x.que)}</p><small><b>Materiales:</b> ${esc(x.mat)}${x.ojo ? ` <b>Cuidado:</b> ${esc(x.ojo)}` : ""}</small></div><button type="button" class="btn btn-sm" data-muact="${esc(k)}" data-muid="${esc(x.id)}" aria-pressed="${ele}">${ele ? "Elegida" : "Elegir"}</button></li>`;
    return `<div class="mu-st"><h4>${esc(s.curso || `Stand ${i + 1}`)}${s.tema ? `: ${esc(s.tema)}` : ""}</h4>${M.tema ? "" : `<p class="hint">Sin tema: estas son ideas que sirven para cualquier stand. Escribí el tema después del curso para ver actividades del tema.</p>`}
      <ul class="mu-ideas-l">${M.ele.map(x => card(x, true)).join("")}${M.sug.map(x => card(x, false)).join("")}</ul>${M.hayMas ? `<button type="button" class="linkbtn" data-murot="${esc(k)}">Ver otras ideas</button>` : ""}</div>`;
  }).join("");
}
function renderIdeasMu(){ const b = $("mu-ideas-b"); if (b) b.innerHTML = htmlIdeasMu(); }
function renderMuestraV46(){
  renderMuestraBase();
  const docs = document.querySelector("#mu-panel .mu-docs");
  if (docs && !$("mu-ideas")) docs.insertAdjacentHTML("beforebegin", `<details class="mu-ideas" id="mu-ideas" open><summary><h3 class="lic-h" id="mu-ideas-h">Actividades para los visitantes</h3></summary><p class="hint">Según el tema de cada stand: que el visitante haga algo, no solo que mire. Todas cumplen las reglas de seguridad de la muestra. Elegí hasta dos por stand: van a la ficha del stand y al proyecto.</p><div id="mu-ideas-b" aria-live="polite"></div></details>`);
  renderIdeasMu();
}
function muPrev(){ muPrevBase(); renderIdeasMu(); }
function modeloMuestra48(doc){
  const M = modeloMuestraBase(doc), S = muStands(muDatos().stands);
  if (doc === "fichas" && S.length){
    M.secs.forEach((sec, i) => {
      const s = S[i]; if (!s || !sec.sub) return;
      const ele = muElegidas(s), sug = ele.length ? [] : muMostradas(s).sug.slice(0, 1);
      const L = ele.length ? ele : sug;
      const j = sec.sub.findIndex(x => x.h === "Qué vamos a mostrar");
      if (L.length && j >= 0) sec.sub.splice(j + 1, 0, {h:ele.length ? "Actividad para los visitantes" : "Actividad para los visitantes (sugerida)", body:L.map(muTxtIdea).join("\n\n")});
    });
  }
  if (doc === "proyecto" && S.length){
    const j = M.secs.findIndex(x => x.h === "Organización de los espacios");
    const rows = S.map((s, i) => { const L = muElegidas(s); return [`${i + 1}. ${[s.curso, s.tema].filter(Boolean).join(": ")}`, L.length ? L.map(x => x.t).join("; ") : "A definir"]; });
    if (j >= 0) M.secs.splice(j + 1, 0, {h:"Actividades para los visitantes", lead:"En cada stand, los visitantes participan de una actividad breve. Todas cumplen las reglas de seguridad de la muestra.", table:{head:["Stand", "Actividad"], rows, w:[4200, 4870]}, tableOnly:true});
  }
  return M;
}
function bindIdeasMu(){
  const D = $("muestra"); if (!D || D.dataset.okIdeas) return; D.dataset.okIdeas = "1";
  D.addEventListener("click", e => {
    const a = e.target.closest("[data-muact]");
    if (a){
      const m = muLeer(), k = a.dataset.muact, id = a.dataset.muid;
      m.act = m.act || {}; const L = (m.act[k] || []).filter(x => x !== id);
      if (L.length === (m.act[k] || []).length){ if (L.length >= 2){ toast("Elegí hasta dos actividades por stand."); return; } L.push(id); }
      m.act[k] = L; if (!L.length) delete m.act[k];
      muGuardar(m); muPrev(); return;
    }
    const r = e.target.closest("[data-murot]");
    if (r){ const m = muLeer(); m.rot = m.rot || {}; m.rot[r.dataset.murot] = (+(m.rot[r.dataset.murot] || 0)) + 1; muGuardar(m); renderIdeasMu(); }
  });
}

/* ---------- Capacitaciones: cómo se suma tu puntaje ----------
   INFoD: Res. 1741/5 (MEd), 19/06/2026. Decreto 3128/5 (MEd), 2025: los cursos de menos de 40 horas
   (desde 2004) y los dictados fuera de la provincia no suman, salvo INFoD. Valores anteriores a abril
   de 2024: lo publicado sobre el Anexo X (0,15 con evaluación, 0,10 sin evaluación, 0,20 si lo dictó el docente).
   El Anexo X completo no está publicado: lo demás queda «a confirmar». */
const PTC_TIPOS = [["eval", "Con evaluación"], ["sin", "Sin evaluación"], ["dicte", "Lo dicté yo"]];
const PTC_AMB = [["", "Dónde se dictó"], ["tuc", "Tucumán"], ["infod", "INFoD (nacional)"], ["fuera", "Otra provincia"]];
const ptcFmt = n => (Math.round(n * 100) / 100).toFixed(2).replace(".", ",");
const numPts = v => { const n = parseFloat(String(v == null ? "" : v).replace(",", ".")); return isFinite(n) && n > 0 ? n : null; };
function ptcEsInfod(x){ return x.ambito === "infod" || (!x.ambito && (/infod|instituto nacional de formaci|red\.infd/i.test(`${x.nombre || ""} ${x.inst || ""} ${x.norma || ""}`) || /1741/.test(x.norma || ""))); }
function ptcEvalV43(x){
  const horas = +x.horas || 0, man = numPts(x.puntaje), infod = ptcEsInfod(x);
  if (man != null) return {estado:"suma", pts:man, como:"El puntaje que cargaste (del certificado o de la resolución)."};
  if (infod){
    if (!horas) return {estado:"conf", pts:null, como:"Es de INFoD: suma según las horas. Cargá las horas en Mi legajo."};
    if (horas < 20) return {estado:"no", pts:0, como:`Tiene ${horas} horas: los cursos de INFoD suman desde 20 horas (Res. 1741/5 MEd).`};
    return {estado:"suma", pts:puntosInfod(horas), como:`INFoD, ${horas} horas: ${ptcFmt(puntosInfod(horas))} puntos según la Res. 1741/5 (MEd) de 2026.`};
  }
  if (x.ambito === "fuera") return {estado:"no", pts:0, como:"Dictado fuera de Tucumán: desde el Decreto 3128 no suma, salvo los cursos de INFoD."};
  if (horas && horas < 40 && (!x.fecha || x.fecha >= "2004-01-01")) return {estado:"no", pts:0, como:`Tiene ${horas} horas: desde el Decreto 3128 no suman los cursos de menos de 40 horas hechos desde 2004, salvo los de INFoD.`};
  if (!String(x.norma || "").trim()) return {estado:"conf", pts:null, como:"Falta la resolución del Ministerio de Educación de Tucumán: sin resolución no suma. Si la tiene, cargala en Mi legajo."};
  if (x.fecha && x.fecha < "2024-04-01"){
    const p = x.tipo === "dicte" ? 0.2 : x.tipo === "sin" ? 0.1 : 0.15;
    return {estado:"est", pts:p, como:`Estimado: ${ptcFmt(p)} puntos, según lo publicado sobre el Anexo X del Decreto 3128 para certificaciones anteriores a abril de 2024 (0,15 con evaluación, 0,10 sin evaluación y 0,20 si lo dictaste). Confirmalo en la Junta.`};
  }
  return {estado:"conf", pts:null, como:"Suma, pero el valor depende del Anexo X del Decreto 3128, que no está publicado. Si el certificado o la resolución dice el puntaje, cargalo en Mi legajo."};
}
function ptcCursos(){
  const L = leerLista(LEG_KEY, {}), out = (L.cursos || []).map(x => ({...x, origen:"legajo"}));
  (L.capInt || []).filter(x => x.estado === "aprobado" && !x.legajo).forEach(x => out.push({id:x.id, nombre:x.n, inst:x.inst, horas:x.horas, norma:x.res, puntaje:x.pts != null ? x.pts : "", ambito:x.infod ? "infod" : x.fuera ? "fuera" : "", origen:"mios"}));
  return out;
}
function ptcResumenV43(){
  const C = ptcCursos().map(x => ({x, e:ptcEval(x)}));
  const r = {C, conf:0, est:0, nConf:0, nNo:0};
  C.forEach(({e}) => { if (e.estado === "suma") r.conf += e.pts; else if (e.estado === "est") r.est += e.pts; else if (e.estado === "conf") r.nConf++; else r.nNo++; });
  r.conf = Math.round(r.conf * 100) / 100; r.est = Math.round(r.est * 100) / 100; r.total = Math.round((r.conf + r.est) * 100) / 100;
  return r;
}
const PTC_ET_V43 = {suma:["Suma", "si"], est:["Estimado", "est"], conf:["A confirmar", "conf"], no:["No suma", "no"]};
function htmlPuntajeCursosV43(){
  if (leerPref().pin && !pinOk) return `<p class="hint">Tus capacitaciones están en Mi legajo, protegido con PIN.</p><div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-ptc="pin">Desbloquear con el PIN</button></div>`;
  const R = ptcResumen();
  const reglas = `<details class="cur-sub"><summary>Cómo se suma</summary><ul class="cp-reglas">
      <li>Cada curso aprobado suma una sola vez, y se suman todos los que cumplen los requisitos. El puntaje vale en el nivel o la modalidad en la que concursás.</li>
      <li><b>INFoD</b> (Res. 1741/5 MEd, junio de 2026): según las horas, de 1,50 puntos (20 a 35 horas) a 6,30 (especialización de 400 horas).</li>
      <li><b>Otros cursos:</b> necesitan resolución del Ministerio de Educación de Tucumán. Desde el Decreto 3128 (2025) no suman los de menos de 40 horas hechos desde 2004 ni los dictados fuera de la provincia.</li>
      <li><b>Certificaciones anteriores a abril de 2024:</b> según lo publicado sobre el Anexo X, 0,15 puntos con evaluación, 0,10 sin evaluación y 0,20 si lo dictaste vos. Se muestran como estimados.</li>
      <li>El valor de los demás cursos está en el Anexo X del Decreto 3128, que no está publicado en internet: si el certificado o la resolución dice el puntaje, cargalo en Mi legajo y se usa ese.</li>
      <li>Si el Anexo X fija un tope para las capacitaciones, la Junta lo aplica al sumar. Este total es solo de capacitaciones: tu puntaje docente también suma el título, la antigüedad, el concepto y otros antecedentes.</li>
      <li>Cuando se publique el padrón provisorio, compará tu puntaje en el período de tacha y, si no coincide, reclamá ante la Junta de Clasificación con tus certificados.</li></ul></details>`;
  if (!R.C.length) return `<p class="hint">Cargá tus capacitaciones en «Mi legajo › Capacitaciones» (nombre, institución, horas, fecha y resolución) y acá ves cuánto suma cada una y el total.</p><div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-ptc="legajo">Cargar en Mi legajo</button></div>${reglas}`;
  return `<div class="ptc-tot"><div><b>${ptcFmt(R.conf)}</b><span>puntos que suman</span></div>${R.est ? `<div><b>${ptcFmt(R.est)}</b><span>estimados</span></div>` : ""}<div><b>${R.nConf}</b><span>a confirmar</span></div><div><b>${R.nNo}</b><span>no suman</span></div></div>
    <p class="hint">${R.est ? `Con los estimados, ${ptcFmt(R.total)} puntos por capacitaciones. ` : ""}Para que el cálculo sea más preciso, indicá dónde se dictó cada curso y si tuvo evaluación.</p>
    <ul class="cp-list ptc-l">${R.C.map(({x, e}) => `<li class="cp-item"><div class="cp-top"><b>${esc(x.nombre || "Curso sin nombre")}</b><span class="cp-pts ${PTC_ET[e.estado][1]}">${e.pts != null && e.estado !== "no" ? `${ptcFmt(e.pts)} · ` : ""}${PTC_ET[e.estado][0]}</span></div>
        <div class="cp-meta">${esc([x.inst, x.horas ? `${x.horas} horas` : "", x.fecha ? fechaCortaIso(x.fecha) : "", x.norma ? `Res. ${x.norma}` : ""].filter(Boolean).join(" · "))}</div>
        <p class="ptc-como">${esc(e.como)}</p>
        ${x.origen === "legajo" ? `<div class="ptc-sel"><label class="sr-only" for="ptca-${esc(x.id)}">Dónde se dictó</label><select id="ptca-${esc(x.id)}" data-ptcamb="${esc(x.id)}">${PTC_AMB.map(([v, l]) => `<option value="${v}"${(x.ambito || "") === v ? " selected" : ""}>${l}</option>`).join("")}</select>
          <label class="sr-only" for="ptct-${esc(x.id)}">Tipo de certificación</label><select id="ptct-${esc(x.id)}" data-ptctipo="${esc(x.id)}">${PTC_TIPOS.map(([v, l]) => `<option value="${v}"${(x.tipo || "eval") === v ? " selected" : ""}>${l}</option>`).join("")}</select></div>` : `<p class="hint">Está en «Mis cursos»: pasalo a Mi legajo para completar los datos.</p>`}</li>`).join("")}</ul>
    <div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-ptc="word">Descargar para la Junta</button><button type="button" class="btn btn-sm" data-ptc="legajo">Editar en Mi legajo</button></div>
    ${reglas}
    <p class="hint">Fuentes: Res. 1741/5 (MEd) de 2026 según Monterizos (28/07/2026); Decreto 3128/5 (MEd) de 2025 según La Izquierda Diario (30/10/2025); Guía para el desempeño profesional del docente 2023. Revisado el 31/10/2026. Es una estimación: el puntaje oficial lo fija la Junta de Clasificación.</p>`;
}
function modeloPuntajeCursosV43(){
  const R = ptcResumen();
  return {inst:val("docente") || "Documento personal", titulo:"Mis capacitaciones y su puntaje", subtitulo:"Para revisar el puntaje en la Junta de Clasificación", faltaSub:"", datos:[["Docente", val("docente")], ["Fecha", fechaCortaIso(hoyIso())]].filter(d => d[1]),
    secs:[
      {h:"Detalle", tableOnly:true, table:{head:["Curso", "Institución", "Horas", "Resolución", "Fecha", "Puntos", "Estado"], w:[2500, 1500, 700, 1100, 1100, 800, 1370], rows:R.C.map(({x, e}) => [x.nombre || "", x.inst || "", x.horas ? String(x.horas) : "", x.norma || "", x.fecha ? fechaCortaIso(x.fecha) : "", e.pts != null && e.estado !== "no" ? ptcFmt(e.pts) : "", PTC_ET[e.estado][0]])}},
      {h:"Total", body:`Puntos que suman: ${ptcFmt(R.conf)}.${R.est ? `\nEstimados (certificaciones anteriores a abril de 2024): ${ptcFmt(R.est)}.\nTotal con los estimados: ${ptcFmt(R.total)}.` : ""}\nCursos a confirmar: ${R.nConf}. Cursos que no suman: ${R.nNo}.`},
      {h:"Cómo se calculó cada uno", body:R.C.map(({x, e}) => `- ${x.nombre || "Curso"}: ${e.como}`).join("\n")},
      {h:"Para tener en cuenta", body:"- Es una estimación hecha con lo publicado; el puntaje oficial lo fija la Junta de Clasificación con la grilla vigente (Decreto 3128/5 MEd y su Anexo X).\n- Llevá los certificados originales y sus copias. En el período de tacha del padrón provisorio podés revisar tu puntaje y reclamar ante la Junta si no coincide."}
    ], firmas:null};
}
function bindPuntajeCursos(){
  const D = $("capac"); if (!D || D.dataset.okPtc) return; D.dataset.okPtc = "1";
  D.addEventListener("click", async e => {
    const b = e.target.closest("[data-ptc]"); if (!b) return;
    if (b.dataset.ptc === "pin"){ if (await exigirPIN()) renderCapac(); return; }
    if (b.dataset.ptc === "word"){ bajarDoc(modeloPuntajeCursos(), `capacitaciones-y-puntaje-${hoyIso()}`, "docx", "Resumen de capacitaciones descargado."); return; }
    if (b.dataset.ptc === "legajo"){ cerrarDialogo("capac"); legTab = "cursos"; const l = $("btn-legajo"); if (l) l.click(); }
  });
  D.addEventListener("change", async e => {
    const a = e.target.closest("[data-ptcamb], [data-ptctipo]"); if (!a) return;
    if (!(await exigirPIN())) { renderCapac(); return; }
    const L = leerLista(LEG_KEY, {}), id = a.dataset.ptcamb || a.dataset.ptctipo, x = (L.cursos || []).find(y => y.id === id); if (!x) return;
    if (a.dataset.ptcamb != null) x.ambito = a.value; else x.tipo = a.value;
    guardarLista(LEG_KEY, L); renderCapac();
    const s = document.querySelector(`[${a.dataset.ptcamb != null ? "data-ptcamb" : "data-ptctipo"}="${CSS.escape(id)}"]`); if (s) s.focus();
  });
}

