/* ---------- 10. Motor pedagógico ----------
   Reglas explicables, sin IA. Cada observación dice qué se detectó, por qué puede ser un problema,
   qué revisar y una propuesta concreta. Son sugerencias didácticas, no exigencias normativas.
   Taxonomía de Bloom revisada (Anderson y Krathwohl, 2001): seis procesos cognitivos. */
const BLOOM = [
  {k:"recordar", n:"Recordar", d:"Recuperar información de la memoria.", v:"recordar reconocer identificar nombrar enumerar listar definir mencionar señalar localizar ubicar citar repetir reproducir memorizar rotular"},
  {k:"comprender", n:"Comprender", d:"Construir significado: explicar con palabras propias, dar ejemplos, comparar.", v:"explicar describir interpretar resumir parafrasear ejemplificar clasificar comparar inferir traducir reformular ilustrar caracterizar asociar"},
  {k:"aplicar", n:"Aplicar", d:"Usar un procedimiento en una situación conocida o nueva.", v:"aplicar resolver calcular usar utilizar emplear ejecutar implementar demostrar medir operar graficar representar modelizar manipular experimentar convertir"},
  {k:"analizar", n:"Analizar", d:"Descomponer en partes y ver cómo se relacionan.", v:"analizar organizar contrastar diferenciar distinguir examinar categorizar descomponer relacionar indagar investigar cuestionar detectar estructurar atribuir esquematizar"},
  {k:"evaluar", n:"Evaluar", d:"Juzgar con criterios: justificar, argumentar, verificar.", v:"evaluar justificar argumentar fundamentar valorar juzgar criticar defender verificar validar debatir decidir priorizar comprobar"},
  {k:"crear", n:"Crear", d:"Producir algo nuevo: diseñar, formular, planificar.", v:"crear diseñar elaborar producir formular planificar proponer inventar componer generar idear redactar plantear construir"}
].map((b, i) => ({...b, i, verbos:b.v.split(" ")}));
const BLOOM_IRREG = {resolver:["resuelv"], medir:["mid"], construir:["construy"], producir:["produzc"], proponer:["propong", "propus"], distinguir:["disting"], inferir:["infier", "infir"], defender:["defiend"], componer:["compong"], demostrar:["demuestr"], comprobar:["comprueb"], recordar:["recuerd"], reconocer:["reconozc"], traducir:["traduzc"], repetir:["repit"], reproducir:["reproduzc"], elegir:["elij", "elig"], seguir:["sig"], diferenciar:["diferenci"], convertir:["conviert", "convirt"], invertir:["inviert"], decidir:["decid"]};
const BLOOM_IDX = (() => {
  const out = [];
  BLOOM.forEach(b => b.verbos.forEach(v0 => {
    const v = norm(v0), st = v.replace(/(ar|er|ir)$/, ""), vs = new Set([st]);
    if (/c$/.test(st)) vs.add(st.slice(0, -1) + "qu");
    if (/g$/.test(st)) vs.add(st + "u");
    if (/z$/.test(st)) vs.add(st.slice(0, -1) + "c");
    (BLOOM_IRREG[v] || []).forEach(x => vs.add(x));
    vs.forEach(s => { if (s.length >= 3) out.push([s, b.i, v0]); });
  }));
  return out.sort((a, b) => b[0].length - a[0].length);
})();
/* Sustantivos y participios que empiezan como un verbo («cuestionario», «relación», «medida») no cuentan */
const BLOOM_NO = /(cion|ciones|sion|siones|miento|mientos|ario|arios|aria|arias|dor|dora|dores|doras|ble|bles|ivo|iva|ivos|ivas|ura|uras|encia|encias|ancia|ancias|ismo|ida|idas|ido|idos|ada|adas|ado|ados)$/;
function bloomDeVerbo(w){
  w = norm(w || "").replace(/[^a-z]/g, "");
  if (w.length < 3) return null;
  if (BLOOM_NO.test(w) && !/(ar|er|ir)$/.test(w)) return null;
  for (const [s, i, v] of BLOOM_IDX) if (w.startsWith(s) && w.length - s.length <= 6) return {i, v};
  return null;
}
function bloomLinea(l){
  const pv = primerVerbo(l), b = bloomDeVerbo(pv);
  return b ? {...b, palabra:pv} : {i:-1, palabra:pv, v:""};
}
/* Nivel más alto de una consigna: se miran las primeras palabras, donde suele estar lo que se pide */
function bloomMaxConsigna(l, n){
  const w = norm(lbSinMarca(l)).replace(/^[-•*\d.)\s¿¡"«(]+/, "").split(/[^a-zñ]+/).filter(Boolean).slice(0, n || 14);
  let m = -1; w.forEach(x => { const b = bloomDeVerbo(x); if (b && b.i > m) m = b.i; });
  return m;
}
const PED = {abierto:{}};
function pedEstado(){ if (!state.ped || typeof state.ped !== "object") state.ped = {bloom:{}, barreras:[]}; state.ped.bloom = state.ped.bloom || {}; state.ped.barreras = Array.isArray(state.ped.barreras) ? state.ped.barreras : []; return state.ped; }
const claveObj = o => norm(o).replace(/[^a-z0-9ñ ]/g, "").replace(/\s+/g, " ").trim().slice(0, 80);
function foto(){ const f = fotoV43(); f.ped = JSON.parse(JSON.stringify(pedEstado())); return f; }
function aplicarV81(saved){ const r = aplicarV43(saved); state.ped = saved && saved.ped && typeof saved.ped === "object" ? JSON.parse(JSON.stringify(saved.ped)) : {bloom:{}, barreras:[]}; return r; }
function objetivosPed(){ return [...(state.modo === "secuencia" ? itemsLista(val("objgen")).map(o => ({o, id:"objgen"})) : []), ...itemsLista(val("objetivos")).map(o => ({o, id:"objetivos"}))]; }
