const MU_ANIOS = [["7", "1.º año"], ["8", "2.º año"], ["9", "3.º año"], ["10", "4.º año"], ["11", "5.º año"], ["12", "6.º año"], ["co", "Ciclo Orientado (NAP)"]];
const muActPorId = id => MU_ACT.find(x => x.id === id) || MU_GEN.find(x => x.id === id) || null;
function renderMuEsp(){ const b = $("mu-esp-b"); if (b) b.innerHTML = htmlMuEsp(); }
function renderMuestra48(){
  renderMuestraV46();
  const ideas = $("mu-ideas");
  if (ideas && !$("mu-esp")) ideas.insertAdjacentHTML("beforebegin", `<details class="mu-ideas mu-esp" id="mu-esp"><summary><h3 class="lic-h">Muestra por materia: temas para exponer y actividades</h3></summary><div id="mu-esp-b"></div></details>`);
  renderMuEsp();
}
function bindMuEsp(){
  const D = $("muestra"); if (!D || D.dataset.okEsp) return; D.dataset.okEsp = "1";
  D.addEventListener("change", e => {
    if (e.target.id === "mu-esp-mat" || e.target.id === "mu-esp-anio"){ const m = muLeer(); m[e.target.id === "mu-esp-mat" ? "espMat" : "espAnio"] = e.target.value; muGuardar(m); renderMuEsp(); const n = $(e.target.id); if (n) n.focus(); }
  });
  D.addEventListener("click", e => {
    const b = e.target.closest("[data-muesp]");
    if (b){
      const {mat, anio} = muEspSel(), x = (MU_ESP[mat].anios[anio] || [])[+b.dataset.muesp]; if (!x) return;
      const m = muLeer(), an = (MU_ANIOS.find(y => y[0] === anio) || [])[1] || "";
      const curso = val("curso") || an;
      const linea = `${curso} | ${x.t}${m.resp || val("docente") ? ` | ${m.resp || val("docente")}` : ""}`;
      m.stands = [String(m.stands || "").trim(), linea].filter(Boolean).join("\n");
      const s = muStands(linea)[0]; m.act = m.act || {}; m.act[muKey(s)] = x.a.filter(id => muActPorId(id)).slice(0, 2);
      muGuardar(m);
      const t = $("mu-stands"); if (t) t.value = m.stands;
      muPrev(); renderMuEsp();
      toast(`Se sumó el stand «${x.t}» con sus actividades. Cambiá el curso si hace falta.`);
      return;
    }
    if (e.target.closest('[data-mu="esp-docx"]')){ const {mat} = muEspSel(); bajarDoc(modeloMuEsp(), `muestra-de-${mat}-${hoyIso()}`, "docx", `Guía de la muestra de ${MU_ESP[mat].n} descargada.`); }
  });
}
function init57(){ try { bindMuEsp(); } catch (e) { registrarError("init57", e); } }

