function bindTramites(){
  const b = $("btn-tramites"); if (b && !b.dataset.ok){ b.dataset.ok = "1"; b.addEventListener("click", () => abrirTramites()); }
  const D = $("tramites"); if (!D || D.dataset.ok) return; D.dataset.ok = "1";
  D.addEventListener("click", e => {
    const tb = e.target.closest('[data-tabs="tra"] [data-tab]'); if (tb){ TRA.tab = tb.dataset.tab; TRA.q = ""; TRA.sit = ""; renderTramites(); return; }
    const q = e.target.closest("[data-traq]"); if (q){ TRA.q = q.dataset.traq; renderTramites(); const h = $("tra-q-t"); if (h){ h.tabIndex = -1; h.focus(); } return; }
    const s = e.target.closest("[data-trasit]"); if (s){ TRA.sit = s.dataset.trasit; renderTramites(); const h = $("tra-sit-t"); if (h){ h.tabIndex = -1; h.focus(); } return; }
    const a = e.target.closest("[data-tra]"); if (!a) return;
    const acc = a.dataset.tra;
    if (acc === "volver"){ const prev = TRA.q; TRA.q = ""; renderTramites(); const v = D.querySelector(`[data-traq="${prev}"]`); if (v) v.focus(); return; }
    if (acc === "volversit"){ const prev = TRA.sit; TRA.sit = ""; renderTramites(); const v = D.querySelector(`[data-trasit="${prev}"]`); if (v) v.focus(); return; }
    if (acc === "lic"){ cerrarDialogo("tramites"); $("btn-licalc").click(); return; }
    if (acc === "capac"){ cerrarDialogo("tramites"); $("btn-capac").click(); return; }
    if (acc === "cargos"){ cerrarDialogo("tramites"); $("btn-cargos").click(); return; }
    if (acc === "bajar"){ const S = TRA_SIT.find(x => x.id === a.dataset.sit); if (S) bajarDoc(modeloTraSit(S), `tramite-${S.id}-${hoyIso()}`, "docx", "Lista descargada."); }
  });
  const upd = e => {
    const f = e.target.closest("[data-traf]");
    if (f){ TRA.v[f.dataset.traf] = f.value; const R = $("tra-res"); if (R) R.innerHTML = htmlTraResultado(); return; }
    const c = e.target.closest("[data-trachk]");
    if (c && e.type === "change"){ const p = traPref(); const k = c.dataset.trachk; p.hecho[k] = p.hecho[k] || {}; if (c.checked) p.hecho[k][c.dataset.i] = 1; else delete p.hecho[k][c.dataset.i]; prefSet("tramites", p); }
  };
  D.addEventListener("input", upd); D.addEventListener("change", upd);
}
