    if (t.dataset.sup && e.type === "change"){ const E = entLeer(); if (t.checked) E.sup[t.dataset.sup] = true; else delete E.sup[t.dataset.sup]; entGuardar(E); const c = D.querySelector(".ent-cont"); if (c) c.innerHTML = `<b>${ENT_SUP.filter(s => E.sup[s.k]).length} de ${ENT_SUP.length}</b> listos`; }
