/* ============================================================
   Versión 60: selector de estilo de vista y color de acento
   Solo pone o quita dos atributos en la raíz y guarda la elección. No toca datos ni lógica.
   ============================================================ */
const EST_KEY = "planificador-estilo-v1";
const EST_ESTILOS = [["", "Lapacho (verde)"], ["minimal", "Minimalismo funcional"], ["enterprise", "Tabular empresarial"], ["bento", "Bento analítico"], ["high-density", "Alta densidad, oscuro"]];
const EST_ACENTOS = [["", "El de la planificación"], ["blue", "Azul"], ["emerald", "Esmeralda"], ["violet", "Violeta"], ["amber", "Ámbar"]];
try { if (!CLAVES_RESPALDO.includes(EST_KEY)) CLAVES_RESPALDO.push(EST_KEY); } catch (e) { logSilencioso(e); }
function estLeer(){
  let o = {};
  try { o = JSON.parse(localStorage.getItem(EST_KEY) || "{}") || {}; } catch (e) { o = {}; }
  return {estilo:EST_ESTILOS.some(([k]) => k === o.estilo) ? o.estilo : "", acento:EST_ACENTOS.some(([k]) => k === o.acento) ? o.acento : ""};
}
function estAplicar(e){
  const r = document.documentElement;
  if (e.estilo) r.setAttribute("data-estilo", e.estilo); else r.removeAttribute("data-estilo");
  if (e.acento) r.setAttribute("data-acento", e.acento); else r.removeAttribute("data-acento");
  const a = document.getElementById("aj-estilo"), b = document.getElementById("aj-acento");
  if (a) a.value = e.estilo; if (b) b.value = e.acento;
}
function estGuardar(e){ try { localStorage.setItem(EST_KEY, JSON.stringify(e)); } catch (err) { logSilencioso(err); } }
try { estAplicar(estLeer()); } catch (e) { logSilencioso(e); }
function prepararEstilos(){
  const M = document.querySelector(".menu-aj"); if (!M || document.getElementById("aj-estilo")) return;
  const tema = [...M.querySelectorAll(".aj-row")].find(x => x.querySelector("[data-tema]")) || M.querySelector(".aj-row:last-of-type");
  const op = L => L.map(([k, n]) => `<option value="${k}">${n}</option>`).join("");
  const html = `<div class="aj-row"><label for="aj-estilo">Estilo de vista</label><select id="aj-estilo">${op(EST_ESTILOS)}</select></div>
    <div class="aj-row"><label for="aj-acento"><span class="aj-acento-m" aria-hidden="true"></span>Color de acento</label><select id="aj-acento">${op(EST_ACENTOS)}</select></div>`;
  if (tema) tema.insertAdjacentHTML("afterend", html); else M.insertAdjacentHTML("beforeend", html);
}
try { prepararEstilos(); estAplicar(estLeer()); } catch (e) { logSilencioso(e); }
function init70(){
  try {
    document.addEventListener("change", ev => {
      const t = ev.target; if (!t || (t.id !== "aj-estilo" && t.id !== "aj-acento")) return;
      const e = estLeer();
      if (t.id === "aj-estilo") e.estilo = EST_ESTILOS.some(([k]) => k === t.value) ? t.value : "";
      else e.acento = EST_ACENTOS.some(([k]) => k === t.value) ? t.value : "";
      estGuardar(e); estAplicar(e);
    });
    estAplicar(estLeer());
  } catch (e) { registrarError("init70", e, "aviso"); }
}

