function criChip(r){ const R = CRI_ROT[r]; return R ? `<span class="der-k cri-k ${R[1]}">${R[0]}</span>` : ""; }
function criFuentes(ids){ return ids.length ? `<small class="cri-f">Fuente: ${ids.map(i => `<a href="${esc(CRI_F[i][1])}" target="_blank" rel="noopener">${esc(CRI_F[i][0])}</a>`).join(" · ")}</small>` : ""; }

/* ---------- 1. Entregas y constancias › Normas ---------- */
try { if (!ENT_TABS.some(([k]) => k === "normas")) ENT_TABS.push(["normas", "Normas"]); } catch (e) { logSilencioso(e); }
try { const t = "Criterios de evaluación comunicados a los estudiantes (Taller Inicial)"; if (!ENT_TIPICAS.includes(t)) ENT_TIPICAS.splice(1, 0, t); } catch (e) { logSilencioso(e); }
try { const s = document.querySelector('[data-tabs="ent"]'); if (s && !s.querySelector('[data-tab="normas"]')) s.insertAdjacentHTML("beforeend", `<button type="button" data-tab="normas" aria-pressed="false">Normas</button>`); } catch (e) { logSilencioso(e); }
function htmlEntNormas(){
  const grupo = (r, tit, intro) => `<h3 class="ent-h">${tit}</h3><p class="hint">${intro}</p><ul class="ent-l">${CRI_NORMAS.filter(n => n.r === r).map(n => `<li class="ent-i cri-i">${criChip(n.r)}<b>${esc(n.t)}</b><p>${esc(n.d)}</p>${criFuentes(n.f)}</li>`).join("")}</ul>`;
  return `<p class="der-aviso">Lo que pudimos comprobar sobre evaluación y gestión en la secundaria de Tucumán, separado de lo que no. Lapacho no presenta como obligatorio nada que no haya leído en una fuente oficial. Revisado el ${esc(fechaCortaIso(CRI_REVISION))}.</p>
    ${grupo("norma", "Comprobado en fuente oficial", "Podés citarlo ante la dirección con la fuente que figura en cada caso.")}
    ${grupo("confirmar", "A confirmar con tu escuela", "Aparece en copias no oficiales o en la prensa, o directamente no lo encontramos. No lo des por cierto sin preguntar.")}`;
}
function renderEntregas(){
  if (ENTUI.tab !== "normas") return renderEntregasV60();
  const P = $("ent-panel"); if (!P) return;
  document.querySelectorAll('[data-tabs="ent"] [data-tab]').forEach(b => b.setAttribute("aria-pressed", String(b.dataset.tab === ENTUI.tab)));
  P.innerHTML = htmlEntNormas();
}

/* ---------- 2. Mi curso › Notas: tres calificaciones y una integradora por período ---------- */
function criEstadoPeriodo(c, p){
  const evs = evalsDe(c, p), integ = evs.some(e => /integrador/.test(norm(e.t || "")));
  const comunes = evs.length - (integ ? 1 : 0);
  return {n:evs.length, integ, ok:comunes >= 3 && integ, comunes};
}
function htmlAvisoNotas(c, p){
  const E = criEstadoPeriodo(c, p); if (E.ok) return "";
  const falta = E.comunes < 3 ? `Este período tiene ${E.comunes} ${E.comunes === 1 ? "calificación" : "calificaciones"}${E.integ ? " y la integradora" : ""}.` : "Este período ya tiene tres calificaciones, pero falta la instancia integradora.";
  return `<div class="cri-nota" role="note">${criChip("norma")}<p><b>${falta}</b> El Régimen Académico pide que la nota del trimestre salga de al menos tres calificaciones y una instancia integradora (Res. 1224/5 MEd, Anexo II, citada en el Diseño Curricular). ${E.integ ? "" : "Cuando la cargues, poné «Integradora» en el nombre para que Lapacho la reconozca. "}Es un aviso: podés cerrar el período igual.</p></div>`;
}
function htmlNotas(c){
  const h = htmlNotasV60(c);
  try {
    if (CUR.notasAnual || !alumnosActivos(c).length || !c.periodos || !c.periodos[CUR.per]) return h;
    const av = htmlAvisoNotas(c, CUR.per); if (!av) return h;
    const i = h.indexOf('<div class="seg-wrap">');
    return i > 0 ? h.slice(0, i) + av + h.slice(i) : h + av;
  } catch (e) { logSilencioso(e); return h; }
}
function avisosCriterios(){
  const hoy = hoyIso(), d = new Date(); d.setDate(d.getDate() + 10); const lim = isoDe(d), av = [];
  (cdatos().cursos || []).forEach(c => (c.periodos || []).forEach((p, k) => {
    if (!p || !p.fin || p.fin < hoy || p.fin > lim || !alumnosActivos(c).length) return;
    const E = criEstadoPeriodo(c, k); if (E.ok) return;
    av.push({f:p.fin, t:`${c.curso}: el ${nombrePeriodo(c, k)} cierra el ${fechaCortaIso(p.fin)} y tiene ${E.comunes} ${E.comunes === 1 ? "calificación" : "calificaciones"}${E.integ ? "" : ", sin integradora"}. Se piden tres y una integradora.`, act:"notas", cid:c.id});
  }));
  return av.slice(0, 2);
}
function avisosDelDia(){
  const av = avisosDelDiaV60();
  try { const m = [...avisosCriterios(), ...avisosPPI311()]; if (m.length) return [...m, ...av].slice(0, 7); } catch (e) { logSilencioso(e); }
  return av;
}

/* ---------- 3. PPI: lo que pide la Res. CFE 311/16, art. 17 ---------- */
const PPI_311 = [["fam", "Lo acordé con la familia y, si corresponde, con el estudiante"], ["equipo", "Lo trabajé con el equipo de apoyo o de orientación"], ["dc", "Los saberes se apoyan en el diseño curricular del año: no es un programa aparte"], ["claro", "Está escrito en lenguaje claro, sin siglas ni términos clínicos"]];
function htmlPPI311(p){
  const c = p.ctrl && typeof p.ctrl === "object" ? p.ctrl : {};
  return `<fieldset class="ppi-311" id="ppi-311"><legend>Antes de darlo por terminado ${criChip("norma")}</legend>
    <p class="hint">Lo que pide la Res. CFE 311/16, art. 17. No sale en el documento: es para tu control.</p>
    ${PPI_311.map(([k, t]) => `<label class="ent-chk"><input type="checkbox" data-ppi311="${k}"${c[k] === true ? " checked" : ""}><span>${esc(t)}</span></label>`).join("")}
    <div class="f ppi-311-f"><label for="ppi-311-rev">Próxima revisión del PPI</label><input type="date" id="ppi-311-rev" data-ppi311="rev" value="${esc(/^\d{4}-\d{2}-\d{2}$/.test(String(c.rev || "")) ? c.rev : "")}"></div></fieldset>`;
}
function renderPPI(){
  renderPPIV60();
  try { const p = ppiActual(), F = $("ppi-form"); if (p && F && !$("ppi-311")) F.insertAdjacentHTML("beforeend", htmlPPI311(p)); } catch (e) { logSilencioso(e); }
}
function avisosPPI311(){
  const hoy = hoyIso(), d = new Date(); d.setDate(d.getDate() + 7); const lim = isoDe(d);
  return ppiLeer().filter(p => p.ctrl && /^\d{4}-\d{2}-\d{2}$/.test(String(p.ctrl.rev || "")) && p.ctrl.rev <= lim && p.ctrl.rev >= adSuma(hoy, 0, -1)).slice(0, 2)
    .map(p => ({f:p.ctrl.rev, t:`Toca revisar un PPI${p.v.curso ? ` de ${p.v.curso}` : ""} (${fechaCortaIso(p.ctrl.rev)}).`, act:"ppi311"}));
}

/* ---------- 4. Revisar la coherencia: reglas nuevas ---------- */
function revisarCoherencia(){
  const R = revisarCoherenciaV60();
  try {
    const A = (rot, n, t, id) => R.av.push({n, t, id, rot});
    const modo = state.modo || "clase", act = norm(textoActividades()), ev = norm(textoEvaluacion()), todo = norm(ALL_IDS.map(val).join("\n"));
    const crit = itemsLista(val("criterios")), hayPlan = !!(act.trim() || ev.trim());
    if (!hayPlan && modo !== "anual") return R;
    /* Normas verificadas (Diseño Curricular de Tucumán) */
    if (modo === "anual"){
      if (val("criterios").trim() && !/(taller inicial|se comunica|se explicita|se informan?|se dan a conocer|se presentan? a los estudiantes)/.test(norm(val("criterios")))) A("norma", "info", "El Diseño Curricular (p. 19) pide explicitar a los estudiantes, en el Taller Inicial, los criterios de evaluación, calificación y acreditación. Agregá una línea que diga cuándo y cómo se los comunicás.", "criterios");
      if (!/(educacion sexual|\besi\b|ambient|memoria|derechos humanos|seminario|educacion vial|malvinas|salud)/.test(todo)) A("norma", "info", "La planificación anual no menciona ningún eje transversal. El Diseño Curricular (p. 19) prevé seminarios temáticos intensivos por trimestre: educación ambiental, salud, derechos humanos, educación sexual y memoria.", $("transv") ? "transv" : "contenidos");
    }
    if (ev.trim() && !/(devoluc|retroaliment|reajust|recuper|rehacer|reescrib|corrig|revis(an|en|ar|ion)|mejor(an|en|ar))/.test(ev + " " + act)) A("norma", "info", "No se prevé una devolución ni una actividad para quienes no lleguen. El Diseño Curricular (p. 25) pide que la evaluación incluya devoluciones que reconozcan avances y nuevas actividades para superar dificultades.", "formativa");
    if (modo === "proyecto" && Array.isArray(state.integra) && state.integra.length) A("norma", "info", "Este proyecto integra otros espacios. Según el Diseño Curricular (pp. 20 y 25), la nota de una propuesta multidisciplinar cuenta como una de las tres del trimestre en cada espacio que participa: acordá con tus colegas cómo se califica.", "aportes");
    if (/(fisic|quimic|biolog|natural)/.test(norm(val("materia"))) && modo !== "clase" && modo !== "anual" && act.trim()){
      const falta = [[/(hipotes|anticip|predic|que creen que|que pasaria)/, "una hipótesis o anticipación"], [/(medi|registr|dato|tabla|observ)/, "el registro de datos u observaciones"], [/(model|analog|esquema|represent|simula|grafic)/, "el uso de un modelo o una representación"], [/(argument|justific|fundament|debat|conclu|evidencia)/, "una instancia para argumentar con evidencia"]].filter(([re]) => !re.test(act + " " + ev)).map(x => x[1]);
      if (falta.length >= 2) A("norma", "info", `Para Ciencias Naturales el Diseño Curricular (pp. 32 a 51) propone trabajar con preguntas investigables, hipótesis, datos, modelos y argumentación. Acá no aparece: ${falta.join("; ")}.`, "desarrollo");
    }
    /* Sugerencias didácticas */
    if (modo !== "clase" && modo !== "anual" && hayPlan && !/(autoevalu|coevalu|entre pares|evaluan? (a|el trabajo de) (un|sus) compa|se evaluan entre)/.test(act + " " + ev)) A("sug", "info", "No hay una instancia de autoevaluación ni de evaluación entre pares. Son dos de las cinco estrategias de evaluación formativa de Dylan Wiliam: que los estudiantes sean recurso para sus compañeros y dueños de su aprendizaje.", "formativa");
    crit.forEach(c => { const n = norm(c);
      if (/^(-\s*)?(entrega|entregar|presenta|presentar|trae|traer|completa|completar|tiene|tener)\b.{0,40}(carpeta|trabajo|tarea|cuaderno|practico|material)/.test(n)) A("sug", "info", `«${recorte(c)}» es una tarea, no un criterio. Un criterio dice qué cualidad del trabajo valorás (por ejemplo, «explica el procedimiento con el vocabulario de la unidad»). Fuente: Brookhart; Popham.`, "criterios");
      else if (/(puntualidad|conducta|comportamiento|asistencia a clase)/.test(n)) A("sug", "info", `«${recorte(c)}» valora la conducta, no el aprendizaje. Si va a contar para la nota, decilo de manera explícita y por separado. Fuente: Anijovich; Ravela.`, "criterios");
      else if (/ y .* y |; /.test(n) && n.length > 90) A("sug", "info", `«${recorte(c)}» junta varias cualidades en un solo criterio. Separalas: cada criterio se valora por sí solo. Fuente: Brookhart.`, "criterios");
    });
    const rub = norm([val("rubrica"), val("rubrica_est")].join("\n"));
    if (rub.trim().length > 40){
      const adj = (rub.match(/\b(excelente|muy bueno|muy bien|bueno|regular|insuficiente|logrado|en proceso|no logrado|destacado|basico)\b/g) || []).length, palabras = rub.split(/\s+/).length;
      if (adj >= 4 && palabras / adj < 6) A("sug", "info", "En la rúbrica los niveles casi no cambian más que el adjetivo. Describí qué se observa en el trabajo en cada nivel, para que el estudiante sepa qué le falta. Fuente: Brookhart, How to Create and Use Rubrics.", "rubrica");
    }
    if (act.trim().length > 120 && !/(justific|argument|fundament|disen|compar|por que|formul|investig|evalu(a|ar|en) (la|el|si)|predic|model|propon|elabor(a|ar|en) (un|una) (conclusi|explicaci|hipotes))/.test(act)) A("sug", "info", "Ninguna consigna pide justificar, comparar, diseñar o argumentar. Sumá al menos una de mayor demanda cognitiva, donde no alcance con recordar o aplicar un procedimiento. Fuente: Webb (niveles de profundidad); Stein y Smith.", "desarrollo");
    if (modo === "proyecto"){
      const t = todo, falta = [];
      if (!val("pregunta").trim()) falta.push("la pregunta o el problema desafiante");
      if (!/(investig|indag|relev|entrevist|experiment|busc(an|ar|en) informacion|encuest)/.test(t)) falta.push("una indagación sostenida");
      if (!/(comunidad|barrio|escuela|familia|real|local|tucuman|vecin|municip)/.test(t)) falta.push("un vínculo con un problema real o cercano");
      if (!/(elig|eleg|decid|propon|opcion|votan|acuerdan)/.test(t)) falta.push("decisiones a cargo de los estudiantes");
      if (!/(reflexi|metacogn|que aprendimos|como trabajamos|bitacora|diario de)/.test(t)) falta.push("momentos de reflexión");
      if (!/(borrador|devoluc|critica|revis(an|en|ar|ion)|mejor(an|en|ar)|retroaliment|ensayo)/.test(t)) falta.push("crítica y revisión antes de la entrega");
      if (!val("producto").trim() || !val("difusion").trim()) falta.push("un producto que se presente a otros");
      if (falta.length) A("sug", falta.length >= 4 ? "medio" : "info", `Según el estándar de PBLWorks para el aprendizaje basado en proyectos, a este proyecto le falta: ${falta.join("; ")}.`, !val("pregunta").trim() ? "pregunta" : "producto");
    }
    if (modo !== "clase" && hayPlan){
      const d = [["dua_imp", "implicarse (intereses, elección, colaboración)"], ["dua_rep", "acceder a la información (más de un formato)"], ["dua_acc", "mostrar lo aprendido (más de un modo de expresión)"]].filter(([id]) => $(id) && !val(id).trim());
      if (d.length && d.length < 3) A("sug", "info", `Diseño Universal para el Aprendizaje (CAST, versión 3.0): falta prever opciones para ${d.map(x => x[1]).join(" y para ")}.`, d[0][0]);
    }
  } catch (e) { registrarError("revisarCoherencia61", e, "aviso"); }
  return R;
}
function init71(){
  try {
    const D = $("ppi");
    if (D) D.addEventListener("change", e => {
      const t = e.target; if (!t || !t.dataset || !t.dataset.ppi311) return;
      const l = ppiLeer(), p = l.find(x => x.id === state.ppiSel); if (!p) return;
      p.ctrl = p.ctrl && typeof p.ctrl === "object" ? p.ctrl : {};
      if (t.dataset.ppi311 === "rev") p.ctrl.rev = /^\d{4}-\d{2}-\d{2}$/.test(t.value) ? t.value : ""; else p.ctrl[t.dataset.ppi311] = !!t.checked;
      ppiGuardar(l); try { renderTuDia(); } catch (err) { logSilencioso(err); }
    });
    const T = $("tudia");
    if (T) T.addEventListener("click", e => { const x = e.target.closest('[data-tdact="ppi311"]'); if (!x) return; e.stopPropagation(); const b = $("btn-ppi"); if (b) b.click(); }, true);
  } catch (e) { registrarError("init71", e, "aviso"); }
}

