    const a = $("sn-abrir"); if (a) a.addEventListener("click", () => { lpMenuOculto(false); prefSet("menuOculto", false); const o = document.querySelector(".sn-ocultar"); if (o) o.focus(); });
    if (!document.querySelector(".sn-ocultar")) construirSidenav();
    lpMenuOculto(!!leerPref().menuOculto);
