/* ============================================================
   Versión 64: planificar por pasos, vista previa A4 y Mis planificaciones con filtros
   - Pasos: las secciones esenciales se recorren en orden, con «Anterior» y «Siguiente».
     «Una sección por vez» (pref pasoUno) cierra las demás al abrir una; de entrada está activo en celular y tablet.
   - Vista A4: reparte el documento en hojas de 210 × 297 mm con los márgenes de impresión y numera las hojas.
   - Mis planificaciones: buscador, filtros por tipo, espacio curricular y estado, y estado de cada una
     (borrador, lista, entregada) guardado aparte, sin tocar los registros que ya existen.
   ============================================================ */

/* ---------- Pasos del formulario ---------- */
function lpPasosVisibles(){
  return [...document.querySelectorAll("#form-secs details.sec.esen")].filter(d => !d.dataset.solo || d.dataset.solo.split(/\s+/).includes(state.modo || "clase"));
}
const lpSecOk = d => { const h = d.querySelector(".sum-hint"); return !h || !h.textContent.trim(); };
const lpSecTitulo = d => { const t = d.querySelector("summary .sec-t"); return t ? t.textContent.trim() : ""; };
function lpPasoUno(){ const p = leerPref().pasoUno; return p == null ? !document.querySelector(".app.nav-desk") : !!p; }
let lpPasoActual = "", lpToque = {d:null, t:0};
function lpIrPaso(id, enfocar){
  if (id === "opc"){
    const h = $("opc-head"); if (!h) return;
    if (!state.opcAbiertas){ const t = $("opc-toggle"); if (t) t.click(); }
    h.scrollIntoView({behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block:"start"});
    return;
  }
  const d = $(id); if (!d) return;
  lpPasoActual = id;
  if (!d.open) d.open = true;
  if (lpPasoUno()) document.querySelectorAll("#form-secs details.sec[open]").forEach(o => { if (o !== d) o.open = false; });
  renderPasos();
  const s = d.querySelector("summary");
  d.scrollIntoView({behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block:"start"});
  if (enfocar && s) s.focus({preventScroll:true});
}
function renderPasos(){
  const bar = $("prog-form"); if (!bar) return;
  const secs = lpPasosVisibles(); if (!secs.length) return;
  if (!secs.some(d => d.id === lpPasoActual)){ const ab = secs.find(d => d.open); lpPasoActual = ab ? ab.id : secs[0].id; }
  let cab = bar.querySelector(".pasos-cab");
  if (!cab){
    bar.insertAdjacentHTML("beforeend", `<div class="pasos-cab"><p class="pasos-txt" id="pasos-txt"></p><label class="pasos-uno"><input type="checkbox" id="pasos-uno"> Una sección por vez</label></div><ol class="pasos" id="pasos" aria-label="Pasos de la planificación"></ol>`);
    cab = bar.querySelector(".pasos-cab");
    $("pasos-uno").addEventListener("change", e => {
      prefSet("pasoUno", e.target.checked);
      if (e.target.checked){ const d = $(lpPasoActual); document.querySelectorAll("#form-secs details.sec[open]").forEach(o => { if (o !== d) o.open = false; }); if (d) d.open = true; }
      toast(e.target.checked ? "Ahora se abre una sección por vez." : "Ahora podés tener varias secciones abiertas.");
    });
  }
  $("pasos-uno").checked = lpPasoUno();
  const i = Math.max(0, secs.findIndex(d => d.id === lpPasoActual));
  $("pasos-txt").textContent = `Paso ${i + 1} de ${secs.length}: ${lpSecTitulo(secs[i])}`;
  $("pasos").innerHTML = secs.map((d, k) => {
    const ok = lpSecOk(d), cur = k === i;
    return `<li><button type="button" class="${ok ? "ok" : ""}" data-paso="${d.id}"${cur ? ' aria-current="step"' : ""} aria-label="Paso ${k + 1}: ${esc(lpSecTitulo(d))}${ok ? ", completa" : ", por completar"}"><span class="ps-n" aria-hidden="true">${ok ? "✓" : k + 1}</span><span class="ps-t">${esc(lpSecTitulo(d))}</span></button></li>`;
  }).join("") + ($("opc-head") ? `<li><button type="button" class="ps-opc" data-paso="opc" aria-label="Más opciones"><span class="ps-n" aria-hidden="true">+</span><span class="ps-t">Más opciones</span></button></li>` : "");
  secs.forEach((d, k) => {
    const body = d.querySelector(".sec-body"); if (!body) return;
    let pie = body.querySelector(":scope > .paso-pie");
    if (!pie){ pie = document.createElement("div"); pie.className = "paso-pie"; body.appendChild(pie); }
    const ant = secs[k - 1], sig = secs[k + 1];
    pie.innerHTML = (ant ? `<button type="button" class="btn btn-sm" data-paso-ir="${ant.id}">Anterior</button>` : "<span></span>") +
      (sig ? `<button type="button" class="btn btn-sm btn-primary" data-paso-ir="${sig.id}">Siguiente: ${esc(lpSecTitulo(sig))}</button>`
           : `<button type="button" class="btn btn-sm btn-primary" data-proxy="btn-ver">Listo: ver el documento</button>`);
  });
  document.querySelectorAll("#form-secs details.sec.esen").forEach(d => { if (!secs.includes(d)){ const p = d.querySelector(".sec-body > .paso-pie"); if (p) p.remove(); } });
}
function progresoFormulario(){
  progresoFormularioV63();
  try { renderPasos(); } catch (e) { registrarError("renderPasos", e, "aviso"); }
}

/* ---------- Vista previa en hoja A4 ---------- */
const LP_MM = 96 / 25.4;
const LP_A4 = {w:210, h:297, mx:16, my:18};
function lpAltoBloques(cont){
  const hijos = [...cont.children], base = cont.getBoundingClientRect();
  return hijos.map((n, k) => {
    const r = n.getBoundingClientRect(), sig = hijos[k + 1];
    return {n, h: (sig ? sig.getBoundingClientRect().top : base.bottom) - r.top};
  });
}
/* Parte una tabla o una lista larga en trozos que entren en el espacio disponible */
function lpPartir(n, libre, lleno){
  const tabla = n.tagName === "TABLE", lista = /^(UL|OL)$/.test(n.tagName);
  if (!tabla && !lista) return null;
  const filas = tabla ? [...n.querySelectorAll(":scope > tbody > tr, :scope > tr")] : [...n.children].filter(x => x.tagName === "LI");
  if (filas.length < 2) return null;
  const thead = tabla ? n.querySelector(":scope > thead") : null, hCab = thead ? thead.getBoundingClientRect().height : 0;
  const trozos = []; let act = [], usado = hCab, cupo = libre;
  filas.forEach(f => {
    const h = f.getBoundingClientRect().height;
    if (usado + h > cupo && (act.length || cupo < lleno)){ trozos.push({fs:act, h:usado}); act = []; usado = hCab; cupo = lleno; }
    act.push(f); usado += h;
  });
  if (act.length) trozos.push({fs:act, h:usado});
  let inicio = n.tagName === "OL" ? (+n.getAttribute("start") || 1) : 1;
  return trozos.map(({fs, h}) => {
    if (!fs.length) return {html:"", h:0};
    const c = n.cloneNode(false);
    if (tabla){
      [...n.children].filter(x => x.tagName === "CAPTION" || x.tagName === "COLGROUP").forEach(x => c.appendChild(x.cloneNode(true)));
      if (thead) c.appendChild(thead.cloneNode(true));
      const tb = document.createElement("tbody"); fs.forEach(f => tb.appendChild(f.cloneNode(true))); c.appendChild(tb);
    } else {
      if (n.tagName === "OL"){ c.setAttribute("start", String(inicio)); inicio += fs.length; }
      fs.forEach(f => c.appendChild(f.cloneNode(true)));
    }
    return {html:c.outerHTML, h: h + 8};
  });
}
async function lpPaginar(){
  const doc = $("doc");
  const med = document.createElement("div");
  med.className = "paper a4-med"; med.dataset.font = doc.dataset.font || "serif";
  med.style.cssText = `position:absolute;left:-20000px;top:0;width:${(LP_A4.w - 2 * LP_A4.mx) * LP_MM}px;visibility:hidden`;
  med.innerHTML = doc.innerHTML;
  med.querySelectorAll("[id]").forEach(x => x.removeAttribute("id"));
  /* la vista previa es para mirar: los atajos al formulario quedan como texto */
  med.querySelectorAll("[data-goto], .goto, button.falta").forEach(x => { ["data-goto", "tabindex", "role", "title"].forEach(a => x.removeAttribute(a)); x.classList.remove("goto"); if (x.tagName === "BUTTON"){ const sp = document.createElement("span"); sp.className = x.className; sp.innerHTML = x.innerHTML; x.replaceWith(sp); } });
  document.body.appendChild(med);
  try {
    await Promise.all([...med.querySelectorAll("img")].map(im => im.decode ? im.decode().catch(() => {}) : null));
    if (document.fonts && document.fonts.ready) await document.fonts.ready;
    const ALTO = (LP_A4.h - 2 * LP_A4.my) * LP_MM;
    const pags = [[]]; let usado = 0;
    const esTitulo = n => /^H[1-4]$/.test(n.tagName) || n.classList.contains("d-title");
    const poner = (html, h, tit) => { if (!html) return; pags[pags.length - 1].push({html, h, tit}); usado += h; };
    const nueva = () => {
      /* un título no queda solo al pie de la hoja: pasa con lo que sigue */
      const pg = pags[pags.length - 1], arrastre = [];
      while (pg.length > 1 && pg[pg.length - 1].tit) arrastre.unshift(pg.pop());
      pags.push(arrastre); usado = arrastre.reduce((a, x) => a + x.h, 0);
    };
    lpAltoBloques(med).forEach(({n, h}) => {
      const tit = esTitulo(n);
      if (usado + h <= ALTO){ poner(n.outerHTML, h, tit); return; }
      const trozos = lpPartir(n, ALTO - usado, ALTO);
      if (trozos && trozos.length > 1){
        trozos.forEach((t, k) => { if (k) nueva(); poner(t.html, t.h, false); });
        return;
      }
      if (pags[pags.length - 1].length) nueva();
      poner(n.outerHTML, h, tit);
    });
    return pags.filter(p => p.length).map(p => p.map(x => x.html));
  } finally { med.remove(); }
}
function lpDlgA4(){
  let d = $("a4dlg"); if (d) return d;
  document.body.insertAdjacentHTML("beforeend", `<dialog class="a4dlg" id="a4dlg" aria-labelledby="a4-t">
    <div class="a4-in">
      <div class="a4-head"><div><h2 id="a4-t">Vista previa en hoja A4</h2><p class="hint" id="a4-n" aria-live="polite"></p></div>
        <div class="a4-acc"><button type="button" class="btn btn-primary btn-sm" id="a4-imp">Imprimir</button><button type="button" class="btn btn-sm" id="a4-pdf">Guardar como PDF</button><button type="button" class="linkbtn" id="a4-cerrar">Cerrar</button></div></div>
      <div class="a4-scroll" id="a4-scroll" tabindex="0" aria-label="Hojas del documento"><div class="a4-pags" id="a4-pags"></div></div>
      <p class="hint a4-nota">Márgenes de 18 mm arriba y abajo y 16 mm a los costados. «Imprimir» y «Guardar como PDF» sacan exactamente estas hojas; para el PDF, elegí «Guardar como PDF» en la ventana de impresión.</p>
    </div></dialog>`);
  d = $("a4dlg");
  const cerrar = () => { if (d.open){ if (d.close) d.close(); else d.removeAttribute("open"); } };
  $("a4-cerrar").addEventListener("click", cerrar);
  $("a4-imp").addEventListener("click", () => lpImprimirA4(false));
  $("a4-pdf").addEventListener("click", () => lpImprimirA4(true));
  d.addEventListener("click", e => { if (e.target === d) cerrar(); });
  d.addEventListener("close", () => { $("app").appendChild($("toast")); });
  addEventListener("resize", () => { if (d.open) lpZoomA4(); });
  return d;
}
function lpZoomA4(){
  const sc = $("a4-scroll"), P = $("a4-pags"); if (!sc || !P) return;
  const ancho = LP_A4.w * LP_MM + 24, z = Math.min(1, Math.max(0.3, (sc.clientWidth - 8) / ancho));
  P.style.zoom = String(Math.round(z * 1000) / 1000);
}
async function abrirVistaA4(){
  if (vistaEfectiva() === "slides"){ toast("La presentación para el aula no se arma en hojas A4. Elegí otra vista para verla así."); return; }
  try {
    renderDoc();
    const d = lpDlgA4(), P = $("a4-pags");
    P.innerHTML = `<p class="a4-cargando">Armando las hojas…</p>`;
    d.appendChild($("toast"));
    if (d.showModal) d.showModal(); else d.setAttribute("open", "");
    const pags = await lpPaginar(), N = pags.length;
    const pie = esc(temaVisible() || "");
    const fuente = $("doc").dataset.font || "serif";
    P.innerHTML = pags.map((p, i) => `<section class="a4-pag" aria-label="Hoja ${i + 1} de ${N}"><div class="paper a4-cont" data-font="${fuente}">${p.join("")}</div><footer class="a4-pie"><span>${pie}</span><span>Página ${i + 1} de ${N}</span></footer></section>`).join("");
    $("a4-n").textContent = N === 1 ? "Entra en 1 hoja." : `Ocupa ${N} hojas.`;
    lpZoomA4();
    $("a4-scroll").scrollTop = 0;
  } catch (e) { registrarError("abrirVistaA4", e); toast("No se pudo armar la vista previa. Probá con «Imprimir» o «PDF»."); }
}
function renderDoc(){
  renderDocV63();
  try { const sl = vistaEfectiva() === "slides"; ["btn-a4", "btn-a4m"].forEach(id => { const b = $(id); if (b) b.hidden = sl; }); } catch (e) { logSilencioso(e); }
}

/* ---------- Mis planificaciones: estado, buscador y filtros ---------- */
const LP_EST_KEY = "lapacho-estados-v1";
const LP_ESTADOS = [["borrador", "Borrador"], ["lista", "Lista"], ["entregada", "Entregada"]];
function lpEstados(){ try { const o = JSON.parse(localStorage.getItem(LP_EST_KEY) || "{}"); return o && typeof o === "object" ? o : {}; } catch (e) { return {}; } }
function lpEstado(id){ const e = lpEstados()[id]; return LP_ESTADOS.some(x => x[0] === e) ? e : "borrador"; }
function lpEstadoSetV64(id, v){ try { const o = lpEstados(); if (v === "borrador") delete o[id]; else o[id] = v; localStorage.setItem(LP_EST_KEY, JSON.stringify(o)); } catch (e) { toast("No se pudo guardar el estado: el navegador no deja guardar."); } }
const LP_TIPOS = [["", "Todos los tipos"], ["clase", "Clase"], ["secuencia", "Secuencia"], ["proyecto", "Proyecto"], ["anual", "Anual"]];
const lpTipo = d => ({proyecto:"proyecto", secuencia:"secuencia", anual:"anual"}[d.modo] || "clase");
function lpFiltrosHTML(lib){
  const F = state.libF || (state.libF = {q:"", tipo:"", mat:"", est:""});
  const mats = [...new Set(lib.map(e => e.data.v && e.data.v.materia).filter(Boolean))].map(m => [m, nombreMateria(m) || m]).sort((a, b) => a[1].localeCompare(b[1], "es"));
  const opt = (L, v) => L.map(([k, t]) => `<option value="${esc(k)}"${k === v ? " selected" : ""}>${esc(t)}</option>`).join("");
  return `<div class="lib-filtros" id="lib-filtros" role="search">
    <label class="lf-q"><span class="sr-only">Buscar en mis planificaciones</span><input type="search" id="lf-q" placeholder="Buscar por tema, espacio o curso" value="${esc(F.q)}" autocomplete="off"></label>
    <label><span class="sr-only">Tipo</span><select id="lf-tipo">${opt(LP_TIPOS, F.tipo)}</select></label>
    <label><span class="sr-only">Espacio curricular</span><select id="lf-mat">${opt([["", "Todos los espacios"], ...mats], F.mat)}</select></label>
    <label><span class="sr-only">Estado</span><select id="lf-est">${opt([["", "Todos los estados"], ...LP_ESTADOS], F.est)}</select></label>
  </div><p class="lib-cuenta" id="lib-cuenta" aria-live="polite"></p>`;
}
function renderLibV64(){
  const box = $("lib-list"); if (!box) return renderLibV63();
  try {
    const lib = libLeer().sort((a, b) => b.upd - a.upd), borrados = Object.values(state.libBorrados || {});
    const F = state.libF || (state.libF = {q:"", tipo:"", mat:"", est:""});
    let fb = $("lib-filtros");
    if (lib.length > 1 || F.q || F.tipo || F.mat || F.est){
      if (!fb){ box.insertAdjacentHTML("beforebegin", lpFiltrosHTML(lib)); fb = $("lib-filtros"); lpBindFiltros(); }
      else { const sel = $("lf-mat"), v = sel.value; const tmp = document.createElement("div"); tmp.innerHTML = lpFiltrosHTML(lib); sel.innerHTML = tmp.querySelector("#lf-mat").innerHTML; sel.value = v; }
    } else if (fb){ fb.remove(); const c = $("lib-cuenta"); if (c) c.remove(); }
    if (!lib.length && !borrados.length){ renderLibV63(); return; }
    const q = norm(F.q.trim());
    const vis = lib.filter(e => {
      const d = e.data, v = d.v || {};
      if (F.tipo && lpTipo(d) !== F.tipo) return false;
      if (F.mat && v.materia !== F.mat) return false;
      if (F.est && lpEstado(e.id) !== F.est) return false;
      if (q && !norm([tituloPlan(d), nombreMateria(v.materia), v.curso, anioSec(v.anio), v.tema, v.escuela].filter(Boolean).join(" ")).includes(q)) return false;
      return true;
    });
    const cuenta = $("lib-cuenta");
    if (cuenta) cuenta.textContent = vis.length === lib.length ? `${lib.length} planificaciones` : `Se ven ${vis.length} de ${lib.length}`;
    box.innerHTML = borrados.map(e => `<div class="lib-item del"><span>Borraste «${esc(tituloPlan(e.data))}».</span><button type="button" class="linkbtn" data-lib-undo="${e.id}">Deshacer</button></div>`).join("") +
      (lib.length && !vis.length ? `<div class="lib-vacio"><p>Ninguna planificación coincide con lo que elegiste.</p><button type="button" class="btn btn-sm" id="lf-limpiar">Ver todas</button></div>` : "") +
      vis.map(e => {
        const d = e.data, v = d.v, actual = e.id === state.planId, est = lpEstado(e.id);
        const meta = [nombreMateria(v.materia), v.curso || anioSec(v.anio), ({proyecto:"Proyecto", secuencia:"Secuencia", anual:"Anual"}[d.modo] || "Clase"), "editada " + fechaCorta(e.upd)].filter(Boolean).join(" · ");
        return `<div class="lib-item${actual ? " on" : ""}" data-est="${est}"><div class="lib-txt"><b>${esc(tituloPlan(d))}</b><small>${esc(meta)}</small></div>` +
          `<div class="lib-act"><label class="lib-est"><span class="sr-only">Estado de «${esc(tituloPlan(d))}»</span><select data-lib-estado="${e.id}">${LP_ESTADOS.map(([k, t]) => `<option value="${k}"${k === est ? " selected" : ""}>${t}</option>`).join("")}</select></label>` +
          `${actual ? `<span class="lib-tag">Abierta</span>` : `<button type="button" class="btn btn-sm" data-lib-abrir="${e.id}">Abrir</button>`}` +
          `<button type="button" class="btn btn-sm" data-lib-dup="${e.id}">Duplicar</button>` +
          (actual ? "" : `<button type="button" class="btn btn-sm lib-del" data-lib-del="${e.id}">Borrar</button>`) + `</div></div>`;
      }).join("");
  } catch (e) { registrarError("renderLib64", e, "aviso"); renderLibV63(); }
}
function lpBindFiltros(){
  const F = () => state.libF || (state.libF = {q:"", tipo:"", mat:"", est:""});
  let t = 0;
  $("lf-q").addEventListener("input", e => { F().q = e.target.value; clearTimeout(t); t = setTimeout(renderLib, 120); });
  [["lf-tipo", "tipo"], ["lf-mat", "mat"], ["lf-est", "est"]].forEach(([id, k]) => $(id).addEventListener("change", e => { F()[k] = e.target.value; renderLib(); }));
}

/* ---------- Inicio: seguí donde dejaste ---------- */
function lpRecientesHTML(){
  const L = libLeer().sort((a, b) => b.upd - a.upd).slice(0, 3);
  if (!L.length) return "";
  const nom = Object.fromEntries(LP_ESTADOS);
  return `<section class="pn-rec" aria-labelledby="pn-rec-t"><div class="pn-rec-h"><h2 id="pn-rec-t">Seguí donde dejaste</h2><button type="button" class="linkbtn" data-proxy="btn-lib">Ver todas</button></div><ul>${L.map(e => {
    const d = e.data, v = d.v || {}, est = lpEstado(e.id);
    return `<li><div><b>${esc(tituloPlan(d))}</b><small>${esc([nombreMateria(v.materia), v.curso || anioSec(v.anio), "editada " + fechaCorta(e.upd)].filter(Boolean).join(" · "))}</small></div><span class="lp-est" data-est="${est}">${nom[est]}</span><button type="button" class="btn btn-sm" data-rec-abrir="${e.id}">${e.id === state.planId ? "Seguir" : "Abrir"}</button></li>`;
  }).join("")}</ul></section>`;
}
function renderPanelV64(){
  renderPanelV63();
  try {
    const P = $("panel"); if (!P) return;
    P.querySelectorAll(".pn-rec").forEach(n => n.remove());
    const acc = P.querySelector(".pn-acc"); if (!acc) return;
    const h = lpRecientesHTML(); if (h) acc.insertAdjacentHTML("afterend", h);
    const L = libLeer(); if (!L.length) return;
    const borr = L.filter(e => lpEstado(e.id) === "borrador").length;
    const s = acc.querySelector('[data-proxy="btn-lib"] small');
    if (s && borr && borr < L.length) s.textContent += ` · ${borr} en borrador`;
  } catch (e) { registrarError("renderPanel64", e, "aviso"); }
}

function init74(){
  try {
    /* Vista A4: un botón en la barra del documento y otro en «Más» */
    const pdf = $("btn-pdf");
    if (pdf && !$("btn-a4")) pdf.insertAdjacentHTML("afterend", `<button type="button" class="btn" id="btn-a4">Vista A4</button>`);
    const pop = document.querySelector("#m-copiar .menu-pop");
    if (pop && !$("btn-a4m")) pop.insertAdjacentHTML("afterbegin", `<button type="button" role="menuitem" id="btn-a4m"><b>Vista previa en hoja A4</b><small>Cómo queda impreso, hoja por hoja</small></button>`);
    ["btn-a4", "btn-a4m"].forEach(id => { const b = $(id); if (b) b.addEventListener("click", abrirVistaA4); });
    /* Pasos */
    const fs = $("form-secs");
    if (fs){
      fs.addEventListener("toggle", e => {
        const d = e.target; if (!d.matches || !d.matches("details.sec") || !d.open) return;
        if (d.classList.contains("esen")) lpPasoActual = d.id;
        /* solo cuando la abrió la persona (no al cargar ni cuando otra función la abre) */
        if (lpPasoUno() && lpToque.d === d && Date.now() - lpToque.t < 1500) document.querySelectorAll("#form-secs details.sec[open]").forEach(o => { if (o !== d) o.open = false; });
        renderPasos();
      }, true);
      fs.addEventListener("click", e => { const s = e.target.closest("details.sec > summary"); if (s) lpToque = {d:s.parentElement, t:Date.now()}; }, true);
    }
    document.addEventListener("click", e => {
      const p = e.target.closest("[data-paso]"); if (p){ e.preventDefault(); lpIrPaso(p.dataset.paso, true); return; }
      const g = e.target.closest("[data-paso-ir]"); if (g){ e.preventDefault(); lpIrPaso(g.dataset.pasoIr, true); return; }
      const r = e.target.closest("[data-rec-abrir]");
      if (r){ const x = libLeer().find(y => y.id === r.dataset.recAbrir); if (!x) return; if (x.id === state.planId){ if (document.querySelector(".app.nav-desk")) irDesk("plan"); setView("form"); return; } save(); cargarPlan(x, x.id); toast(`Abriste «${tituloPlan(x.data)}».`); return; }
      if (e.target.closest("#lf-limpiar")){ state.libF = {q:"", tipo:"", mat:"", est:""}; const f = $("lib-filtros"); if (f) f.remove(); const c = $("lib-cuenta"); if (c) c.remove(); renderLib(); }
    });
    document.addEventListener("change", e => {
      const s = e.target.closest && e.target.closest("[data-lib-estado]"); if (!s) return;
      lpEstadoSet(s.dataset.libEstado, s.value);
      const it = s.closest(".lib-item"); if (it) it.dataset.est = s.value;
      if (state.libF && state.libF.est) renderLib();
    });
    progresoFormulario();
    renderDoc();
  } catch (e) { registrarError("init74", e, "aviso"); }
}

/* ============================================================
   Versión 65: menú lateral en la tablet acostada y registro de actividad
   - Tablet con pantalla táctil de 1000 px o más (acostada): usa el diseño de computadora con el menú
     lateral como cajón que se abre con «Menú» y se cierra al elegir, al tocar afuera o con Escape.
     Parada (menos de 1000 px) sigue con la barra de abajo.
   - Actividad: Lapacho anota cuándo empezaste una planificación, cuándo cambiaste su estado y cuándo
     descargaste el Word o el PDF (clave aparte lapacho-actividad-v1, solo en este navegador).
   - La copia descargada de Mis planificaciones lleva también el estado de cada una.
   ============================================================ */

/* ---------- Registro de actividad ---------- */
const LP_ACT_KEY = "lapacho-actividad-v1", LP_ACT_MAX = 80;
function lpActividad(){ try { const a = JSON.parse(localStorage.getItem(LP_ACT_KEY) || "[]"); return Array.isArray(a) ? a.filter(x => x && x.t && x.ev) : []; } catch (e) { return []; } }
function lpAnotar(ev, id, det){
  try {
    if (!id) return;
    const e = libLeer().find(x => x.id === id);
    const tit = e ? tituloPlan(e.data) : (id === state.planId ? tituloPlan(foto()) : "");
    const A = lpActividad();
    /* el mismo hecho repetido en menos de un minuto cuenta una sola vez */
    if (A[0] && A[0].ev === ev && A[0].id === id && (A[0].det || "") === (det || "") && Date.now() - A[0].t < 60000) A.shift();
    A.unshift({t:Date.now(), ev, id, tit, det:det || ""});
    localStorage.setItem(LP_ACT_KEY, JSON.stringify(A.slice(0, LP_ACT_MAX)));
  } catch (e) { logSilencioso(e); }
}
function lpActTexto(a){
  const t = `«${a.tit || "Sin tema"}»`;
  switch (a.ev){
    case "creada": return `Empezaste ${t}`;
    case "lista": return `Marcaste ${t} como lista`;
    case "entregada": return `Marcaste ${t} como entregada`;
    case "borrador": return `Volviste ${t} a borrador`;
    case "pdf": return a.det ? `Descargaste ${a.det} de ${t} en PDF` : `Descargaste el PDF de ${t}`;
    case "impresion": return a.det === "pdf" ? `Abriste «Guardar como PDF» de ${t}` : `Abriste la impresión de ${t}`;
    case "word": return a.det ? `Descargaste ${a.det} de ${t} en Word` : `Descargaste el Word de ${t}`;
    default: return t;
  }
}
const lpFechaHora = ts => { const d = new Date(ts); return d.toLocaleDateString("es-AR", {day:"numeric", month:"short"}) + ", " + d.toLocaleTimeString("es-AR", {hour:"2-digit", minute:"2-digit"}); };
function lpCuandoEstado(id, ev){ const a = lpActividad().find(x => x.id === id && x.ev === ev); return a ? a.t : 0; }
function lpEstadoSet(id, v){
  const antes = lpEstado(id);
  lpEstadoSetV64(id, v);
  if (antes !== v && lpEstado(id) === v) lpAnotar(v, id);
}
let lpConocidos = null;
function libActualizarV68(){
  libActualizarV64();
  try {
    const id = state.planId; if (!id) return;
    if (!lpConocidos) lpConocidos = new Set(libLeer().map(x => x.id));
    if (lpConocidos.has(id)) return;
    if (libLeer().some(x => x.id === id)){ lpConocidos.add(id); lpAnotar("creada", id); }
  } catch (e) { logSilencioso(e); }
}
let lpDescarga = "";
function lpDescargaOk(){
  if (!lpDescarga || !state.planId) return;
  const vis = {ficha:"la ficha para estudiantes", inst:"los instrumentos de evaluación", registro:"el registro de clase", libreto:"el libreto"}[vistaEfectiva()] || "";
  lpAnotar(lpDescarga, state.planId, vis);
}
async function descargarPDF(){ lpDescarga = "pdf"; try { await descargarPDFV64(); } finally { lpDescarga = ""; } }
async function descargarWord(){ lpDescarga = vistaEfectiva() === "slides" ? "" : "word"; try { await descargarWordV64(); } finally { lpDescarga = ""; } }
function lpEstadosImportar(E, lib){
  try {
    if (!E || typeof E !== "object") return;
    const o = lpEstados(), ids = new Set((lib || libLeer()).map(x => x.id)); let n = 0;
    Object.entries(E).forEach(([id, v]) => { if (ids.has(id) && !o[id] && LP_ESTADOS.some(x => x[0] === v) && v !== "borrador"){ o[id] = v; n++; } });
    if (n) localStorage.setItem(LP_EST_KEY, JSON.stringify(o));
  } catch (e) { logSilencioso(e); }
}
function lpActividadHTML(max, cls){
  const A = lpActividad().slice(0, max);
  if (!A.length) return "";
  return `<ol class="${cls}">${A.map(a => `<li><span>${esc(lpActTexto(a))}</span><time datetime="${new Date(a.t).toISOString()}">${esc(lpFechaHora(a.t))}</time></li>`).join("")}</ol>`;
}
function renderLibV67(){
  renderLibV64();
  try {
    /* fecha en que quedó lista o entregada */
    document.querySelectorAll("#lib-list .lib-item select[data-lib-estado]").forEach(s => {
      const v = s.value; if (v === "borrador") return;
      const t = lpCuandoEstado(s.dataset.libEstado, v); if (!t) return;
      const sm = s.closest(".lib-item").querySelector(".lib-txt small");
      if (sm && !sm.querySelector(".lib-cuando")) sm.insertAdjacentHTML("beforeend", `<span class="lib-cuando"> · ${v === "lista" ? "lista" : "entregada"} el ${esc(new Date(t).toLocaleDateString("es-AR", {day:"numeric", month:"short"}))}</span>`);
    });
    const lib = $("lib"); if (!lib) return;
    let reg = $("lib-actividad");
    const html = lpActividadHTML(15, "lib-act-l");
    if (!html){ if (reg) reg.remove(); return; }
    if (!reg){
      const foot = lib.querySelector(".lib-foot");
      (foot || $("lib-list")).insertAdjacentHTML(foot ? "beforebegin" : "afterend", `<details class="lib-actividad" id="lib-actividad"><summary>Actividad reciente</summary><div class="lib-act-c"></div><p class="hint">Se anota sola en este navegador: cuándo empezaste cada planificación, cuándo cambiaste su estado y cuándo la descargaste.</p></details>`);
      reg = $("lib-actividad");
    }
    reg.querySelector(".lib-act-c").innerHTML = html;
  } catch (e) { registrarError("renderLib65", e, "aviso"); }
}
function renderPanelV67(){
  renderPanelV64();
  try {
    const R = document.querySelector("#panel .pn-rec"); if (!R) return;
    const html = lpActividadHTML(4, "pn-act-l"); if (!html) return;
    R.insertAdjacentHTML("beforeend", `<h3 class="pn-act-t">Lo último que hiciste</h3>${html}`);
  } catch (e) { registrarError("renderPanel65", e, "aviso"); }
}

/* ---------- Tablet acostada: menú lateral como cajón ---------- */
const LP_CAJON_MQ = window.matchMedia ? window.matchMedia("(pointer:coarse) and (max-width:1279px)") : {matches:false, addEventListener(){}};
function lpCajonAbierto(on, foco){
  const app = document.querySelector(".app"); if (!app) return;
  on = !!on && app.classList.contains("nav-cajon");
  app.classList.toggle("cajon-abierto", on);
  let v = $("sn-velo");
  if (!v){ document.body.insertAdjacentHTML("beforeend", `<div id="sn-velo" hidden></div>`); v = $("sn-velo"); v.addEventListener("click", () => lpCajonAbierto(false, true)); }
  v.hidden = !on;
  const S = $("sidenav"); if (S) S.inert = app.classList.contains("nav-cajon") && !on;
  const a = $("sn-abrir"); if (a) a.setAttribute("aria-expanded", String(on));
  const o = document.querySelector(".sn-ocultar"); if (o) o.textContent = app.classList.contains("nav-cajon") ? "Cerrar el menú" : "Ocultar el menú";
  if (foco){ if (on){ const p = S && S.querySelector(".sn-ocultar, button, a"); if (p) p.focus(); } else if (a) a.focus(); }
}
function lpAplicarCajon(){
  const app = document.querySelector(".app"); if (!app) return;
  const on = app.classList.contains("nav-desk") && LP_CAJON_MQ.matches;
  const era = app.classList.contains("nav-cajon");
  app.classList.toggle("nav-cajon", on);
  if (on){ app.classList.add("nav-oculto"); lpCajonAbierto(app.classList.contains("cajon-abierto")); }
  else if (era){ app.classList.remove("cajon-abierto"); lpCajonAbierto(false); lpMenuOculto(!!leerPref().menuOculto); }
}
function aplicarDesk(){
  aplicarDeskV64();
  try { lpAplicarCajon(); } catch (e) { registrarError("aplicarDesk65", e, "aviso"); }
}

function init75(){
  try {
    /* los botones «Menú» y «Ocultar el menú» abren y cierran el cajón cuando corresponde */
    document.addEventListener("click", e => {
      const app = document.querySelector(".app.nav-cajon"); if (!app) return;
      if (e.target.closest("#sn-abrir")){ e.preventDefault(); e.stopPropagation(); lpCajonAbierto(!app.classList.contains("cajon-abierto"), true); return; }
      if (e.target.closest(".sn-ocultar")){ e.preventDefault(); e.stopPropagation(); lpCajonAbierto(false, true); return; }
      /* elegir una opción del menú lo cierra; abrir o cerrar un grupo, no */
      const b = e.target.closest("#sidenav button, #sidenav a");
      if (b && app.classList.contains("cajon-abierto") && !b.closest("summary")) setTimeout(() => lpCajonAbierto(false), 0);
    }, true);
    document.addEventListener("keydown", e => { if (e.key === "Escape" && document.querySelector(".app.cajon-abierto") && !document.querySelector("dialog[open]")){ e.preventDefault(); lpCajonAbierto(false, true); } });
    if (LP_CAJON_MQ.addEventListener) LP_CAJON_MQ.addEventListener("change", aplicarDesk);
    lpAplicarCajon();
    /* «Mis planificaciones» se vuelve a dibujar al abrir: así la actividad está al día */
    const panel = $("panel"); if (panel && document.querySelector(".app.nav-desk")) renderPanel();
  } catch (e) { registrarError("init75", e, "aviso"); }
}

/* ============================================================
   Versión 66: banco de actividades por espacio curricular y por tema, y perfil en el encabezado
   - Mis actividades (banco): filtro por espacio curricular y opción «Agrupar por tema» (pref bancoAgrupar, activa de entrada).
     Los datos del banco no cambian: se usan los campos materia y tema que ya tenía cada actividad.
   - Computadora: a la derecha del encabezado, tu nombre con sus iniciales; lleva al inicio para cambiarlo.
   ============================================================ */
let lpBancoMat = "";
function lpBancoItemHTML(x, dest, opts){
  return `<div class="lib-item banco-item"><div class="lib-txt"><b>${esc(x.tema || "Sin tema")}</b><small>${esc([nombreMateria(x.materia), x.origen, fechaCorta(x.fecha)].filter(Boolean).join(" · "))}</small><pre>${esc(x.texto)}</pre></div>` +
    `<div class="lib-act">${dest.length ? `<label class="sr-only" for="bd-${x.id}">Agregar a</label><select id="bd-${x.id}" class="banco-dest">${opts}</select><button type="button" class="btn btn-sm" data-bancoadd="${x.id}">Agregar</button>` : ""}<button type="button" class="btn btn-sm lib-del" data-bancodel="${x.id}">Borrar</button></div></div>`;
}
function renderBanco(){
  const list = $("banco-list"), q0 = $("banco-q");
  if (!list || !q0) return renderBancoV65();
  try {
    const todo = bancoLeer();
    const mats = [...new Set(todo.map(x => x.materia).filter(Boolean))].map(m => [m, nombreMateria(m) || m]).sort((a, b) => a[1].localeCompare(b[1], "es"));
    if (lpBancoMat && !mats.some(m => m[0] === lpBancoMat)) lpBancoMat = "";
    let fb = $("banco-filtros");
    if (!fb){
      q0.insertAdjacentHTML("afterend", `<div class="banco-filtros" id="banco-filtros"><label><span class="sr-only">Espacio curricular</span><select id="banco-mat"></select></label><label class="pasos-uno"><input type="checkbox" id="banco-agr"> Agrupar por tema</label></div><p class="lib-cuenta" id="banco-cuenta" aria-live="polite"></p>`);
      fb = $("banco-filtros");
      $("banco-mat").addEventListener("change", e => { lpBancoMat = e.target.value; renderBanco(); });
      $("banco-agr").addEventListener("change", e => { prefSet("bancoAgrupar", e.target.checked); renderBanco(); });
    }
    fb.hidden = todo.length < 2;
    $("banco-mat").innerHTML = [["", "Todos los espacios"], ...mats].map(([k, t]) => `<option value="${esc(k)}"${k === lpBancoMat ? " selected" : ""}>${esc(t)}</option>`).join("");
    const agr = leerPref().bancoAgrupar !== false; $("banco-agr").checked = agr;
    const q = norm(val("banco-q"));
    const b = todo.filter(x => (!lpBancoMat || x.materia === lpBancoMat) && (!q || norm(x.texto + " " + x.tema + " " + nombreMateria(x.materia)).includes(q)));
    const cuenta = $("banco-cuenta");
    if (cuenta) cuenta.textContent = todo.length < 2 ? "" : b.length === todo.length ? `${todo.length} actividades guardadas` : `Se ven ${b.length} de ${todo.length}`;
    if (!b.length){
      list.innerHTML = todo.length ? `<div class="lib-vacio"><p>No hay actividades con ese filtro.</p><button type="button" class="btn btn-sm" id="banco-limpiar">Ver todas</button></div>`
        : `<p class="lib-empty">Todavía no guardaste actividades. Usá «Guardar en el banco» junto a las actividades o escribí una nueva acá abajo.</p>`;
      return;
    }
    const dest = destinosBanco(), opts = dest.map(d => `<option value="${d}">${esc(etiquetaCampo(d))}</option>`).join("");
    if (!agr){ list.innerHTML = b.map(x => lpBancoItemHTML(x, dest, opts)).join(""); return; }
    const G = new Map();
    b.forEach(x => { const k = (x.tema || "").trim() || "Sin tema"; const kk = norm(k); if (!G.has(kk)) G.set(kk, {t:k, xs:[]}); G.get(kk).xs.push(x); });
    list.innerHTML = [...G.values()].sort((a, c) => a.t === "Sin tema" ? 1 : c.t === "Sin tema" ? -1 : a.t.localeCompare(c.t, "es")).map(g =>
      `<section class="banco-grupo" aria-label="${esc(g.t)}"><h3 class="banco-gt">${esc(g.t)} <span>${g.xs.length}</span></h3>${g.xs.map(x => lpBancoItemHTML(x, dest, opts)).join("")}</section>`).join("");
  } catch (e) { registrarError("renderBanco66", e, "aviso"); renderBancoV65(); }
}
function lpIniciales(n){ return String(n || "").trim().split(/\s+/).filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase()).join(""); }
function lpPintarPerfil(){
  const tools = document.querySelector(".topbar .tools"); if (!tools) return;
  let p = $("lp-perfil");
  if (!p){
    tools.insertAdjacentHTML("beforeend", `<button type="button" class="lp-perfil" id="lp-perfil"><span class="lp-ini" aria-hidden="true"></span><span class="lp-nom"></span></button>`);
    p = $("lp-perfil");
    p.addEventListener("click", () => {
      if (document.querySelector(".app.nav-desk")) irDesk("inicio");
      try { TD_NOM.abierto = true; renderTuDia(); } catch (e) { logSilencioso(e); }
      const i = $("td-nom-in"); if (i){ i.value = nombreDocente(); i.focus(); i.select(); }
    });
  }
  const n = nombreDocente();
  p.querySelector(".lp-ini").textContent = lpIniciales(n) || "";
  p.querySelector(".lp-ini").classList.toggle("vacio", !n);
  p.querySelector(".lp-nom").textContent = n || "Tu nombre";
  p.setAttribute("aria-label", n ? `Tu perfil: ${n}. Cambiar el nombre` : "Poné tu nombre para que Lapacho te salude");
}
function init76(){
  try {
    document.addEventListener("click", e => { if (e.target.closest("#banco-limpiar")){ lpBancoMat = ""; const q = $("banco-q"); if (q) q.value = ""; renderBanco(); } });
    lpPintarPerfil();
    /* el nombre se guarda desde «Tu día»: al enviarlo, se actualiza el encabezado */
    const alNombre = () => setTimeout(() => { const antes = $("lp-perfil") && $("lp-perfil").querySelector(".lp-nom").textContent; lpPintarPerfil(); const ahora = nombreDocente() || "Tu nombre"; if (antes !== ahora && document.querySelector(".app.nav-desk") && document.querySelector('.app[data-dsec="inicio"]')) renderPanel(); }, 50);
    document.addEventListener("submit", alNombre, true);
    document.addEventListener("click", e => { if (e.target.closest("[data-tdnom]")) alNombre(); });
  } catch (e) { registrarError("init76", e, "aviso"); }
}

