function ciLeer(){ try { const o = JSON.parse(localStorage.getItem(CI_KEY) || "{}"); return o && typeof o === "object" ? o : {}; } catch (e) { return {}; } }
function ciSet(k, v){ try { const o = ciLeer(); o[k] = v; localStorage.setItem(CI_KEY, JSON.stringify(o)); } catch (e) { logSilencioso(e); } }
const ciFecha = iso => { if (!/^\d{4}-\d{2}-\d{2}$/.test(iso || "")) return ""; const d = fechaDe(iso); return d.toLocaleDateString("es-AR", {weekday:"long", day:"numeric", month:"numeric", year:"numeric"}); };
function ciRango(d, h){ const a = ciFecha(d), b = ciFecha(h); return a && b ? `del ${a} al ${b}` : a ? `desde el ${a}` : b ? `hasta el ${b}` : ""; }
function ciFaltan(){ try { const r = diasDeClaseRestantes(); return r && !r.antes && !r.despues ? r : null; } catch (e) { return null; } }
function htmlCierreAnio(){
  const D = ciLeer(), T = D.tareas || {}, r = ciFaltan();
  const fu = k => { const f = CI_FUENTES[k]; return f ? `<a href="${esc(f[1])}" target="_blank" rel="noopener">${esc(f[0])}</a>` : ""; };
  const hechas = CI_TAREAS.filter(([k]) => T[k]).length;
  return `${r ? `<p class="ci-cuenta"><b>${r.n}</b> ${r.n === 1 ? "día de clase" : "días de clase"} hasta el viernes 18 de diciembre${r.mios != null ? `, ${r.mios} con tus cursos` : ""}.</p>` : ""}
    <h3 class="sv-g">Fechas</h3>
    <div class="gr-tw"><table class="ci-tab"><thead><tr><th scope="col">Qué</th><th scope="col">Cuándo</th><th scope="col">Estado</th></tr></thead><tbody>
      ${CI_FIJAS.map(x => `<tr><th scope="row">${esc(x.t)}</th><td>${esc(x.f ? ciFecha(x.f) : x.txt)}</td><td><span class="ci-est" data-est="${x.est}">${CI_EST[x.est]}</span><small>${fu(x.fu)}</small></td></tr>`).join("")}
    </tbody></table></div>
    <h3 class="sv-g">Las fechas de tu escuela</h3>
    <p class="hint">El acompañamiento, las mesas y la entrega de notas los fija cada escuela y no están publicados por el Ministerio. Cargalos acá: se usan en los avisos a las familias.</p>
    <div class="ci-grid">${CI_EDIT.map(([k, l]) => `<div class="f"><label for="ci-${k}">${esc(l)}</label><input type="date" id="ci-${k}" data-ci="${k}" value="${esc(D[k] || "")}"></div>`).join("")}</div>
    <h3 class="sv-g">Lo que falta (${hechas} de ${CI_TAREAS.length})</h3>
    <ul class="ci-tareas">${CI_TAREAS.map(([k, t, ir]) => `<li><label><input type="checkbox" data-citarea="${k}"${T[k] ? " checked" : ""}> ${esc(t)}</label>${ir ? `<button type="button" class="linkbtn" data-ciir="${ir}">Ir</button>` : ""}</li>`).join("")}</ul>
    <h3 class="sv-g">2027</h3>
    <ul class="ci-2027">
      <li>El calendario escolar 2027 de Tucumán todavía no se publicó (al 21/11/2026). El de 2026 se difundió el 22 de enero.</li>
      <li>El Consejo Federal de Educación aprobó el 6/11/2026 el marco del calendario 2027: un piso de 190 días de clase, o 900 horas reloj en secundaria. La resolución se publica en diciembre. ${fu("cfe")}</li>
      <li>Anunciado por la ministra (periodístico, a verificar): inicio el 1 de marzo de 2027 y más horas en escuelas primarias. ${fu("ctx")}</li>
    </ul>
    <p class="hint">Normativa de evaluación y promoción de secundaria (Res. 1222, 1223 y 1224/5 MEd y modificatorias): ${fu("sec")}. Escala, nota de aprobación y tope de inasistencias se configuran en cada curso (Mi curso › Datos del curso): confirmalos con tu escuela.</p>`;
}
