/* ---------- avisos a las familias (Mi curso › Cierre) ---------- */
function modeloAvisoFamilias(c, inst){
  const D = ciLeer(), dic = inst === "dic";
  const al = alumnosActivos(c).filter(a => { try { return condicion(c, a.id).k === inst; } catch (e) { return false; } });
  const aco = dic ? ciRango(D.acoDicD, D.acoDicH) : ciRango(D.acoFebD, D.acoFebH), mesa = ciFecha(dic ? D.mesaDic : D.mesaFeb);
  const secs = al.map((a, k) => {
    const cont = itemsLista(((c.recup || {})[a.id] || {}).cont || "").filter(Boolean), lista = cont.length ? cont : contenidosSugeridos(c);
    return {h:a.n, pageBreak:k > 0, lead:`${nombreMateria(c.materia)} · ${c.curso} · Ciclo lectivo ${c.ciclo || ""}`,
      body:[`Señora, señor, familia de ${a.n}:`, "",
        `Les informamos que ${a.n} todavía no aprobó ${nombreMateria(c.materia)} y la tiene que completar en la instancia de ${dic ? "diciembre" : "febrero y marzo"}.`,
        `Período de acompañamiento: ${aco || "las fechas las confirma la escuela"}.`,
        `Evaluación: ${mesa ? "el " + mesa : "la fecha la confirma la escuela"}.`, "",
        "Contenidos que tiene que recuperar:", toList(lista), "",
        "Le pedimos que asista a todos los encuentros y que traiga la carpeta. Cualquier consulta, acérquense a la escuela.", "",
        "Firma del docente: ............................................     Firma de la familia (notificada): ............................................"].join("\n")};
  });
  return {inst:c.escuela, titulo:"Aviso a la familia", subtitulo:`Instancia de ${dic ? "diciembre" : "febrero y marzo"}`, faltaSub:"Instancia",
    datos:[["Espacio curricular", nombreMateria(c.materia)], ["Curso", c.curso], ["Docente", c.docente || val("docente") || ""]], secs, firmas:null};
}
function htmlCierre(c){
  const h = htmlCierreV71(c);
  try {
    if (!alumnosActivos(c).length) return h;
    const n = k => alumnosActivos(c).filter(a => { try { return condicion(c, a.id).k === k; } catch (e) { return false; } }).length, nD = n("dic"), nF = n("feb");
    const D = ciLeer(), faltan = !(D.acoDicD || D.mesaDic);
    return h + `<details class="cur-sub" id="ci-fam"><summary>Aviso a las familias (diciembre y febrero)</summary>
      <p class="hint">Una hoja por estudiante, con los contenidos a recuperar, las fechas del acompañamiento y de la evaluación, y un espacio para la firma de la familia.${faltan ? ` Las fechas se toman de <button type="button" class="linkbtn" data-proxy="btn-cierre">Cierre del año</button>: si no las cargaste, dice que las confirma la escuela.` : ""}</p>
      <div class="cur-bar"><button type="button" class="btn btn-sm btn-primary" data-cifam="dic"${nD ? "" : " disabled"}>Diciembre (${nD})</button><button type="button" class="btn btn-sm" data-cifam="feb"${nF ? "" : " disabled"}>Febrero (${nF})</button></div></details>`;
  } catch (e) { registrarError("htmlCierre72", e, "aviso"); return h; }
}
