function init59(){
  try {
    const b = $("btn-diasesc"); if (b) b.addEventListener("click", abrirDE);
    const D = $("diasesc");
    if (D && !D.dataset.ok){
      D.dataset.ok = "1";
      D.addEventListener("change", e => { if (e.target.id === "de-imp"){ const f = e.target.files && e.target.files[0]; const copia = f ? new File([f], f.name, {type:f.type}) : null; e.target.value = ""; deImportar(copia); } });
      D.addEventListener("click", e => {
        const a = e.target.closest("[data-de]"), q = e.target.closest("[data-dequitar]");
        if (a && a.dataset.de === "agregar") deAgregar();
        else if (a && a.dataset.de === "ics") deIcs();
        else if (a && a.dataset.de === "exp") deExportar();
        else if (a && a.dataset.de === "imp"){ const f = $("de-imp"); if (f) f.click(); }
        else if (q){ prefSet("diasEsc", deLeer().filter(x => x.id !== q.dataset.dequitar)); renderDE(); try { renderTuDia(); } catch (err) { logSilencioso(err); } const f = $("de-desde"); if (f) f.focus(); }
      });
    }
    const LCD = $("licalc");
    if (LCD && !LCD.dataset.ok59){
      LCD.dataset.ok59 = "1";
      LCD.addEventListener("click", e => {
        if (e.target.closest("[data-lcnota]") && LC.r){ bajarDoc(modeloNotaLic(LC.r), `nota-pedido-licencia-${LC.r.ini}`, "docx", "Nota descargada. Revisala, firmala y presentala en la dirección."); return; }
        if (e.target.closest("[data-lcsupl]")){ const s = $("btn-suplente"); if (s) s.click(); }
      });
    }
    document.addEventListener("click", e => {
      const t = e.target.closest('[data-tdact="muestra"], [data-tdact="diasesc"]');
      if (t){ e.stopImmediatePropagation(); if (t.dataset.tdact === "muestra") abrirMuestra(); else abrirDE(); return; }
      const r = e.target.closest("[data-tdrep]");
      if (r){ e.stopImmediatePropagation(); repasarDeHoy(r.dataset.tdrep); return; }
      const mu = e.target.closest("[data-mu59]");
      if (mu){ muIcs(); return; }
      const m = e.target.closest('#muestra [data-mu="docx"], #muestra [data-mu="pdf"]');
      if (m && muDatos().doc === "carteles"){ e.stopImmediatePropagation(); e.preventDefault(); if (m.dataset.mu === "docx") muCartelesDocx(); else muCartelesPdf(); return; }
      const ac = e.target.closest("[data-acp]");
      if (ac){ e.stopImmediatePropagation(); const c = cursoSel(); if (c) acpBajar(c, ac.dataset.acp); }
    }, true);
    document.addEventListener("change", e => {
      if (e.target && /^acp-(inst|desde|hasta)$/.test(e.target.id)) ACP[e.target.id.slice(4)] = e.target.value;
    });
  } catch (e) { registrarError("init59", e, "aviso"); }
}

